window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cirurgia-cir-3"]={"block":"medcurso:medcurso-cirurgia-cir-3","label":"Medcurso · CIR 3","count":411,"questions":[{"id":"medcurso-cirurgia-cir-3-343816","number":"343816","sourceNumber":"343816","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente proveniente do Bujari - AC, sexo masculino, 45 anos, tabagista e hipertenso,\ndá entrada no HUERB relatando que há 5 anos\napresenta abaulamento em região umbilical, sem\nqueixas. Há 2 meses refere aumento do volume, apresentando há 8 horas dor em região\nmesogastrica, abaulamento irredutível, associado a náuseas e vômitos incoercíveis. Ao exame\nfísico, nota-se nodulação em região umbilical, com sinais de hiperemia e hipertermia, não sendo\npossível realizar redução manual devido à dor. No USG de parede, apresenta anel herniário de 2cm\ncom grande volume de alças em saco herniário, ao Doppler não apresenta fluxo. De acordo com o\ncaso clínico, qual a melhor conduta:","options":{"A":"SNG aberta, analgesia plena e hidratação.","B":"Analgesia e redução manual.","C":"Laparotomia exploradora.","D":"Solicitar Tomografia computadorizada."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343818","number":"343818","sourceNumber":"343818","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Pac. ?, 19 anos, sob efeito de álcool, adentrou num açude e foi atacado por um jacaré,\napresentando lacerações em todo comprimento da face lateral do antebraço esquerdo. Qual a\nconduta com relação a essa lesão?","options":{"A":"Limpeza exaustiva com clorexedine e sutura da lesão; profilaxia do tétano.","B":"Limpeza, desbridamento e aproximação dos bordos da lesão; profilaxia do tétano\nantibioticoterapia.","C":"Limpeza e sutura da lesão; profilaxia do tétano; antibioticoterapia.","D":"Limpeza, desbridamento e sutura da lesão; profilaxia do tétano; antibioticoterapia."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343820","number":"343820","sourceNumber":"343820","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Pac. ?, 20 anos, no 1º dia de pós-operatório de uma herniorrafia inguinal esquerda, foi\nobservado uma extensa equimose na região operada. Qual a conduta?","options":{"A":"Exploração da ferida no centro-cirúrgico.","B":"Punção aspirativa.","C":"Compressas frias.","D":"Expectante."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345505","number":"345505","sourceNumber":"345505","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hérnia da parede abdominal cujo conteúdo é divertículo de Meckel é a hérnia de:","options":{"A":"Richter.","B":"Spiegel.","C":"Littré.","D":"Grynfeltt."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345514","number":"345514","sourceNumber":"345514","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação à classificação das feridas cirúrgicas de acordo com o grau de\ncontaminação, como se classifica uma\nlaparotomia exploradora em decorrência de um ferimento\nabdominal penetrante por arma branca?","options":{"A":"Limpa.","B":"Potencialmente contaminada.","C":"Contaminada.","D":"Infectada ou suja."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345518","number":"345518","sourceNumber":"345518","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As cirurgias potencialmente contaminadas são:","options":{"A":"Realizadas em tecidos de difícil descontaminação, na ausência de supuração local, com\npenetração nos tratos digestório, respiratório ou urinário sem contaminação significativa.","B":"Realizadas em tecidos recentemente traumatizados e abertos, de difícil descontaminação, com\nprocesso inflamatório, mas sem supuração.","C":"Realizadas em tecidos estéreis ou de fácil descontaminação, na ausência de processo\ninfeccioso local, sem penetração nos tratos\ndigestório, respiratório ou urinário, em condições ideais\nde sala de cirurgia.","D":"Realizadas em tecido com supuração local, tecido necrótico, feridas traumáticas sujas."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345519","number":"345519","sourceNumber":"345519","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considere que uma criança de 7 anos de idade é submetida a laparotomia exploradora\npara esclarecimento diagnóstico de dor abdominal.\nApós cerca de 30 minutos do início da\nanestesia, nota-se hiperpirexia (42 ºC), taquicardia, rigidez e cianose. Exames laboratoriais\nrevelam\nhipercalcemia, hipercalemia e acidose metabólica. O diagnóstico mais provável para essa condição\né:","options":{"A":"Síndrome maligna associada aos neurolépticos.","B":"Reação anafilática.","C":"Hipertermia maligna.","D":"Processo infeccioso não diagnosticado no pré-operatório."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283328","number":"283328","sourceNumber":"283328","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente foi submetido à hernioplastia inguinal à Linchtenstein, foi utilizado\ncefazolina 1g IV imediatamente antes do\nbloqueio anestésico. No retorno ambulatorial apresenta\numa equimose extensa em bolsa escrotal. Qual a conduta?","options":{"A":"Reabordagem cirúrgica.","B":"Drenagem com dreno de Penrose.","C":"Solicitar doppler de bolsa escrotal.","D":"Conduta expectante."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-247218","number":"247218","sourceNumber":"247218","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. Fístula\ngastrointestinal de baixo débito é quando apresenta drenagem em 24 horas inferior a:","options":{"A":"300 mL/dia.","B":"1.000 mL/dia.","C":"500 mL/dia.","D":"200 mL/dia.","E":"400 mL/dia."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-251938","number":"251938","sourceNumber":"251938","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente foi submetido à hernioplastia inguinal à Linchtenstein, foi utilizado\ncefazolina 1g IV imediatamente antes do\nbloqueio anestésico. No retorno ambulatorial apresenta\numa equimose extensa em bolsa escrotal. Qual a conduta?","options":{"A":"Reabordagem cirúrgica.","B":"Drenagem com dreno de Penrose.","C":"Solicitar Doppler de bolsa escrotal.","D":"Conduta expectante."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-251942","number":"251942","sourceNumber":"251942","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das seguintes associações tem indicação cirúrgica mais urgente pelo risco e\ngravidade das complicações?","options":{"A":"Criptorquidia em criança de 7 anos.","B":"Hérnia inguinal esquerda em lactente de 3 meses.","C":"Hidrocele em criança de 5 anos.","D":"Fimose em lactente de 9 meses."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-251950","number":"251950","sourceNumber":"251950","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Aumenta a incidência de náuseas e vômitos em anestesias para cirurgia ambulatorial\nde adultos:","options":{"A":"Ingestão de água até 2 horas antes da indução de anestesia.","B":"Tabagismo.","C":"Propofol.","D":"Sexo feminino entre o 1º e o 7º dia do ciclo menstrual."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-217664","number":"217664","sourceNumber":"217664","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente sexo feminino, 35 anos, IMC 36,5 kg/m², foi submetida à colecistectomia\nvideolaparoscópica sem intercorrências e\nalta no mesmo dia. No retorno ambulatorial, no 7º dia de\npós-operatório, havia saída de secreção serosa pela ferida operatória do porto umbilical. Qual o\ntratamento?","options":{"A":"Iniciar antibioticoterapia.","B":"Exploração cirúrgica da ferida.","C":"Drenagem da ferida com dreno de Penrose.","D":"Apenas orientar expressão da ferida operatória."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183205","number":"183205","sourceNumber":"183205","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à parede abdominal e às incisões, assinale a alternativa INCORRETA.","options":{"A":"Incisões transversais resultam em menor número de eviscerações que incisões longitudinais, em\ndecorrência das linhas de tensão da parede abdominal.","B":"Incisões realizadas por bisturi de lâmina ou eletrocautério apresentam mesmo número de\ncomplicações de ferida operatória.","C":"A síntese do peritônio é desnecessária independente do tipo de incisão realizada.","D":"A síntese da parede abdominal com sutura contínua utilizando fio monofilamentar absorvível de\nlonga permanência, resulta em menor índice de hérnia incisional.","E":"Infecção do sítio cirúrgico é o principal fator de risco para deiscência da aponeurose."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183172","number":"183172","sourceNumber":"183172","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação às hérnias incisionais, assinale a alternativa INCORRETA.","options":{"A":"As hérnias incisionais são mais frequentes em mulheres, abaixo da cicatriz umbilical e\npredominantemente, acima dos 50 anos.","B":"25% a 50% dos pacientes submetidos à hemioplastias incisionais têm excesso de peso.","C":"O pneumoperitônio progressivo, introduzido por Goñi-Moreno, em 1947, representa uma\nimportante indicação nas hérnias gigantes e doentes com doenças pulmonares.","D":"Em pacientes com hérnia incisional aguda, também denominada evisceração aguda, o\ntratamento cirúrgico deve ser realizado em caráter de urgência.","E":"O melhor posicionamento para as próteses é a fixação das mesmas acima da aponeurose\nanterior."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182635","number":"182635","sourceNumber":"182635","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual reparo anatômico diferencia uma hérnia inguinal direta de uma indireta?","options":{"A":"Orifício inguinal externo.","B":"Canal inguinal.","C":"Vasos epigástricos superficiais.","D":"Ligamento de Gimbernat."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182617","number":"182617","sourceNumber":"182617","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No primeiro dia de pós-operatório de uma herniorrafia inguinal foi observado grande\nequimose na bolsa escrotal do paciente. A ferida operatória estava com aspecto normal. Qual a\nconduta?","options":{"A":"Expectante.","B":"Exploração cirúrgica da bolsa escrotal.","C":"Realizar ultrassonografia de bolsa escrotal.","D":"Punção evacuadora na bolsa escrotal."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-159048","number":"159048","sourceNumber":"159048","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente sexo feminino, 40 anos, IMC 34,5Kg/m² submetida à colecistectomia. No\nretorno ambulatorial refere saída de secreção serosa pela ferida operatória sem outras queixas.\nQual a conduta?","options":{"A":"Realizar expressão da ferida.","B":"Realizar ultrassonografia abdominal.","C":"Realizar tomografia computadorizada de abdome.","D":"Realizar exploração da ferida no centro-cirúrgico."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-135911","number":"135911","sourceNumber":"135911","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Secreção Hormonal diminuída durante a cirurgia:","options":{"A":"Catecolamina;","B":"Insulina;","C":"Cortisol;","D":"Glucagon;"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-84502","number":"84502","sourceNumber":"84502","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre a avaliação pré-operatória dos pacientes diabéticos, é correto afirmar, EXCETO:","options":{"A":"Especial atenção deve ser dada ao sistema cardiovascular, principalmente a história de\nhipertensão, isquemia miocárdia e doença cerebrovascular.","B":"Alterações no intervalo R-R indicam infarto silencioso.","C":"As infecções do trato urinário devem ser excluídas.","D":"O uso de metformina deve ser interrompido no máximo dois dias antes da cirurgia, pelo risco de\nacidose lática.","E":"A cirurgia, quando possível, deve ser postergada até que os níveis glicêmicos sejam inferiores a\n200 mg/dl."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-67000","number":"67000","sourceNumber":"67000","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre sepse, assinale a afirmativa INCORRETA:","options":{"A":"O nível sérico de lactato tem valor prognóstico bem estabelecido, particularmente se os níveis\nelevados forem persistentes;","B":"Culturas devem ser coletadas antes de iniciada a antibioticoterapia;","C":"Fazer reposição volêmica agressiva e repetitiva na presença de hipotensão e/ou lactato sérico\nelevado;","D":"Manter PVC maior ou igual a 75 mmHg e diurese maior ou igual a 0,5 ml/kg/hora."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-67004","number":"67004","sourceNumber":"67004","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente com a seguinte prescrição: 1) Cefepime; 2) Hidratação; 3) Noradrenalina; 4)\nMidazolam. Provavelmente tem o diagnóstico de:","options":{"A":"SIRS;","B":"Sepse;","C":"Choque séptico;","D":"Infarto do Miocárdio."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-369538","number":"369538","sourceNumber":"369538","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 12 anos de idade, é levado ao Pronto-Socorro pela genitora,\ncom queixa de dor abdominal difusa há dois\ndias. O paciente refere, também, hiporexia, alguns\nepisódios de náuseas, vômitos e diarreia. Ao exame físico, bom estado geral, temperatura axilar:\n38.2°C, FC: 82 bpm, PA: 110x74mmHg; ausculta cardíaca e respiratória sem alterações; abdome\num pouco distendido, ruídos hidroaéreos presentes, flácido, dor à palpação profunda de\nmesogástrio e fossa ilíaca direita, com sinais de irritação peritoneal. Os exames laboratoriais\niniciais\napresentaram Hb: 13g/dL, Ht: 36%, Leucócitostotais: 12500células/mm³ (Bastões: 5%). Indique a\nsequência correta de camadas que são dissecadas na laparotomia lateral a linha semilunar:","options":{"A":"Pele, subcutâneo, músculo oblíquo externo, músculo oblíquo interno, músculo transverso, fáscia\ntransversal e peritônio.","B":"Pele, subcutâneo, músculo oblíquo externo, músculo oblíquo interno, fáscia transversal, músculo\ntransverso e peritônio.","C":"Pele, subcutâneo, aponeurose do músculo reto abdominal, músculo oblíquo externo, músculo\noblíquo interno, músculo transverso, fáscia transversal e peritônio.","D":"Pele, subcutâneo, aponeurose e músculo reto abdominal, fáscia transversal e peritônio."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-341057","number":"341057","sourceNumber":"341057","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, 20 anos de idade, sexo feminino, sofreu ferimento cortante em mão direita\ncom uma faca, há uma hora. Nega outros\ntraumas. Ao exame físico, bom estado geral, corada, FC:\n78bpm, PA: 118x72mmHg, FR: 16imp; apresenta ferimento cortante em palma da mão direita,\nmedindo cerca de 2cm, linear e sem sangramento ativo. Sobre a anestesia local para a síntese\ndesse ferimento, é correto o que se afirma em","options":{"A":"A bupivacaína é o anestésico local mais indicado.","B":"Em meio ácido a lidocaína tem o seu efeito potencializado.","C":"A associação da epinefrina aumenta o risco de intoxicação dos anestésicos locais.","D":"O tempo de latência é um fator importante na escolha do anestésico local a ser utilizado para a\npaciente."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343196","number":"343196","sourceNumber":"343196","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre as heparinas, fórmulas utilizadas no tratamento das doenças vasculares,\nassinale a correta.","options":{"A":"A dose de heparina não fraciona normalmente deve ser ajustada pela medida do TTPa (Tempo\nde Tromboplastina Parcial Ativada). No caso de\ndoses muito elevadas, como as administradas em\ncircuitos extracorpóreos no momento de cirurgia cardíaca, cirurgia vascular ou transplante hepático,\nestas são determinadas pelo TCA (tempo de coagulação ativado).","B":"O efeito anticoagulante da heparina de baixo peso molecular pode ser neutralizado rapidamente\npela protamina intravenosa, uma proteína catiônica\nque se liga fortemente à heparina.","C":"O pico da concentração de antifator Xa e antifator IIa plasmático é alcançado 3 a 4 h depois da\nadministração da heparina não fracionada.","D":"Diferente como na heparina não fracionada, os pacientes podem apresentar resistência às\nheparinas de baixo peso molecular pois também se ligam às células do endotélio e aos\nmacrófagos, com mudanças na sua farmacocinética."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343233","number":"343233","sourceNumber":"343233","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Primariamente, a recorrência Tromboembolismo Venoso após o término da\nanticoagulação depende de fatores:","options":{"A":"Caso a TVP aguda não foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores de risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e as trombofilias.","B":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, reduziram a\nrecorrência, notadamente a doença maligna e as trombofilias.","C":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e nunca as trombofilias.","D":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e as trombofilias."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-315167","number":"315167","sourceNumber":"315167","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os procedimentos em cirurgias ambulatoriais podem ser beneficiados com efeito\nvasoconstritor da epinefrina, resultando em um bloqueio mais eficaz e duradouro, além da\ndiminuição do sangramento da região da intervenção. O local mais indicado para se utilizar a\nadição de vasocontritores em uma sutura de lesão superficial é o:","options":{"A":"Braço.","B":"Dedo.","C":"Pênis.","D":"Olho.","E":"Nariz."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-315168","number":"315168","sourceNumber":"315168","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo a classificação de estratificação de risco da Sociedade Americana de\nAnestesiologia (ASA), o paciente classe 5 é aquele:","options":{"A":"Saudável.","B":"Com doença sistêmica severa, não incapacitante.","C":"Maribundo, com espectativa de vida menor que 24 horas.","D":"Doador de órgãos.","E":"Com doença sistêmica moderada."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-315169","number":"315169","sourceNumber":"315169","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à antibioticoprofilaxia na prevenção das infecções cirúrgicas é CORRETO\nafirmar que:","options":{"A":"Os antimicrobianos de largo expectro são as drogas preferenciais.","B":"Uma única dose deve ser administrada, independente do tempo cirúrgico.","C":"Uma cefalosporina de primeira geracão é a droga de escolha para as cirurgias colorretais.","D":"O agente antimicrobiano deve ser administrado 30 minutos antes da incisão cirúrgica.","E":"NDA"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-307041","number":"307041","sourceNumber":"307041","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente foi submetido à cirurgia de colectomia total, ampliada para ressecção de tumor\nde cólon direito. A cirurgia teve duração de\ntrês horas e extravasamento de conteúdo fecal para\ncavidade abdominal. No pós-operatório em UTI desenvolveu edema em membros inferiores\nbilateral e bolsa escrotal. Determine o grau de contaminação nessa cirurgia.","options":{"A":"Limpa.","B":"Potencialmente contaminada.","C":"Contaminada.","D":"Infectada."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-307045","number":"307045","sourceNumber":"307045","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, refere dor em região testicular há vários\nmeses. A dor piora ao fazer esforço físico, como agachar. Refere que melhora ao deitar. Sua\nesposa percebeu que o lado onde sente dor (direito) está com um volume maior que o esquerdo.\nProcurou um médico para avaliação que, ao fazer o exame físico completo com o paciente deitado\ne em pé, notou abaulamento em região inguino-escrotal ao solicitar que tossisse. Diante do caso,\nindique a manobra utilizada nesse exame físico.","options":{"A":"Lapinsk.","B":"Dunphy.","C":"Blumberg.","D":"Valsalva."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-275985","number":"275985","sourceNumber":"275985","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na correção das hérnias inguinais, qual das técnicas apresenta menor índice de\nrecidiva?","options":{"A":"Bassinet.","B":"Shouldice.","C":"McKay.","D":"Lichtenstein.","E":"Andrews."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-278096","number":"278096","sourceNumber":"278096","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa correta.","options":{"A":"A aplicação de ventilação não invasiva deve ser uma rotina em todas as crianças após a\nextubação.","B":"A ventilação pulmonar mecânica, para ser definida como prolongada, necessita de um período\nininterrupto de 2 meses.","C":"A utilização da ventilação não invasiva pode ser uma estratégia útil, permitindo a remoção\nprecoce da ventilação pulmonar mecânica\ninvasiva.","D":"Um pequeno número de crianças é retirada da ventilação pulmonar mecânica sem\nintercorrências."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-278102","number":"278102","sourceNumber":"278102","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa incorreta em relação às medidas não farmacológicas para\npacientes em uso de sedação.","options":{"A":"Minimizar ruídos na unidade e diminuir a luminosidade à noite.","B":"Estabelecer momento de descanso e sono em consonância com a orientação dia/ noite.","C":"Na medida do possível, realizar a maior parte dos procedimentos durante o dia.","D":"Evitar a presença de acompanhantes, mantendo o ambiente o mais silencioso possível."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-280422","number":"280422","sourceNumber":"280422","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Levando-se em consideração o manejo da sedação realizada em pacientes internados\nna UT Pediátrica, assinale a alternativa\ncorreta.","options":{"A":"Um nível de sedação leve acarreta diminuição do tempo de ventilação mecânica, do tempo de\ninternação em UTI e hospital, com menores doses de sedativos.","B":"O ambiente de UTI ocasiona desconforto e angústia física ou psíquica; portanto, é sempre\nnecessário que o paciente em ventilação pulmonar\nmecânica permaneça sedado, a fim de diminuir\ntais desconfortos e provocar amnésia.","C":"Com o uso de escalas de sedação, é possível ter certeza de que o paciente está bem sedado,\npouco reativo e sem riscos de peras de\ndispositivos.","D":"Um nível de sedação leve acarreta diminuição do uso de medicações, mantendo o paciente\ncalmo e responsivo; porém, pode ocasionar\nmaior dificuldade de sincronia com ventilação pulmonar\nmecânica e risco de extubação traqueal acidental."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-280428","number":"280428","sourceNumber":"280428","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São fatores que impedem o fechamento de fístulas enterocutâneas, exceto:","options":{"A":"Alto débito (> 500ml/24h).","B":"Epitelização do trajeto fistuloso.","C":"Trajeto fistuloso > 2.5 cm de comprimento.","D":"Grande ruptura da continuidade intestinal."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-279063","number":"279063","sourceNumber":"279063","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 59 anos foi submetido a gastrectomia subtotal devido a adenocarcinoma\ngástrico, em primeiro dia de pós-operatório\napresentou desconforto respiratório e febre aferida de\n38oC. Nega dor torácica. Nega tosse. Nega sintomas urinários. Ao exame físico: regular estado\ngeral, descorado (++/4+), desidratado (+/4+), taquipneico, anictérico, acianótico, afebril. Estável\nhemodinamicamente, bulhas rítmicas sem sopros audíveis, normofonéticas. Murmúrio vesicular\nabolido em hemitórax esquerdo, submaciço à percussão. Abdome com ferida operatória levemente\nhiperemiada, sem saída de secreções, ruídos hidroaéreos reduzidos, levemente doloroso, sem\nsinais de irritação peritoneal. Foi submetido à radiografia de tórax abaixo. A provável etiologia do\nquadro febril é:","options":{"A":"Atelectasia.","B":"Pneumonia lobar.","C":"Pneumotórax.","D":"Hemotórax."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/279063.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-280434","number":"280434","sourceNumber":"280434","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"É o estado de hipermetabolismo e injúria muscular associado à administração de\nagentes anestésicos halogenados. Pode ser reconhecido por aumento na atividade do sistema\nnervoso simpático, rigidez muscular e febre alta:","options":{"A":"Anafilaxia.","B":"Febre do Nilo Ocidental.","C":"Hipertemia Maligna.","D":"Rabdomiólise Idiopática."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-278647","number":"278647","sourceNumber":"278647","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A figura abaixo ilustra a anatomia da região inguinal direita sob uma visão anterior.\nAssinale a alternativa com a correta associação entre o número indicado na foto com o tipo de\nhérnia.","options":{"A":"1: femoral; 2: direta; 3: indireta.","B":"1: indireta; 2: femoral; 3: direta.","C":"1: indireta; 2: direta; 3: femoral.","D":"1: direta; 2: femoral; 3: indireta."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/278647.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-278649","number":"278649","sourceNumber":"278649","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os tipos de hérnias inguinais, classificadas por Nyhus, em um grupo associadas a um\ndefeito da parede posterior são:","options":{"A":"Tipo I","B":"Tipo II","C":"Tipo III","D":"Tipo IV"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-231346","number":"231346","sourceNumber":"231346","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é o melhor método (gold standard) para confirmar a posição da cânula na\ntraqueia?","options":{"A":"Ausculta do tórax e abdome","B":"Detector colorimétrico de CO2 expirado","C":"Visualização da condensação de gás na cânula durante a expiração","D":"Percussão do tórax","E":"Presença de vapor de água na cânula orotraqueal"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-249299","number":"249299","sourceNumber":"249299","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Das alternativas abaixo, qual o recurso faz detecção precoce de intubação esofágica?","options":{"A":"Capnografia.","B":"Lactato arterial.","C":"Lactato sérico.","D":"Radiografia de tórax."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-252897","number":"252897","sourceNumber":"252897","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 22 anos de idade, dá entrada na UPA do seu bairro, vítima\nde agressão física há uma hora. A paciente\nrefere que, após discussão com a prima, recebeu um\nsoco na boca e cursou um ferimento no lábio inferior com sangramento ativo. Nega comorbidades\nou outros traumas. Refere dor no lábio inferior e sem outras queixas. Ao exame inicial: A: via aérea\npérvia, nega dor cervical, SatO?: 99%; B: Murmúrio vesicular bem distribuído sem ruídos\nadventícios, FR: 16ipm; C: Bulhas rítmicas e normofonéticas, FC: 80bpm, PA: 126x82mmHg; D:\nEscala de coma de Glasgow 15, pupilas isocóricas e fotorreagentes; E: ferimento corto-contuso\nmedindo 4cm em lábio inferior do lado esquerdo, acometendo pele e mucosa oral, bordas\nirregulares, lesão da musculatura sem perda de substância e apresentando sangramento ativo e\npequena quantidade. Considerando o quadro, após o atendimento inicial, indique a conduta mais\nadequada.","options":{"A":"Solicitar radiografia de tórax, pelve e cervical.","B":"Fazer hidratação com solução cristaloide.","C":"Fazer síntese do ferimento da boca com anestesia local.","D":"Observar por seis horas e fazer curativo no lábio."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-252898","number":"252898","sourceNumber":"252898","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 22 anos de idade, dá entrada na UPA do seu bairro, vítima\nde agressão física há uma hora. A paciente\nrefere que, após discussão com a prima, recebeu um\nsoco na boca e cursou um ferimento no lábio inferior com sangramento ativo. Nega comorbidades\nou outros traumas. Refere dor no lábio inferior e sem outras queixas. Ao exame inicial: A: via aérea\npérvia, nega dor cervical, SatO?: 99%; B: Murmúrio vesicular bem distribuído sem ruídos\nadventícios, FR: 16ipm; C: Bulhas rítmicas e normofonéticas, FC: 80bpm, PA: 126x82mmHg; D:\nEscala de coma de Glasgow 15, pupilas isocóricas e fotorreagentes; E: ferimento corto-contuso\nmedindo 4cm em lábio inferior do lado esquerdo, acometendo pele e mucosa oral, bordas\nirregulares, lesão da musculatura sem perda de substância e apresentando sangramento ativo e\npequena quantidade. Visando evitar complicações em relação ao tratamento do lábio inferior,\nindique uma conduta não adequada para o momento.","options":{"A":"Lavagem do ferimento com SF0,9%.","B":"Desbridamento das bordas.","C":"Síntese com inversão das bordas.","D":"Retirada de corpo estranho do ferimento."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-252899","number":"252899","sourceNumber":"252899","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 22 anos de idade, dá entrada na UPA do seu bairro, vítima\nde agressão física há uma hora. A paciente\nrefere que, após discussão com a prima, recebeu um\nsoco na boca e cursou um ferimento no lábio inferior com sangramento ativo. Nega comorbidades\nou outros traumas. Refere dor no lábio inferior e sem outras queixas. Ao exame inicial: A: via aérea\npérvia, nega dor cervical, SatO?: 99%; B: Murmúrio vesicular bem distribuído sem ruídos\nadventícios, FR: 16ipm; C: Bulhas rítmicas e normofonéticas, FC: 80bpm, PA: 126x82mmHg; D:\nEscala de coma de Glasgow 15, pupilas isocóricas e fotorreagentes; E: ferimento corto-contuso\nmedindo 4cm em lábio inferior do lado esquerdo, acometendo pele e mucosa oral, bordas\nirregulares, lesão da musculatura sem perda de substância e apresentando sangramento ativo e\npequena quantidade. Dos tempos cirúrgicos, indique o mais relevante para se evitar sequela grave\nfuncional relacionada ao tratamento do ferimento do lábio inferior.","options":{"A":"Síntese com reconstrução da musculatura oral.","B":"Síntese da mucosa oral.","C":"Síntese da pele.","D":"Hemostasia."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-231373","number":"231373","sourceNumber":"231373","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual o tipo de herniorrafia inguinal mais utilizado atualmente na correção dos defeitos\ninguinais","options":{"A":"Bassini","B":"Shoudice","C":"Lichenstein","D":"TAAP","E":"TEP"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-249223","number":"249223","sourceNumber":"249223","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A ginecomastia é a proliferação benigna mais comum do tecido glandular da mama\nmasculina, causada pela alteração do equilíbrio entre as concentrações de estrógeno e\nandrogênios. Pela Classificação de Simon, a mama que apresenta aumento mamário moderado\ncom redundância de pele definida, similar a mama feminina corresponde ao grau:","options":{"A":"I","B":"II","C":"III","D":"IV"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-249230","number":"249230","sourceNumber":"249230","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A principal causa de febre pós operatória entre 24h a 48h do tempo cirúrgico é:","options":{"A":"Abscesso intra-cavitário.","B":"Infecção de sítio cirúrgico.","C":"Tromboembolismo venoso.","D":"Atelectasia."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-249232","number":"249232","sourceNumber":"249232","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente 70 anos, admitido em terapia intensiva após esofagectomia subtotal\n\ntrans-hiatal convencional por carcinoma espinocelular de terço médio. Está sedado, em ventilação\nmecânica, com doses de analgésico otimizadas apresentando frequência cardíaca de 135 bpm,\npressão arterial média de 55 mmHg, Sat O2 99% com FiO2 a 40%. Gasometria arterial: pH: 7,30;\npO2: 90; pCO2: 35; HCO3: 14. A melhor conduta neste caso é:","options":{"A":"expansão com albumina humana 10%.","B":"prescrever noradrenalina (0,3 mcg/kg/min).","C":"administrar bicarbonato de sódio 8,4%.","D":"expansão volêmica com Ringer Lactato ou Cloreto de Sódio 0,9%."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-216258","number":"216258","sourceNumber":"216258","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Para Intubação endotraqueal em serviços de urgência, podemos apenas CONCORDAR\ncom o item:","options":{"A":"Uma vez indicada a necessidade de intubação endotraqueal e de suporte ventilatório, a opção\npela não utilização de drogas em sequência rápida para o estabelecimento da via aérea tem se\nmostrado segura e deve ser preferencialmente adotada no adulto.","B":"Uma vez indicada a necessidade de intubação endotraqueal e de suporte ventilatório, a opção\npela utilização de drogas em sequência rápida para o estabelecimento da via aérea tem se\nmostrado insegura e deve ser preferencialmente adotada no adulto.","C":"Uma vez indicada a necessidade de intubação endotraqueal e de suporte ventilatório, a opção\npela utilização de drogas em sequência rápida para o estabelecimento da via aérea tem se\nmostrado segura e não deve ser preferencialmente adotada no adulto.","D":"Uma vez indicada a necessidade de intubação endotraqueal e de suporte ventilatório, a opção\npela utilização de drogas em sequência rápida para o estabelecimento da via aérea tem se\nmostrado segura e deve ser preferencialmente adotada no adulto."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212139","number":"212139","sourceNumber":"212139","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considere os seguintes cenários: I. Paciente de 30 anos, obeso, será submetido a\ncolecistectomia eletiva. II. Paciente de 62 anos, hipertenso e diabético, IAM prévio, com 3 stents\ncoronarianos, compensado do ponto de vista cardiológico, em uso de AAS e clopidogrel,\napresentando quadro de colecistite aguda litiásica. III. Paciente de 48 anos, obeso mórbido, IMC\n49, diabético, apneia obstrutiva do sono e com doença do refluxo gastro-esofágico, em\nprogramação de cirurgia bariátrica. IV. Paciente de 55 anos, tabagista, portador de adenocarcinoma\nde antro gástrico, realizou neoadjuvância, com proposta de gastrostomia subtotal oncológica. Em\nrelação a esses casos, assinale a alternativa correta.","options":{"A":"O melhor procedimento para o paciente III é o sleeve ou gastrectomia vertical.","B":"Profilaxia de TEV para o paciente IV deve ser feita com heparina, apenas, por 10 dias.","C":"O paciente I necessita de uso de heparina, dose única, como profilaxia de tromboembolismo\nvenoso (TEV).","D":"O paciente II deve ser submetido a cirurgia em até 24 horas para não haver descompensação\ndo seu quadro cardiológico.","E":"Profilaxia de TEV para o paciente III deve ser feita com deambulação precoce, meias elásticas e\nheparina por 21 dias."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212148","number":"212148","sourceNumber":"212148","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 52 anos, sexo masculino, hipertenso, assintomático. Exame físico, corado,\nhidratado, antiictérico, circunferência abdominal de 89 cm. Abdome semi-globoso, flácido, indolor,\nfígado palpável a 2 cm de rebordo costal direito, sem circulação colateral, sem hérnia umbilical,\nanel inguinal externo esquerdo dilatado, com projeção de conteúdo por este à manobra de Vasalva.\nRealizou exames de rotina e ultrassonografia de abdome evidenciou lesão cística em segmento 6\ndo fígado e vesícula biliar com imagens hiperecogências que ocasionam sombra acústica posterior,\ndiâmetro médio de 8 mm, móveis ao decúbito. A ressonância nuclear magnética do abdome\nsuperior confirmou lesão cística no fígado, em segmento 6, sem septações com as mesmas\ndimensões da ultrassonografia. Qual a conduta correta a ser tomada?","options":{"A":"Indicar hernioplastia inguinal.","B":"Seguimentos clínico e radiológico semestral.","C":"Destelhamento do cisto hepático e colecistectomia, apenas.","D":"Hepatectomia lateral direita, colecistectomia e hernioplastia inguinal laparoscópicas.","E":"Destelhamento do cisto hepático e colecistectomia num primeiro tempo e hernioplastia inguinal\nem segundo tempo."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212169","number":"212169","sourceNumber":"212169","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São fatores que diminuem a incidência de fístulas pancreáticas após\nduodenopancreatectomias:","options":{"A":"perda sanguínea mínima; pancreatite crônica.","B":"tumor neuroendócrino; índice de massa corpórea superior a 30.","C":"adenocarcinoma de duodeno; ausência de pancreatite crônica.","D":"uso de cola biológica em anastomose; drenagem biliar pré-operatória.","E":"calibre do ducto pancreático principal de até 3 mm; textura macia do parênquima pancreático."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212181","number":"212181","sourceNumber":"212181","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O projeto ACERTO (Aceleração da Recuperação Total Pós-operatória) é um programa\nque objetiva acelerar a recuperação\npós-operatória dos pacientes. Baseado nesse projeto, são\ncaracterísticas de um programa multimodal de cuidados perioperatórios em paciente de 55 anos\nque irá ser submetido a retossigmoidectomia oncológica:","options":{"A":"hidratação venosa até o quarto dia; jejum de 6 horas.","B":"uso de sonda nasogástrica; jejum de 6 horas pré-operatório.","C":"informação detalhada sobre o perioperatório; jejum de 2 horas.","D":"preparo de cólon; realimentação em segundo dia pós-operatório.","E":"sem terapia nutricional pré-operatória; hidratação venosa até o terceiro dia pós-operatório."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212171","number":"212171","sourceNumber":"212171","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre as hérnias da região inguinal, assinale a alternativa correta.","options":{"A":"Não é possível pelo exame físico diferenciar a hérnia inguinal direta da indireta.","B":"Pode-se afirmar que uma hérnia inguino-escrotal é uma hérnia inguinal direta.","C":"A hérnia indireta com anel inguinal profundo normal (até 2 cm) é classificada como Nyhus II.","D":"A hérnia de Amyand consiste na protrusão do apêndice vermiforme no saco herniário inguinal.","E":"As hérnias inguinais indiretas surgem medialmente aos vasos epigástricos inferiores (triângulo\nde Hesselbach)."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215469","number":"215469","sourceNumber":"215469","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Hoje há uma preocupação cada vez mais frequente com a humanização do paciente\ninternado, principalmente em UTI. Como isso pode ser aplicado em pediatria?","options":{"A":"Por meio de uma sedação mais leve, consciente, permitindo que o paciente fique o menor tempo\npossível na VPM.","B":"Por meio de uma sedação mais pesada para evitar agitação.","C":"Pela utilização de som ambiente.","D":"Pela utilização de escalas de abstinência."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215474","number":"215474","sourceNumber":"215474","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa CORRETA em relação aos efeitos associados ao uso de alfa-2\nagonistas.","options":{"A":"Somente analgesia.","B":"Somente sedação.","C":"Não há efeitos adversos.","D":"Analgesia e, principalmente, sedação."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215489","number":"215489","sourceNumber":"215489","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que apresenta a principal vantagem do uso da clonidina em\nrelação à dexmedetomidina.","options":{"A":"Baixo custo.","B":"Melhora da função renal.","C":"Maior sedação.","D":"Redução do tempo de VPM."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215504","number":"215504","sourceNumber":"215504","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que NÃO configura indicação de ECMO no pós-operatório de\ncirurgia cardíaca.","options":{"A":"Parada cardíaca.","B":"Saturação venosa inferior a 50%.","C":"Uso de drogas vasoativas em doses supramáximas.","D":"Presença de defeito residual com repercussão hemodinâmica."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215508","number":"215508","sourceNumber":"215508","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre o uso de ECMO, assinale a alternativa CORRETA.","options":{"A":"O uso de ECMO demanda apenas cirurgião cardíaco e anestesista especializados e treinados.","B":"No Brasil, há farto número de publicações sobre uso de ECMO no pós-operatório cardíaco em\ncrianças.","C":"O uso de ECMO é parte integrante do manejo do pós-operatório de cirurgia cardíaca em\ncrianças.","D":"O tempo prolongado de VPM é fator de melhor prognóstico no uso de ECMO."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215241","number":"215241","sourceNumber":"215241","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é o principal efeito da dopamina quando utilizada em baixas doses?","options":{"A":"Melhora do fluxo renal.","B":"Aumento da contratilidade cardíaca.","C":"Aumento da vasoconstrição periférica.","D":"Ação na vasodilatação periférica."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215501","number":"215501","sourceNumber":"215501","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é o tempo médio de absorção do fio de seda?","options":{"A":"Inabsorvível.","B":"1 a 2 anos.","C":"5 anos.","D":"60 dias."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215511","number":"215511","sourceNumber":"215511","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é o hipnótico mais indicado para intubação em sequência rápida para um paciente\npolitraumatizado com hipotensão?","options":{"A":"Midazolam.","B":"Diazepam.","C":"Etomidato.","D":"Succinilcolina."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-216268","number":"216268","sourceNumber":"216268","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hérnia inguinal é a afecção cirúrgica mais frequente da criança. Assinale a alternativa\nINCORRETA.","options":{"A":"Predomina no sexo masculino (3:1), sendo o lado esquerdo acometido em 60% dos casos, e o\ndireito em 30%. Em 10% dos casos, a hérnia é bilateral.","B":"No recém-nascido ou lactente, o exame físico consiste na palpação digital da região inguinal,\nlateralmente ao púbis, visando avaliar a espessura do cordão espermático.","C":"A hérnia inguinal não causa dor em crianças, a não ser em situações em que se apresenta\nencarcerada.","D":"A criança com hérnia inguinal encarcerada se apresenta irritada, chorosa, não aceita\nalimentação e pode apresentar sintomas de obstrução intestinal, como vômitos e parada de\neliminação de gases e fezes."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212215","number":"212215","sourceNumber":"212215","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Carlos, 3 meses de vida, é levado ao atendimento em Puericultura sem queixas\nreferidas por sua genitora, estando com\nsituação vacinal atualizada, bem como em aleitamento\nmaterno exclusivo. Durante a realização do exame físico, o pediatra notou espessamento do\ncordão espermático, bem como presença de abaulamento em região inguinal à direita, com prova\nde transiluminação negativa, com testículos em bolsa escrotal. Nesse momento, a genitora relata\nque esporadicamente havia notado tal tumoração, que surgia em momento de choro, desparecendo\nespontaneamente. Qual a principal hipótese diagnóstica para Carlos e a proposta terapêutica a ser\nsugerida?","options":{"A":"Testículo retrátil, devendo a conduta ser expectante.","B":"Hidrocele comunicante, devendo ter tratamento conservador.","C":"Ectopia testicular, devendo ser indicado procedimento cirúrgico de imediato.","D":"Orquite, devendo ser indicado uso de antibioticoterapia e reavaliação de procedimento cirúrgico\napós esta.","E":"Hérnia inguinal, tendo indicação de herniorrafia inguinal logo após o diagnóstico, com exploração\ncirúrgica contralateral."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-181288","number":"181288","sourceNumber":"181288","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Durante uma cirurgia pélvica, a lesão do nervo obturatório é identificada clinicamente\npor:","options":{"A":"perda da sensibilidade perineal, escrotal e na face posterior da coxa D.","B":"parestesia da região inguinal homolateral e atrofia do músculo oblíquo interno.","C":"perda da sensibilidade na região púbica, porção anterior do escroto e face posterior da coxa.","D":"perda da força no músculo adutor da coxa e perda da sensibilidade na face medial da coxa D.","E":"perda de sensibilidade na região anterior da coxa direita e diminuição da força do diafragma\nurogenital."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-187729","number":"187729","sourceNumber":"187729","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação ao uso profilático de antibiótico em cirurgia, assinale alternativa ERRADA:","options":{"A":"Doses complementares são formalmente contraindicadas","B":"Na colecistectomia videolaparoscópica está indicada em pacientes com mais de 70 anos,\ndiabéticos e com manipulação recente das vias biliares","C":"Uso prolongado aumenta o risco de infecções nosocomiais não relacionadas ao sítio cirúrgico","D":"Visa principalmente coibir infecção da ferida operatória"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-181328","number":"181328","sourceNumber":"181328","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa correta em relação às hérnias de parede abdominal.","options":{"A":"As hérnias umbilicais devem ser sempre tratadas com tela.","B":"As hérnias femorais têm maior incidência em homens e tabagistas.","C":"A recidiva pós-herniorrafia inguinal convencional deve ser tratada, preferencialmente, por\nlaparoscopia.","D":"O tratamento laparoscópico das hérnias inguinais é inferior ao convencional em termos de dor\npós-operatória.","E":"As hérnias inguinais em adultos apresentam taxa de recorrência semelhante quando tratadas\ncom e sem tela."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-181389","number":"181389","sourceNumber":"181389","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação às complicações cirúrgicas da parede abdominal, é correto afirmar:","options":{"A":"evisceração é a ruptura parcial das camadas da parede abdominal.","B":"o aspecto da borda da ferida não é um bom parâmetro preditivo da evisceração.","C":"o ambiente seco (feridas secas) tende a ter mais rápida cicatrização e proteção contra infecção.","D":"a obesidade é o principal responsável pelo aumento da pressão intra-abdominal no\npós-operatório precoce.","E":"infecção, desnutrição e alcoolismo são fatores de risco para evisceração. Icterícia e uso de\ncorticoides são fatores protetores."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182781","number":"182781","sourceNumber":"182781","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os escores de risco habitualmente utilizados permitem estimar o risco de eventos\ncardiovasculares no período perioperatório com moderada acurácia. Testes de avaliação de\nisquemia, assim como novos biomarcadores promissores (troponinas e peptídeos natriuréticos),\npermitem refinar esta estimativa de risco antes da cirurgia. Somente podemos CONCORDAR com\no seguinte item:","options":{"A":"os peptídeos natriuréticos são liberados na circulação sanguínea pelo miocárdio em resposta a\nmúltiplos estímulos fisiológicos, como estresse miocárdico e isquemia. Múltiplos estudos\ndemonstraram que níveis pré-operatórios elevados de Peptídeo Natriurético do Tipo B (BNP) são\nfracos preditores de complicações cardiovasculares perioperatória.","B":"os peptídeos natriuréticos não são liberados na circulação sanguínea pelo miocárdio em\nresposta a múltiplos estímulos fisiológicos,\nsomente com isquemia. Múltiplos estudos\ndemonstraram que níveis pré-operatórios elevados de Peptídeo Natriurético do Tipo B (BNP) são\npotentes preditores de complicações cardiovasculares perioperatória.","C":"os peptídeos natriuréticos são liberados na circulação sanguínea pelo miocárdio em resposta a\nmúltiplos estímulos fisiológicos, como estresse miocárdico e isquemia. Múltiplos estudos\ndemonstraram que níveis pré-operatórios elevados de Peptídeo Natriurético do Tipo B (BNP) são\npotentes preditores de complicações cardiovasculares perioperatória.","D":"os peptídeos natriuréticos são liberados na circulação sanguínea pelo miocárdio em resposta a\nmúltiplos estímulos fisiológicos, como estresse miocárdico e isquemia. Mas, estudos falham em\ndemonstrar que níveis pré-operatórios elevados de Peptídeo Natriurético do Tipo B (BNP) são\npotentes preditores de complicações cardiovasculares perioperatória."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182794","number":"182794","sourceNumber":"182794","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Há cerca de quatro décadas, a análise de risco perioperatório do coronariopata\nconsistia estritamente em aferir a relação\ntemporal entre determinado evento isquêmico cardíaco e\na operação proposta. Somente sendo INCORRETO que,","options":{"A":"uma cautelosa anamnese, associada à propedêutica direcionada para o aparelho circulatório e a\nexames subsidiários básicos, como o ECG de repouso e o raio-X de tórax, nunca é suficiente para\ndeterminar o risco cirúrgico de pacientes coronariopatas.","B":"discriminar objetivamente o risco cirúrgico para cada condição específica da doença arterial\ncoronária (DAC) é fundamental para a prevenção e para uma menor morbidade de eventos\nperioperatórios.","C":"atualmente, no entanto, contemplamos, além do intervalo referido, todos os fatores relevantes\nno prognóstico de pacientes portadores de DAC,\nindependentemente do contexto perioperatório.","D":"presença de angina, insuficiência cardíaca, sinais eletrocardiográficos, extensão e limiar da\nisquemia, além da anatomia coronária, nos casos pertinentes são fatores relevantes no prognóstico\nde pacientes portadores."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-187844","number":"187844","sourceNumber":"187844","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação ao perioperatório, assinale alternativa ERRADA:","options":{"A":"A solução de clorexidine é superior à solução de iodopovidine no preparo da pele para inserção\nde cateteres venosos","B":"A utilização de drenagem abdominal de rotina diminui consideravelmente o risco de infecção\npós-operatória","C":"Glicemia superior a 200mg/dL em qualquer momento do pós-operatório imediato aumenta o\nrisco de infecção do sítio cirúrgico","D":"Transfusões de sangue no per-operatório aumentam a incidência de infecção"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182801","number":"182801","sourceNumber":"182801","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na hipertensão leve ou moderada, em que não há alterações metabólicas ou\ncardiovasculares associadas, não há evidências de\nque seja benéfico retardar a operação. Sendo\nCORRETO, apenas, que de forma geral,","options":{"A":"a hipertensão estágio 2 com pressão arterial sistólica >200 mmHg e diastólica > 110 mmHg deve\nser controlada antes da cirurgia. A estratégia\nperioperatória, em geral, deve ser manter a pressão\narterial dentro de 20% dos valores pré-operatórios (desde que este valor não esteja muito\ndescontrolado), o que reflete uma flexibilidade no controle - não necessariamente para níveis ditos\nnormais. Isto pode reduzir a ocorrência das urgências hipertensivas no período perioperatório.","B":"a hipertensão estágio 2 com pressão arterial sistólica > 180 mmHg e diastólica > 120 mmHg\ndeve ser controlada antes da cirurgia. A\nestratégia perioperatória, em geral, deve ser manter a\npressão arterial dentro de 20% dos valores pré-operatórios (desde que este valor não esteja muito\ndescontrolado), o que reflete uma flexibilidade no controle - não necessariamente para níveis ditos\nnormais. Isto pode reduzir a ocorrência das urgências hipertensivas no período perioperatório.","C":"a hipertensão estágio 2 com pressão arterial sistólica > 180 mmHg e diastólica > 110 mmHg não\nnecessita de ser controlada antes da cirurgia. A estratégia perioperatória, em geral, deve ser\nmanter a pressão arterial dentro de 20% dos valores pré-\n\noperatórios (desde que este valor não esteja muito descontrolado), o que reflete uma flexibilidade\nno controle - não necessariamente para níveis\nditos normais. Isto pode reduzir a ocorrência das\nurgências hipertensivas no período perioperatório.","D":"a hipertensão estágio 2 com pressão arterial sistólica > 180 mmHg e diastólica > 110 mmHg\ndeve ser controlada antes da cirurgia. A\nestratégia perioperatória, em geral, deve ser manter a\npressão arterial dentro de 20% dos valores pré-operatórios\n\n(desde que este valor não esteja muito descontrolado), o que reflete uma flexibilidade no controle -\nnão necessariamente para níveis ditos normais. Isto pode reduzir a ocorrência das urgências\nhipertensivas no período perioperatório."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182813","number":"182813","sourceNumber":"182813","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"IC é o fator de risco bem conhecido para eventos cardíacos perioperatórios. A IC afeta\nem torno de 1 a 2% da população geral nos países desenvolvidos e atinge mais de 10% da\npopulação com mais de 70 anos. Podemos, apenas, CONCORDAR com o seguinte:","options":{"A":"fração de ejeção reduzida é considerada forte preditora de eventos em pacientes submetidos à\ncirurgia vascular. No entanto, a maioria dos estudos analisou a fração de ejeção como variável\ncategórica (acima ou abaixo de 60%).","B":"fração de ejeção reduzida é considerada pouco preditora de eventos em pacientes submetidos à\ncirurgia vascular. No entanto, a maioria dos estudos analisou a fração de ejeção como variável\ncategórica (acima ou abaixo de 40%).","C":"fração de ejeção reduzida é considerada forte preditora de eventos em pacientes submetidos à\ncirurgia vascular. No entanto, a maioria dos estudos analisou a fração de ejeção como variável\ncategórica (acima ou abaixo de 40%).","D":"fração de ejeção reduzida é considerada forte preditora de eventos em pacientes submetidos à\ncardíaca, apenas. No entanto, a maioria dos estudos analisou a fração de ejeção como variável\ncategórica (acima ou abaixo de 40%)."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-180134","number":"180134","sourceNumber":"180134","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O triângulo de Hesselbach é formado por:","options":{"A":"Bainha do reto, ligamento inguinal e vasos femorais","B":"Vasos epigástricos, tendão conjunto e ligamento de Cooper","C":"Vasos epigástricos inferiores, bainha do reto abdominal e ligamento inguinal","D":"Vasos epigástricos, vasos femorais e ligamento inguinal","E":"Ligamento inguinal, espinha ilíaca anterossuperior e bainha do reto."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-180144","number":"180144","sourceNumber":"180144","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que complete corretamente a frase. A presença de apêndice\ncecal em um saco herniário é conhecida como\nhérnia de:","options":{"A":"Grynfelt","B":"Petit","C":"Littre","D":"Amyand","E":"McVay"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183551","number":"183551","sourceNumber":"183551","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São variáveis comportamentais e fisiológicas avaliadas na escala de COMFORT,\nEXCETO","options":{"A":"sono.","B":"agitação.","C":"movimento físico.","D":"reflexo pupilar."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183558","number":"183558","sourceNumber":"183558","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre as principais definições relacionadas à\nanalgesia e sedação.","options":{"A":"Sedação é alívio da percepção de dor associada à depressão controlada do nível de consciência","B":"A analgesia é alívio da percepção da dor sem a produção intencional do estado sedativo.","C":"O alívio da ansiedade é a diminuição do estado de apreensão.","D":"A sedação é a redução controlada do nível de consciência."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183565","number":"183565","sourceNumber":"183565","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre a avaliação da dor em pediatria, assinale a alternativa INCORRETA.","options":{"A":"É direta para pacientes que estão em condições de relatar a intensidade da dor.","B":"É dificultada em crianças de 3 a 7 anos de idade.","C":"Para crianças com idade entre 3 a 7 anos, os métodos mais comuns para avaliação da dor são\nos de autorretrato.","D":"A avaliação da dor é feita pelo uso de EVA em crianças maiores de 8 anos de idade."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182798","number":"182798","sourceNumber":"182798","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Das medicações citadas abaixo, qual não tem propriedades analgésicas?","options":{"A":"Dexmedetomidina","B":"Cetamina","C":"Pentobarbital","D":"Propofol"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183571","number":"183571","sourceNumber":"183571","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que apresenta um efeito colateral do propofol.","options":{"A":"Alcalose metabólica.","B":"Vômito.","C":"Mioclonia.","D":"Falência adrenal."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183578","number":"183578","sourceNumber":"183578","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à síndrome de abstinência em pediatria.","options":{"A":"É o desenvolvimento da necessidade de aumentar progressivamente a dose de um fármaco\npara obter o mesmo efeito.","B":"É o aparecimento de alguns sinais e sintomas físicos como taquicardia, febre, agitação, entre\noutros.","C":"É evidenciada após 10 a 21 dias de administração do medicamento.","D":"É a necessidade do organismo em continuar recebendo o fármaco."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182790","number":"182790","sourceNumber":"182790","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na criança traumatizada, a intubação endotraqueal é indicada em uma grande\nvariedade de situações, incluindo traumatismos\ncranianos graves, insuficiência ventilatória,\nhipovolemia significativa. A droga de escolha para sedação na intubação de doentes pediátricos\nhipovolêmicos é","options":{"A":"Propofol.","B":"Fentanil.","C":"Etomidato.","D":"Diazepam."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183605","number":"183605","sourceNumber":"183605","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente em uso de clopidogrel, será submetido à colecistectomia videolaparoscópica\neletiva. Quanto tempo antes do precedimento devemos\nsuspender o uso da medicação?","options":{"A":"24 horas.","B":"48 horas.","C":"5-7 dias.","D":"10-14 dias."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183610","number":"183610","sourceNumber":"183610","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das complicações abaixo é mais comum com o uso do propofol?","options":{"A":"Taquicardia.","B":"Hipotensão.","C":"Hipertensão.","D":"Taquiarritmias."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182784","number":"182784","sourceNumber":"182784","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São efeitos colaterais da Succinilcolina, EXCETO.","options":{"A":"amnésia.","B":"bradicardia.","C":"hipercalemia.","D":"hipertermia maligna"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-182805","number":"182805","sourceNumber":"182805","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A figura a seguir corresponde à qual classe de Mallampati?","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/182805.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183112","number":"183112","sourceNumber":"183112","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente no 5º dia de pós-operatório de pneumonectomia direita evoluindo com quadro\nde tosse com expectoração hemática em grande\nquantidade, dispneia e queda da saturação de O2.\nRadiografia de tórax evidenciando aumento da câmera aérea à direita. Qual é a principal hipótese\ndiagnóstica?","options":{"A":"Pneumonia.","B":"Tromboembolismo pulmonar.","C":"Hemotórax.","D":"Fístula de coto brônquico"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158756","number":"158756","sourceNumber":"158756","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A cirurgia segura para o doente é a grande meta buscada pelos serviços médicos. Qual\na causa mais comum de evento sentinela como erro do sítio cirúrgico?","options":{"A":"Comunicação insuficiente.","B":"Treinamento inadequado do pessoal envolvido.","C":"Procedimentos múltiplos com acessos distintos.","D":"Informação crítica insuficiente no transoperatório.","E":"Avaliação incompleta do doente antes do procedimento."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161130","number":"161130","sourceNumber":"161130","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Apesar do aprimoramento nutricional pós-cirúrgico e da terapia intensiva, a mortalidade\npor fístulas enterocutâneas permanece alta.\nIndique a alternativa INCORRETA sobre as fístulas\nenterocutâneas:","options":{"A":"As fístulas enterocutâneas são, em geral, iatrogênicas, por exemplo, deiscência anastomótica,\nlesão do intestino ou do suprimento\nsanguíneo, laceração do intestino por fios de sutura. Em menor\nincidência estão associadas às condições predisponentes, como a Doença de Crohn, malignidade,\nenterite por radiação, sepse ou trauma.","B":"As fístulas proximais estão associadas a um alto débito, com maior perda hidroeletrolítica. As\nfístulas distais tendem a ter menor débito, tornando seu controle mais fácil.","C":"Fístulas de alto débito são aquelas que eliminam mais de 500 mL em 24 horas.","D":"O emprego da NPT ajuda a minimizar as perdas de fístula de alto débito e para reposição\nnutricional imediata. Após estabilização, uma\nintervenção cirúrgica é necessária na maioria dos\ncasos."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158790","number":"158790","sourceNumber":"158790","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Dadas as cirurgias, I. Tratamento de diverticulite perfurada com peritonite fecal.; II.\nEsplenectomia.; III. Hernioplastia incisional. IV. Hernioplastia inguinal.; V. Cirurgia cardíaca.\nconstituem indicação de antibioticoprofilaxia apenas:","options":{"A":"I e II.","B":"II e IV.","C":"I, III e IV.","D":"I, III e V.","E":"II, III, IV e V."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161384","number":"161384","sourceNumber":"161384","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A aspiração de conteúdo gástrico durante a anestesia é uma complicação incomum,\nporém grave. Segundo as recomendações da ASA, o\ntempo de jejum indicado para o leite materno\né:","options":{"A":"2 horas.","B":"4 horas.","C":"6 horas.","D":"8 horas."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161294","number":"161294","sourceNumber":"161294","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"À qual classe da classificação de Mallampati corresponde a figura a seguir? (Conforme\nimagem do caderno de questões)","options":{"A":"Classe I.","B":"Classe II.","C":"Classe III.","D":"Classe IV."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/161294.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161195","number":"161195","sourceNumber":"161195","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre o Midazolam, assinale a alternativa INCORRETA.","options":{"A":"É uma droga lipossolúvel.","B":"Tem alta ligação com as proteínas plasmáticas.","C":"É metabolizada pelos rins.","D":"Sua farmacocinética é afetada pela obesidade."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158796","number":"158796","sourceNumber":"158796","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente masculino, 36 anos, sem co-morbidades, apresenta-se ao consultório\nreferindo dor e abaulamento em região\ninguinal direita. Foi submetido a hernioplastia inguinal nesse\nlado há 2 anos. Durante o exame físico, foi identificado uma hérnia inguinal indireta com assoalho\ninguinal posterior destruído. Segundo a classificação de Nyhus, é uma hérnia","options":{"A":"IIIa.","B":"IIIb.","C":"IIIc.","D":"IVa.","E":"IVd."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161121","number":"161121","sourceNumber":"161121","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A Dexmedetomidina é usada para sedação prolongada e ansiólise em UTI, bem como\nadjuvante na sala de cirurgia e sedação em unidades de diagnóstico e outras aplicações. Sobre\nesta droga, é CORRETO afirmar que:","options":{"A":"É um beta 2 agonista.","B":"Não tem interferência sobre variáveis cardiovasculares.","C":"Tem efeito sedativo, hipnótico, analgésico e bloqueador neuromuscular.","D":"É ideal para intubação acordada com fibroscópio na via aérea difícil."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161395","number":"161395","sourceNumber":"161395","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação ao Midazolam, assinale a alternativa INCORRETA.","options":{"A":"Naloxona é um antagonista competitivo do receptor benzodiazepínico.","B":"É metabolizado no fígado pelo citocromo P450 e seu principal metabólito é o 1-hidroximidazolam\nque é conjugado com glucuronidases e\nexcretado por via renal.","C":"Tem efeito hipnótico, sedativo, ansiolítico, amnésico, anticonvulsivante e relaxante da\nmusculatura.","D":"Tem interação medicamentosa com drogas antifúngicas, com redução do metabolismo do\nMidazolam."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158815","number":"158815","sourceNumber":"158815","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das alternativas apresenta apenas fios inabsorvíveis?","options":{"A":"Seda, ácido poliglicólico e aço.","B":"Aço, poliglecaprone e categute.","C":"Algodão, poliéster e polipropileno.","D":"Seda, poliglactina e polidioxanona.","E":"Seda, poliglecaprone e polidioxonona."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161333","number":"161333","sourceNumber":"161333","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São soluções comumente usadas em pós-operatórios de cirurgias cardíacas, com\nEXCEÇÃO de:","options":{"A":"sangue total.","B":"concentrado de hemácias.","C":"solução fisiológica 0,9%.","D":"ringer lactato."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161351","number":"161351","sourceNumber":"161351","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação ao controle glicêmico no pós-operatório de cirurgia cardíaca, assinale a\nalternativa CORRETA:","options":{"A":"Iniciar precocemente insulinoterapia se qualquer glicemia for maior do que 180 mg/dl, nas\nprimeiras 6 horas de pós-operatório.","B":"Usar sempre solução fisiológica como manutenção, para evitar hiperglicemia.","C":"Manter controle frequente e glicemia para manter níveis entre 80 e 130 mg/dl.","D":"A circulação extracorpórea, o uso de corticoides, o uso de vasopressores e o estresse cirúrgico\nnormalmente mantêm a glicemia próxima de 180 ? 200 mg/dl nas primeiras 24 horas de\n\npós-operatório, o que é espontaneamente revertido na maioria dos casos."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161293","number":"161293","sourceNumber":"161293","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Julgue os itens seguintes acerca dos métodos não farmacológicos relacionados à\nsedação e à analgesia em emergência\npediátrica. I. Oferecer sucção não nutritiva para os lactentes\nauxilia no controle do desconforto de procedimentos menores; II. A sedação é difícil em crianças\nque se negam a realizar um procedimento, mesmo com sedações moderadas; III. O uso de\nataduras, talas ou tipoias é um método simples que causa a melhora efetiva da dor. Estão\nCORRETOS os itens:","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161397","number":"161397","sourceNumber":"161397","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um dos maiores desafios para o médico é antecipar a possibilidade de manejo de uma\nvia aérea difícil antes da intubação traqueal da criança. Sinais e sintomas sugestivos de via aérea\ndifícil incluem, EXCETO:","options":{"A":"O estridor laríngeo.","B":"O palato em ogiva.","C":"O choro fraco ou ausente.","D":"A história de apneia obstrutiva do sono a história de apneia obstrutiva do sono."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161236","number":"161236","sourceNumber":"161236","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à criança com derrame pleural volumoso, drenado previamente, foi indicada\nnova colocação de dreno de tórax. Aponte a opção que contém, RESPECTIVAMENTE, a sedação\ne a analgesia MAIS apropriadas para a colocação de dreno de tórax.","options":{"A":"Propofol.","B":"Midazolan mais fentanil.","C":"Midazolan mais morfina.","D":"Dexmetomedima."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-161398","number":"161398","sourceNumber":"161398","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Ao escolher um sedativo deve-se utilizar a dose mínima para reduzir a pressão\nintracraniana, sem causar efeitos colaterais,\ncomo a hipotensão. A sedação com analgesia ideal\ninclui todas abaixo, com EXCEÇÃO de uma delas. Indique-a.","options":{"A":"Fármaco de fácil manuseio e de metabolismo bem conhecido.","B":"Fármaco de efeito lento.","C":"Mínimos efeitos cardiovasculares.","D":"Ausência de interações com outros medicamentos."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134274","number":"134274","sourceNumber":"134274","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente apresentando choque cardiogênico não-compressivo, com pressão\ncoloido-oncótica plasmática normal, não\ndesenvolverá edema pulmonar se, na manipulação da\npré-carga, conseguir manter uma pressão capilar pulmonar entre:","options":{"A":"6 a 9 mmHg.","B":"10 a 12 mmHg.","C":"15 a 18 mmHg.","D":"20 a 25 mmHg."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134092","number":"134092","sourceNumber":"134092","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quanto à cicatrização de ferida, aponte a afirmativa INCORRETA.","options":{"A":"Na cicatrização primária tardia, geralmente há contaminação.","B":"A fase de remodelação inicia-se após 21 dias.","C":"Na fase fibroplasia, os linfócitos são os primeiros a entrar na ferida.","D":"Na fase de remodelação, a força tênsil da cicatriz atinge no máximo 80%."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134099","number":"134099","sourceNumber":"134099","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quanto ao colágeno produzido na cicatrização, marque a FALSA.","options":{"A":"É produzido pelo fibroblasto.","B":"Sua produção inicia-se no terceiro dia.","C":"É formado pela hidroxilisina e hidroxiprolina.","D":"Predomina-se colágeno tipo I (20%) e II (80%)."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134283","number":"134283","sourceNumber":"134283","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A insulina promove cada uma das alterações abaixo, com EXCEÇÃO do que consta em\numa alternativa. Aponte-a.","options":{"A":"Gliconeogênese hepática.","B":"Transporte de glicose da membrana para dentro da célula.","C":"Síntese de proteína","D":"Glicogênese."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134125","number":"134125","sourceNumber":"134125","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As citocinas que aparecem precocemente na corrente sanguínea, com efeito\npró-inflamatório em resposta a um estímulo deflagrador são:","options":{"A":"interleucinas 1 e 2, fator de necrose tumoral alfa.","B":"fator de necrose tumoral alfa, interleucinas 3 e 8.","C":"interleucinas 1, 3 e 8.","D":"fator de necrose tumoral, interleucinas 4 e 10."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134287","number":"134287","sourceNumber":"134287","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A principal camada da parede do tubo digestivo responsável pela cicatrização de uma\nanastomose gastrointestinal é","options":{"A":"Mucosa.","B":"Submucosa.","C":"Muscular.","D":"Serosa."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134289","number":"134289","sourceNumber":"134289","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hidratação de um grande queimado deve ser mantida, rotineiramente, durante","options":{"A":"A primeira semana.","B":"As primeiras seis horas.","C":"As primeiras 24 horas.","D":"As primeiras 48 horas."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134295","number":"134295","sourceNumber":"134295","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Nas queimaduras, qual é o organismo oportunista mais frequentemente encontrado?","options":{"A":"Phycomycetes.","B":"Candida sp.","C":"Aspergillus.","D":"Herpes."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134052","number":"134052","sourceNumber":"134052","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quais são as células responsáveis pela contração das feridas abertas formando tecido\nde granulação?","options":{"A":"Miofibroblastos.","B":"Células endoteliais.","C":"Fibras colágenas.","D":"Células epiteliais."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134300","number":"134300","sourceNumber":"134300","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na fase proliferativa do processo de cicatrização das feridas, existe predominância\ncelular de","options":{"A":"Macrófagos.","B":"Neutrófilos.","C":"Fibroblastos.","D":"Linfócitos."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134304","number":"134304","sourceNumber":"134304","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A causa mais comum de deficiência de cicatrização dos tecidos está associada à\nhipovitaminose do tipo","options":{"A":"D.","B":"C.","C":"B.","D":"A."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134059","number":"134059","sourceNumber":"134059","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quando o paciente está em uso de corticoides, para diminuir os efeitos deletérios dessa\nmedicação durante a cicatrização, prescrevemos","options":{"A":"Vitamina C.","B":"Vitamina E.","C":"Zinco.","D":"Vitamina A."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134308","number":"134308","sourceNumber":"134308","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A ulceração observada na cicatriz de uma queimadura profunda é conhecida como\núlcera de","options":{"A":"Barret.","B":"Curling.","C":"Cushing.","D":"Marjolim."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134313","number":"134313","sourceNumber":"134313","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No paciente queimado, vítima de incêndio, deve ser avaliado em primeiro lugar","options":{"A":"As alterações neurológicas.","B":"A extensão das queimaduras.","C":"A profundidade das queimaduras.","D":"Os sinais de agressão à árvore traqueobrônquica."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134066","number":"134066","sourceNumber":"134066","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"?Hérnia inguinal indireta ? anel inguinal interno dilatado, medialmente enrolado ou\ndestruído a fáscia transversalis do triângulo de Hasselbach?. De acordo com a classificação de\nNYHUS para hérnias da região inguinal, esta descrição corresponde à :","options":{"A":"Tipo II.","B":"Tipo IIIA.","C":"Tipo IIIB.","D":"Tipo IIIC."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134319","number":"134319","sourceNumber":"134319","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A contração cicatricial é um fenômeno melhor observado na","options":{"A":"Cicatrização por 2ª intenção.","B":"Cicatrização por 3ª intenção.","C":"Cicatrização por 1ª intenção.","D":"Área doadora de enxertos cutâneos."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134323","number":"134323","sourceNumber":"134323","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O choque primário do grande queimado deve-se:","options":{"A":"Ao distúrbio do centro termorregulador.","B":"À hemorragia tecidual.","C":"Ao desequilíbrio hidrossalino.","D":"À sequestração de plasma."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134847","number":"134847","sourceNumber":"134847","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Analise as afirmativas abaixo relacionadas ao processo de cicatrização da ferida\noperatória e assinale a alternativa CORRETA:\nI. Na primeira semana pós-lesão é inibida a\nneoformação vascular. II. O colágeno só começa a ser produzido de 4 a 14 dias após a lesão (fase\nproliferativa). III. O aumento da resistência da ferida cirúrgica à ruptura está associado ao\nacúmulo\nde colágeno tipo I, na fase proliferativa da cicatrização. É CORRETO o que se afirma em:","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"III, apenas.","D":"I, II e III."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-109720","number":"109720","sourceNumber":"109720","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale abaixo a afirmativa CORRETA.","options":{"A":"A dobutamina é primariamente um agonista dos receptores ß2. Além de seu efeito sobre fibras\nmusculares cardíacas, também atua em musculatura lisa de bronquíolos terminais, tendo potente\nação broncodilatadora.","B":"A noradrenalina é um agonista dos receptores \"alfa\" nas doses habitualmente utilizadas,\npromovendo vasoconstrição periférica,\n\nsendo indicada nos casos de choque anafilático, séptico e neurogênico.","C":"A dopamina tem ação predominante sobre receptores dopaminérgicos localizados em\ntecido renal, mesentérico e cerebral, sendo\nimportante na profilaxia e tratamento da insuficiência\nrenal aguda secundária à sepse.","D":"A adrenalina em baixas doses tem efeito predominante sobre receptores \"alfa\", sendo\nimportante droga no manejo de choques\n\nrefratários ao uso de dopamina ou noradrenalina."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-109756","number":"109756","sourceNumber":"109756","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale abaixo a recomendação para o uso de corticoide no choque séptico.","options":{"A":"Deve ser usado em todo paciente com choque séptico.","B":"Não há indicação de uso de corticoide no choque séptico.","C":"Deve ser utilizado no choque séptico pouco responsivo a fluídos e droga vasoativa.","D":"Deve ser utilizado apenas em choque séptico de foco pulmonar."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-110037","number":"110037","sourceNumber":"110037","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é a sequência CORRETA no processo de cicatrização?","options":{"A":"Vasodilatação, aumento de polimorfonucleares, fibroblastos, neoformação vascular e colágeno.","B":"Vasodilatação, aumento de polimorfonucleares, neoformação vascular, fibroblastos e colágeno.","C":"Aumento de polimorfonucleares, fibroblastos, colágeno, neoformação vascular e vasodilatação.","D":"Neoformação vascular, fibroblastos, vasodilatação, aumento de polimorfonucleares e colágeno."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-109984","number":"109984","sourceNumber":"109984","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As citocinas que aparecem precocemente na corrente sanguínea, com efeito\npró-inflamatório em resposta a um estímulo deflagrador, são:","options":{"A":"interleucinas 1 e 2, fator de necrose tumoral alfa.","B":"fator de necrose tumoral alfa, interleucinas 3 e 8.","C":"interleucinas 1, 3 e 8.","D":"fator de necrose tumoral, interleucinas 4 e 10."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-110038","number":"110038","sourceNumber":"110038","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Nos casos de queimadura elétrica, qual é a forma de acometimento renal?","options":{"A":"Insuficiência renal aguda pré-renal devido à hipotensão causada pelo aumento da\npermeabilidade capilar nas áreas não queimadas.","B":"Microlesões vasculares renais devido à passagem da corrente elétrica pelos rins.","C":"Necrose tubular aguda devido à mioglobinúria consequente a lesão muscular causada pela\nqueimadura elétrica.","D":"Estímulo da secreção inapropriada de hormônio antidiurético."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-110045","number":"110045","sourceNumber":"110045","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é a conduta MAIS adequada frente à criança com queimadura de segundo grau e\nque começa apresentar edema de face e região\ncervical?","options":{"A":"Escarotomia cervicofacial.","B":"Traqueostomia imediata.","C":"Uso de albumina para diminuir o edema.","D":"Intubação oro ou nasotraqueal."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-110051","number":"110051","sourceNumber":"110051","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é a principal causa de mortalidade, nas primeiras 24 horas, de vítimas de\nqueimaduras?","options":{"A":"Incapacidade de retenção de líquidos.","B":"Insuficiência respiratória.","C":"Sepse.","D":"Resposta metabólica ao trauma."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-110056","number":"110056","sourceNumber":"110056","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual principal célula, das citadas abaixo, participa do processo de reparação e\nformação de tecido cicatricial de feridas?","options":{"A":"Matócitos.","B":"Linfócitos.","C":"Macrófagos.","D":"Neutrófilos."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86818","number":"86818","sourceNumber":"86818","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A solicitação da radiografia de tórax na avaliação pré-operatória deve ser realizada nas\nseguintes situações, exceto:","options":{"A":"Idade > 50 anos;","B":"Doença cardíaca;","C":"Doença pulmonar;","D":"Exame físico com sinais de doença cardiopulmonar;","E":"Hipertensão arterial sistêmica."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86792","number":"86792","sourceNumber":"86792","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em função da classificação fisiopatológica do estado de choque, o choque em\ndecorrência da embolia pulmonar é classificado como:","options":{"A":"Hipovolêmico;","B":"Cardiogênico;","C":"Respiratório;","D":"Obstrutivo;","E":"Distributivo."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86797","number":"86797","sourceNumber":"86797","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São fatores indutores da resposta inflamatória complexa (SIRS) associados ao choque\ncirculatório, exceto;","options":{"A":"Radicais livres do oxigênio;","B":"Óxido nítrico;","C":"Endotelinas;","D":"Fator de ativação plaquetária;","E":"Metabólitos do sistema angiotensina."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86807","number":"86807","sourceNumber":"86807","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo a classificação das hérnias (NYHUS, 1989), paciente com hérnia inguinal\nrecidivada é classificada como:","options":{"A":"Tipo I;","B":"Tipo II;","C":"Tipo III;","D":"Tipo IV;","E":"Tipo V."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86812","number":"86812","sourceNumber":"86812","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São causas de abdome agudo inflamatório, exceto;","options":{"A":"Apendicite aguda;","B":"Colecistite aguda;","C":"Diverticulite colônica;","D":"Endometriose;","E":"Megacólon tóxico."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86848","number":"86848","sourceNumber":"86848","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Tríade de Charcot (febre, icterícia, calafrios) é um achado comum em:","options":{"A":"Hepatopatias alcoólicas;","B":"Colangites bacterianas;","C":"Colecistites agudas;","D":"Pancreatite aguda;","E":"Abcesso hepático."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86659","number":"86659","sourceNumber":"86659","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A causa mais comum de obstrução do intestino delgado é:","options":{"A":"Hérnia inguinal.","B":"Hérnia femoral.","C":"Tumores.","D":"Doença de Crohn.","E":"Aderências."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86670","number":"86670","sourceNumber":"86670","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O ligamento inguinal ou de Poupart é composto por fibras da aponeurose do músculo:","options":{"A":"Reto abdominal.","B":"Transversal.","C":"Oblíquo interno.","D":"Serrátil.","E":"Oblíquo externo."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-86662","number":"86662","sourceNumber":"86662","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das estruturas anatômicas abaixo é mais importante na correção da hérnia\ninguinal direta?","options":{"A":"Fáscia tranversalis.","B":"Artéria epigástrica inferior.","C":"Trato ileopubiano.","D":"Ligamento inguinal.","E":"Bainha do reto abdominal"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158424","number":"158424","sourceNumber":"158424","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hérnia inguinal indireta associada à fraqueza da parede posterior ou inguino escrotal\né classificada como:","options":{"A":"Tipo 1.","B":"Tipo 2.","C":"Tipo 3a.","D":"Tipo 3b.","E":"Tipo 4."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158423","number":"158423","sourceNumber":"158423","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que tange à trombose venosa profunda marque a INCORRETA:","options":{"A":"É caracterizada pela oclusão parcial ou total de veia profunda por trombo com inflamação\nprimaria ou secundaria da parede do vaso.","B":"A trombose venosa profunda dos membros inferiores assume interesse particular quer por sua\nalta incidência quer pelo tromboembolismo pulmonar e pelas sequelas de hipertensão venosa\ncrônica que pode provocar.","C":"O acometimento de veias superficiais dos membros inferiores, embora muito frequente, não tem\na mesma importância e gravidade que a das\nveias profundas.","D":"A trombose venosa profunda nem sempre é diagnosticada na fase aguda, podendo determinar\nmorte súbita por embolia pulmonar.","E":"Pacientes submetidos a operações ortopédicas, em especial artroplastia de joelho e quadril\napresentam incidência baixa de trombose venosa profunda."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-108614","number":"108614","sourceNumber":"108614","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação as queimaduras de 3° grau, é verdadeiro:","options":{"A":"Deve-se internar o paciente.","B":"Deve-se realizar a vacinação antitetânica.","C":"Deve-se ter atenção com os distúrbios hidroeletrolíticos.","D":"Deve-se realizar hidratação contínua.","E":"Todas acima."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-49594","number":"49594","sourceNumber":"49594","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No atendimento primário ao queimado:","options":{"A":"O oxigênio a 100% é indicado para todos os casos de pacientes com queimaduras de 30% ou\nmais.","B":"A fórmula Ringer Lactato 2 a 4 ml x Peso em Kg x % de S.C.Q. (Superfície Corpo Queimado) é a\nde consenso para reposição hídrica.","C":"A morfina é a \"pedra fundamental\" no controle da dor severa do queimado, devendo ser\nsubstituída em pacientes depressivos.","D":"Os pacientes com queimaduras de 2° grau em até 30% de S.C.Q. podem ter tratamento\nambulatorial.","E":"O metronidazol é o antibiótico de escolha para a profilaxia."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-362506","number":"362506","sourceNumber":"362506","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, 2 anos de idade, é trazido pela mãe ao pronto socorro,\nqueixando dor inguinal intensa à direita\nhá cerca de 4 horas. Refere aparecimento de \"caroço\" em\nregião inguinal quando a criança chora, desde o nascimento, e que desaparece quando a criança\ndorme. Informa que esta nodulação vem aumentando de volume com o passar do tempo. Ao\nexame físico, observamos abaulamento inguino-escrotal volumoso, doloroso à palpação, irredutível,\nsem sinais flogísticos. Sobre o caso clínico, assinale a alternativa CORRETA:","options":{"A":"O exame físico sugere estrangulamento herniário, estando indicada a ultrassonografia de\nurgência para confirmação diagnóstica e programação cirúrgica.","B":"A complicação descrita acima, classifica a doença como Nyhus IVa.","C":"Caso a redução do abaulamento não seja factível, há indicação de tratamento cirúrgico de\nurgência, com inguinotomia para correção da falha anatomica e laparotomia para enterectomia e\nenteroanastomose.","D":"A redução do abaulamento é dificultada pela dor e pelo choro, estando indicada a analgesia e\nsedação para o procedimento."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-327244","number":"327244","sourceNumber":"327244","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, estivador, fumante inveterado, vem ao\nambulatório de Cirurgia Geral queixando\nquadro de dor e abaulamento em região inguinal direita\naos esforços físicos, com evolução progressiva, há cerca de 4 anos (SIC). Ao exame físico, o\npaciente se encontra hígido, em BEG, LOTE, eupneico, afebril, hemodinamicamente estável. Ao\nexame da região inguinal direita, observa-se abaulamento à manobra de Vassalva, redutível e\ndiscretamente desconfortável à palpação. O paciente trouxe consigo na consulta, uma\nultrassonografia com diagnóstico de hérnia inguinal à direita. A abordagem cirúrgica convencional\nda região inguinal foi indicada e o achado intra-operatório foi de projeção peritoneal sacular que\nse\nprotuía através de laceração de fascia transversalis e seu conteúdo era composto por epíplon. A\nexploração cirúrgica do funículo espermático não demonstrou alterações anatômicas. Sobre os\ndados oferecidos sobre este caso, assinale a alternativa INCORRETA:","options":{"A":"O defeito anatômico observado durante a cirurgia contraindica o uso de tela inorgânica na sua\ncorreção, sendo a técnica de Shouldice a mais recomendada para o caso.","B":"Apesar de jovem, o paciente apresenta quadro de hérnia inguinal adquirida, provavelmente\nocasionada pela associação do tabagismo, esforço físico excessivo e fragilidade da parede\nabdominal.","C":"Podemos classificar o defeito anatômico inguinal deste paciente como Nyhus IIIA.","D":"A ultrassonografia, apesar de exame de imagem adequado para o diagnóstico de hérnias\ninguinais, foi desnecessária tanto na avaliação\nclínica do caso quanto para a decisão terapêutica\nescolhida."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-298212","number":"298212","sourceNumber":"298212","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, 39 anos, portador de hérnia inguino-escrotal à direita\nprocurou o ambulatório de Cirurgia no\nintuito de ser submetido a herniorrafia laparoscópica. O\npaciente é hígido, sem comorbidades e sem histórias de sangramentos anormais, porém apresenta\nsobrepeso. Não faz uso rotineiro de medicações. Nunca foi submetido a transfusões sanguíneas e\nnega cirurgias anteriores. Seus sinais vitais são normais e os exame físico do tórax e abdome não\napresentam alterações. Observa-se herniação inguino-escrotal redutível, indolor à palpação e sem\nsinais flogísticos. Sobre o caso, assinale a alternativa INCORRETA:","options":{"A":"Os dados acima nos permitem concluir que o paciente pode ser classificado quanto ao risco\nanestésico como ASA 1.","B":"O sobrepeso do paciente não contraindica a herniorrafia laparoscópica.","C":"Tanto a herniorrafia laparoscópica (técnica TAPP) quanto a herniorrafia convencional pela\ntécnica Lichtestein indicam antibioticoprofilaxia com cefalosporina de 1ª. Geração.","D":"O fato do paciente ser sobrepeso indica solicitação de radiografia de tórax, ECG e avaliação do\nrisco cardiológico."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-298222","number":"298222","sourceNumber":"298222","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 52 anos, vítima de atropelamento em via pública, foi\ninternada por fratura de bacia e fêmur\nesquerdo, sendo submetida a correção cirúrgica ortopédica.\nNo 2o. PO apresentou quadro de dor e aumento do volume da panturrilha esquerda. Ao exame\nfísico observamos panturrilha esquerda edemaciada, com dilatação de veias superficiais e\nmusculatura empastada, dolorosa à palpação, sobretudo à dorsiflexão passiva do pé. Sobre o caso\ndescrito acima, assinale a alternativa INCORRETA:","options":{"A":"A dosagem de baixos níveis séricos de D- dímero, sobretudo abaixo de 350ng/ml, fecha o\ndiagnóstico da patologia descrita e exclui a necessidade de investigação tomográfica.","B":"Já que podemos considerar a paciente como alto risco para a complicação descrita acima,\npodemos afirmar que havia indicação do uso de heparina de baixo peso molecular desde a\ninternação hospitalar.","C":"A ultrassonografia com doppler além de fechar o diagnóstico, também avalia a extensão do\nacometimento da complicação.","D":"Anticoagulação com heparina não fracionada e antagonistas da vitamina K fazem parte da\nproposta de tratamento inicial desta paciente."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-252245","number":"252245","sourceNumber":"252245","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual a hérnia abdominal é a mais comum na mulher?","options":{"A":"Inguinal","B":"Lombar inferior","C":"Lombar superior","D":"Femoral"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-252246","number":"252246","sourceNumber":"252246","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na avaliação pré-anestésica o anestesista examina a orofaringe para classificar a via\naérea usando a classificação de Mallampati. No exame realizado foi identificado apenas o palato\nduro, não visualizando a úvula e nem os pilares. Qual o Mallampati?","options":{"A":"2","B":"3","C":"4","D":"1"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-208304","number":"208304","sourceNumber":"208304","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os limites constituídos por músculo retoabdominal (medial), músculos oblíquo interno e\ntransverso (superior), músculo iliopsoas (lateral) e pelo ligamento de Cooper e a sínfise de púbis\n(inferior). Corresponde ao:","options":{"A":"Espaço de Retzius","B":"Triângulo de Hasselbach","C":"Orifício miopectíneo de Fruchaud","D":"Espaço de Bogros"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-208424","number":"208424","sourceNumber":"208424","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, 36 anos, refere quadro de dor em virilha direita, aguda,\ndurante uma partida de futebol, com evolução\nde 24h. Nega episódios semelhantes prévios e\nquaisquer comorbidades. Seu exame físico cardiopulmonar e abdominal foi normal. Ao exame da\nregião inguinal direita observamos massa de cerca de 4cm de diâmetro, dolorosa à palpação, não\nredutível, sem sinais flogísticos, que projetava-se abaixo do ligamento inguinal em direção da raiz\nda coxa direita. Assinale a alternativa CORRETA:","options":{"A":"A ultrassonografia é método adequado para efetuar o diagnóstico diferencial com linfadenite","B":"Por tratar-se de hérnia 3C de Nyhus, o reparo laparoscópico está contraindicado","C":"Por tratar-se de hérnia de Richter complicada, há indicação de reparo à Lichtenstein urgente","D":"Já que não há sinais flogísticos, a melhor conduta para o caso é a alta hospitalar com analgesia\noral, compressas mornas e acompanhamento\nambulatorial"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-151861","number":"151861","sourceNumber":"151861","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma hérnia contendo um divertículo de Meckel é denominada:","options":{"A":"Littre.","B":"Amyand.","C":"Spiegel.","D":"Richter."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-151985","number":"151985","sourceNumber":"151985","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 72 anos, vem ao ambulatório de cirurgia com diagnóstico\nultrassonográfico de colelitíase. Refere desconforto em HD (Hipocôndrio Direito) ocasional após\ningesta de gordura, mas já apresentou 2 crises agudas, sendo submetida a tratamento clínico no\npronto socorro, com regressão da sintomatologia. Nega história de icterícia. É diabética e\nhipertensa e faz uso de metformina, losartana e AAS regularmente com controle adequado dos\nníveis pressóricos e glicêmicos. Nega história de precordialgia, infarto do miocárdio ou demais\npatologias cardíacas. Seu estado geral é bom e não tem queixas no momento. Refere fazer suas\natividades diárias sem limitações. Apresenta eletrocardiograma pré-operatório que evidencia\nextra-sístoles supraventriculares, ecocardiograma com alterações típicas para a idade com boa\nfração de ejeção e radiografia de tórax normal. Hemograma e bioquímica sem alterações\nrelevantes. A paciente questiona o cirurgião sobre a possibilidade de ser operada pela via\n\nlaparoscópica. Sobre o preparo pré-operatório desta paciente, assinale a alternativa INCORRETA:","options":{"A":"A losartana não deve ser suspensa, inclusive no dia do procedimento cirúrgico.","B":"O AAS deve ser suspenso 7 a 10 dias antes do procedimento cirúrgico devido a sua ação\nanti-agregante plaquetária que pode resultar em maior sangramento intra-operatório.","C":"A metformina deve ser suspensa na manhã da cirurgia e a Diabetes da paciente deve ser\ncontrolada com uso de insulina regular de acordo com sua glicemia capilar a cada 6h.","D":"Esperamos classificar esta paciente com risco intermediário de complicações anestésicas e\ncardiológicas, com scores ASA 2E e risco cardiológico grau II de Goldman, respectivamente."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-103856","number":"103856","sourceNumber":"103856","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os pacientes com lesão por queimaduras, necessitam de internação em CTQ,\nEXCETO:","options":{"A":"queimaduras envolvendo mãos, pés, face, genitália","B":"queimaduras de espessura parcial maiores que 5% da área de superfície corporal queimada\n(ASCP)","C":"queimaduras químicas","D":"queimaduras associadas à traumas"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-103860","number":"103860","sourceNumber":"103860","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No tratamento inicial do grande queimado qual item deve ser evitado?","options":{"A":"uso de tranquilizantes","B":"oxigênio suplementar","C":"resfriamento da lesão","D":"analgesia"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-81018","number":"81018","sourceNumber":"81018","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, pedreiro, dá entrada no Pronto-Socorro 28 de\nAgosto apresentando dor intensa em região\ninguinal direita após esforço físico excessivo, há 2\nhoras. Nega vômitos e parada de eliminação de flatos. Ao exame físico evidenciou-se hérnia\ninguinal encarcerada, sem sinais flogísticos, bastante dolorosa a palpação, impedindo sua redução.\nAssinale a alternativa que contempla a conduta mais adequada para o caso:","options":{"A":"Analgesia e alta hospitalar para que o paciente seja submetida a herniorrafia eletiva.","B":"Hemorrafia inguinal urgente via laparoscópica.","C":"Internação e aguardar redução espontânea pelo período de 12 horas.","D":"Analgesia potente e nova tentativa de redução.","E":"Deixar o paciente em jejum e descompressão gástrica e retal com sondas."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-81015","number":"81015","sourceNumber":"81015","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo feminino, 46 anos, portadora de constipação intestinal crônica, refere\nque há 2 semanas vem apresentando dor à\ndefecação, fezes endurecidas e presença de raios de\nsangue no papel higiênico durante sua higienização. Qual das alternativas abaixo confere a\nhipótese mais provável, seu método diagnóstico e opção terapêutica?","options":{"A":"Hemorroidas internas grau II; exame proctológico; ligadura elástica.","B":"Fissura anal; inspeção proctológica; creme à base de diltiazem.","C":"Fístula perianal; exame proctológico; fistulotomia.","D":"Neoplasia de reto; retossigmoidoscopia com biópsia; retossigmoidectomia.","E":"Doença de Crohn; colonoscopia; prednisona oral."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-81010","number":"81010","sourceNumber":"81010","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do gênero masculino com 65 anos de idade e peso corporal de 70 kg, sofre\nqueimadura de 2º grau, superficial e profunda, acometendo 30% de superfície corporal. O acidente\nocorreu em nível domiciliar com água fervendo há mais ou menos 5h. Qual o volume total de\nlíquidos que devemos administrar nas primeiras 24h?","options":{"A":"4.200 ml.","B":"8.400 ml.","C":"5.200 ml.","D":"2.500 ml.","E":"12.000 ml."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-61563","number":"61563","sourceNumber":"61563","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher, 17 anos, 55 kg, previamente hígida, atendida em casa pelo SAMU: sonolenta,\nPA inaudível, FC = 120 bpm, Temperatura axilar =\n35°C, FR = 24 ipm, dor à palpação em\nhipogástrio. Amiga informa que ela estava grávida e há uma semana pretendia provocar aborto. No\ncaminho para o PS foram administrados 2.000 ml de ringer lactato e pode-se aferir PA de 85 x 30\nmmHg. Qual diagnóstico provável do caso clínico e que medidas devem ser realizadas na sala de\nemergência?","options":{"A":"Choque séptico com provável foco pélvico, USG pélvica e avaliação do cirurgião/obstetra para\nremoção do foco infeccioso.","B":"Síndrome da Resposta Inflamatória Sistêmica, ausência de foco comprovado e avaliação\nlaboratorial com hemograma, bioquímica e gasometria arterial.","C":"Sepse grave com provável foco pélvico, suspender reposição volêmica até avaliação laboratorial\ncom hemograma, bioquímica e gasometrial arterial.","D":"Choque séptico com provável foco pélvico, expansão volêmica guiada pela PVC ou saturação\nvenosa central O2, avaliação laboratorial,\nculturas, vasopressor e antibioticoterapia empírica.","E":"Sepse grave com provável foco pélvico, expansão volêmica até avaliação laboratorial com\nhemograma, bioquímica e gasometria arterial para decidir sobre antibioticoterapia e início de\nvasopressor."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-60839","number":"60839","sourceNumber":"60839","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à cicatrização das feridas, identifique alternativa INCORRETA:","options":{"A":"São fases da cicatrização: inflamação, proliferação e maturação","B":"Feridas agudas evoluem em um processo reparador ordenado e cronológico","C":"Os tipos de fechamento das feridas são divididos em: reparo primário, secundário, terciário e\nquartenário","D":"O fechamento por intenção secundária não envolve nenhum tipo de procedimento ativo para\nfechar a ferida","E":"O tecido de granulação aparece na fase proliferativa"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-46662","number":"46662","sourceNumber":"46662","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A albumina plasmática é um método excelente para a mensuração do estado\nnutricional. Sua vida média é de:","options":{"A":"9 horas.","B":"2 dias.","C":"9 dias.","D":"21 dias.","E":"28 dias."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-354412","number":"354412","sourceNumber":"354412","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem, 35 anos de idade, procura o ambulatório de cirurgia geral com queixa de\nabaulamento na região inguinal direita há um ano, com aumento de tamanho nos últimos meses. O\npaciente é trabalhador rural e tabagista de 20 cigarros/dia. Nega dor ou outros sintomas\nassociados. Ao exame físico, bom estado geral; abdome plano, flácido e indolor à palpação; região\ninguinal direita com abaulamento redutível à palpação, medindo cerca de 2x2cm, indolor e móvel à\nmanobra de Valsalva. Com base nas informações apresentadas no caso, determine a principal\nsuspeita diagnóstica para o quadro clínico do paciente:","options":{"A":"Lipoma de cordão espermático.","B":"Testículo ectópico.","C":"Hidrocele.","D":"Hérnia inguinal."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-354414","number":"354414","sourceNumber":"354414","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem, 35 anos de idade, procura o ambulatório de cirurgia geral com queixa de\nabaulamento na região inguinal direita há um ano, com aumento de tamanho nos últimos meses. O\npaciente é trabalhador rural e tabagista de 20 cigarros/dia. Nega dor ou outros sintomas\nassociados. Ao exame físico, bom estado geral; abdome plano, flácido e indolor à palpação; região\ninguinal direita com abaulamento redutível à palpação, medindo cerca de 2x2cm, indolor e móvel à\nmanobra de Valsalva. Diante do quadro, identifique a conduta mais adequada para o tratamento\ndeste paciente:","options":{"A":"Observação clínica e caso o paciente evolua com dor na região inguinal, realizar hernioplastia.","B":"Realizar hernioplastia à Shouldice.","C":"Realizar hernioplastia inguinal à Stoppa.","D":"Realizar hernioplastia inguinal sem tensão."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-294463","number":"294463","sourceNumber":"294463","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 40 anos de idade, está no 4º dia de pós-operatório de\ngastroplastia em Y de Roux aberta para tratamento de obesidade mórbida, evolui na enfermaria\ncom dor abdominal difusa, hiporexia, náusea e vômitos. Paciente é portador de diabetes mellitus e\nhipertensão arterial sistêmica. Ao exame físico, regular estado geral, corado. Temperatura axilar =\n37,9ºC; FC = 108 bpm; PA = 128 x 78 mmHg; FR = 20 irpm, ausculta cardíaca e respiratória sem\nalterações, abdome distendido, ruídos hidroaéreos presentes, flácido, dor de grande intensidade\ndifusamente à palpação profunda e ausência de dor à descompressão brusca. De acordo com os\ndados apresentados: Indique a principal suspeita diagnóstica correspondente ao quadro clínico\ndescrito.","options":{"A":"Apendicite aguda.","B":"Deiscência de anastomose intestinal.","C":"Abscesso intra-abdominal.","D":"Tromboembolismo pulmonar."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-294464","number":"294464","sourceNumber":"294464","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 40 anos de idade, está no 4º dia de pós-operatório de\ngastroplastia em Y de Roux aberta para tratamento de obesidade mórbida, evolui na enfermaria\ncom dor abdominal difusa, hiporexia, náusea e vômitos. Paciente é portador de diabetes mellitus e\nhipertensão arterial sistêmica. Ao exame físico, regular estado geral, corado. Temperatura axilar =\n37,9ºC; FC = 108 bpm; PA = 128 x 78 mmHg; FR = 20 irpm, ausculta cardíaca e respiratória sem\nalterações, abdome distendido, ruídos hidroaéreos presentes, flácido, dor de grande intensidade\ndifusamente à palpação profunda e ausência de dor à descompressão brusca. De acordo com os\ndados apresentados: Para a confirmação diagnóstica da suspeita principal, será decisiva a\nrealização de:","options":{"A":"Radiografias de abdome agudo e hemograma.","B":"Tomografia computadorizada de abdome e pelve com contraste.","C":"Angiotomografia computadorizada de tórax.","D":"Hemograma, hemocultura e PCR."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-294465","number":"294465","sourceNumber":"294465","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 40 anos de idade, está no 4º dia de pós-operatório de\ngastroplastia em Y de Roux aberta para tratamento de obesidade mórbida, evolui na enfermaria\ncom dor abdominal difusa, hiporexia, náusea e vômitos. Paciente é portador de diabetes mellitus e\nhipertensão arterial sistêmica. Ao exame físico, regular estado geral, corado. Temperatura axilar =\n37,9ºC; FC = 108 bpm; PA = 128 x 78 mmHg; FR = 20 irpm, ausculta cardíaca e respiratória sem\nalterações, abdome distendido, ruídos hidroaéreos presentes, flácido, dor de grande intensidade\ndifusamente à palpação profunda e ausência de dor à descompressão brusca. De acordo com os\ndados apresentados: Indique a conduta terapêutica mais adequada para esse paciente.","options":{"A":"Realizar laparotomia exploradora.","B":"Fazer terapia antibiótica endovenosa.","C":"Realizar drenagem guiada por ultrassonografia.","D":"Fazer anticoagulação plena com enoxaparina."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-62858","number":"62858","sourceNumber":"62858","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 19 anos de idade, vítima de acidente automobilístico, estava\nno banco carona do automóvel, onde o\nmotorista faleceu no local do evento. O acidente aconteceu\nhá duas horas e o paciente foi transportado ao Centro de Trauma pelo Serviço Médico de\nEmergência, adentrando à sala de emergência transportado em maca, acordado, fásico,\ndesorientado no tempo e no espaço, com abertura ocular e movimentos espontâneos, mucosas\ndescoradas +++/IV. Dados vitais - pressão arterial: 96 x 54 mmHg, pulso radial: 132 bpm (filiforme),\nfrequência respiratória: 30 ipm. De acordo com o quadro descrito, pode-se concluir que a pressão\narterial média do paciente é de:","options":{"A":"65 mmHg.","B":"68 mmHg.","C":"72 mmHg.","D":"75 mmHg.","E":"78 mmHg."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-332614","number":"332614","sourceNumber":"332614","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre problemas cirúrgicos mais prevalentes na infância, assinale a alternativa correta:","options":{"A":"Todos os casos suspeitos de hérnia inguinal demandam realização de ultrassonografia da região\npara confirmar o diagnóstico e, caso haja confirmação, o encaminhamento imediato para\ntratamento cirúrgico.","B":"A hérnia umbilical raramente provoca dor ou desconforto e nesses casos a criança deve ser\nobservada até pelo menos 2 anos de idade, podendo a observação seguir até o sétimo ou oitavo\nano de vida se houver fechamento gradual do anel umbilical.","C":"Crianças com criptorquidia unilateral devem, após confirmação da presença do testículo na\ncavidade abdominal por exames de imagem,\nreceber tratamento hormonal até o final do primeiro\nano de vida, estando o tratamento cirúrgico reservado para os casos de insucesso na terapia\ninicial.","D":"A presença de fimose em meninos com mais de 5 anos de idade sugere a necessidade de\ntratamento cirúrgico, pelo risco aumentado de\ndesenvolvimento de infecções do trato urinário (ITU)\nnesses casos.","E":"A diástase dos músculos retos abdominais é um fator predisponente para a hérnia epigástrica e\npor isso demanda tratamento cirúrgico se não apresentar resolução espontânea até o final do\nprimeiro ano de vida."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343383","number":"343383","sourceNumber":"343383","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Primariamente, a recorrência Tromboembolismo Venoso após o término da\nanticoagulação depende de fatores:","options":{"A":"Caso a TVP aguda não foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores de risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e as trombofilias.","B":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, reduziram a\nrecorrência, notadamente a doença maligna e as trombofilias.","C":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e nunca as trombofilias.","D":"Caso a TVP aguda foi tratada efetivamente, incluindo a duração mínima do tratamento\nanticoagulante; e, segundo a presença de fatores\nde risco intrínsecos que, de fato, aumentam a\nrecorrência, notadamente a doença maligna e as trombofilias."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283844","number":"283844","sourceNumber":"283844","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente 20 anos, apresenta lesão corto-contusa em antebraço de 4,0 cm, envolvendo\npele e tecido celular subcutâneo. Considerando\nque o evento ocorreu há 5 horas, a melhor opção\npara sutura da pele é","options":{"A":"contínua com fio inabsorvível (nylon).","B":"contínua com fio absorvível (poligalactina).","C":"em pontos separados com fio absorvível (categute).","D":"em pontos separados simples com fio inabsorvível (nylon).","E":"em pontos separados (\"\"X\"\"interno) com fio absorvível (categute)."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-249719","number":"249719","sourceNumber":"249719","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A alternativa que contém o tipo de hérnia com maior risco de estrangulamento é","options":{"A":"femural.","B":"umbilical.","C":"incisional.","D":"inguinal direta.","E":"inguinal indireta."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-250002","number":"250002","sourceNumber":"250002","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 53 anos, internado na enfermaria da ortopedia há 3 dias por fratura de\nfêmur, aguardando cirurgia. Após discussão com a\nequipe, opta-se por adiantar a cirurgia para data\nde hoje, porém o paciente recebeu 1mg/kg de enoxaparina há 2 horas. A técnica anestésica que\ndeve ser utilizada neste caso é:","options":{"A":"Anestesia peridural com cateter.","B":"Raquianestesia.","C":"Anestesia peridural sem cateter.","D":"Anestesia geral."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-218117","number":"218117","sourceNumber":"218117","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"\"O objetivo principal do tratamento nos traumatismos superficiais é restabelecer a\nintegridade anatômica e funcional dos tecidos, sem se esquecer do aspecto estético, às vezes, de\ngrande importância\" (BRASIL, 2011, p. 43). Sobre o tratamento de feridas, é CORRETO afirmar\nque:","options":{"A":"O tratamento aberto é contraindicado nas feridas infectadas.","B":"O fechamento secundário é reservado somente para as feridas limpas, com pequeno risco de\ninfecção.","C":"O fechamento primário é indicado nas feridas cujos tecidos estejam com suprimento sanguíneo\ninadequado.","D":"O fechamento primário é contraindicado quando há impossibilidade técnica de aproximação das\nbordas da ferida em consequência de perda de pele e tecido celular subcutâneo.","E":"O fechamento primário é reservado para feridas com maior risco de infecção, seja pelo alto grau\nde contaminação, seja pelo longo tempo decorrido\nentre a lesão e a procura de tratamento."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-215576","number":"215576","sourceNumber":"215576","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das alternativas NÃO é um fio inabsorvível?","options":{"A":"Categute cromado.","B":"Fio de seda.","C":"Poliéster.","D":"Polipropileno."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-157642","number":"157642","sourceNumber":"157642","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"É inegável a fundamental importância da participação neuroendócrina na resultante do\nquadro clínico dos pacientes submetidos à agressão cirúrgica. Sobre as alterações endócrinas,\nmarque a opção INCORRETA:","options":{"A":"Ocorre liberação rápida de adrenalina e noradrenalina, e em cirurgias de grande porte,\npermanecem elevadas por 12 a 48 horas. As\ncatecolaminas interferem no metabolismo por ação\ndireta nos fenômenos de glicogenólise, neoglicogênese, utilização de aminoácidos musculares,\nhidrólise de gorduras e liberação de ácidos graxos.","B":"Independente da condição de tendência a hiperglicemia no pós-operatório, os níveis de\nglucagon aumentam, esse aumento propicia a degradação da glicose, bloqueia a formação de\nglicogênio e propicia a transformação no fígado, de aminoácidos em glicose.","C":"Nas cirurgias de médio e grande porte, a secreção de aldosterona encontra-se diminuída,\ndeterminando diminuição da excreção dos íons\nsódio e bicarbonato, com produção de urina com\nelevado teor de íons hidrogênio e com alto teor de potássio.","D":"A zona traumatizada desencadeia estímulos que determinam a elevação do Hormônio\nAntidiurético. Geralmente esta elevação permanece até o quarto ou quinto dia."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-157711","number":"157711","sourceNumber":"157711","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As lesões térmicas constituem causa importante de morbidade e mortalidade. Segundo\na Regra dos Nove, uma vítima com queimaduras\nna região posterior da cabeça, tórax e pernas tem\numa extensão em porcentagem de superfície corporal queimada de, APROXIMADAMENTE,","options":{"A":"30%.","B":"40%.","C":"50%.","D":"60%."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-162485","number":"162485","sourceNumber":"162485","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Gilberto, 38 anos, ao fazer o café derruba a panela e a água quente cai no chão e\nrespinga no seu braço. Ele vai logo em\nseguida para a unidade de saúde da família que você é\nresidente. Na avaliação, você percebe uma flictena em antebraço esquerdo. Refere dor no local da\nlesão. Em relação a esse quadro, é correto afirmar que","options":{"A":"o tratamento da queimadura poderá ser inteiramente realizado na Unidade de Saúde da Família\n(USF).","B":"Gilberto tem área corporal queimada de cerca de 20%.","C":"a Tabela de Lund-Browder para a classificação de superfície corporal queimada é utilizada,\nprincipalmente, na Atenção Básica.","D":"a melhor conduta a ser feita é lavar com água e passar manteiga.","E":"a hospitalização para tratamento em um centro de tratamento especializado está indicada."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-157657","number":"157657","sourceNumber":"157657","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A terapia nutricional precoce apresenta, como vantagem,","options":{"A":"A redução do número de mitoses e divisões celulares na mucosa intestinal.","B":"evitar o uso do leite materno com a utilização de alimentos substitutos mais adequados no\nperíodo neonatal.","C":"a liberação de colecistoquinina, essencial na função trófica do enterócito.","D":"O descarte da utilização de terapia parental."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-157667","number":"157667","sourceNumber":"157667","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quanto à administração de nutrientes com a terapia nutricional parenteral, assinale a\nalternativa CORRETA.","options":{"A":"A concentração máxima de glicose por via periférica deve ser de 20%.","B":"Na via central, não pode ser utilizada concentração de glicose abaixo de 20%.","C":"Os micronutrientes são desnecessários nos primeiros sete dias de terapia nutricional parenteral\nexclusiva.","D":"A oferta de triglicerídeos de cadeia longa é importante na prevenção de deficiência de ácidos\ngraxos essenciais."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-157646","number":"157646","sourceNumber":"157646","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Foi solicitado que apresentasse sua opinião a respeito do seguinte quadro clínico.\nAnalise-o. Paciente masculino, 50 anos de idade,\ncom quadro de hérnia inguinal não complicada.\nFoi agendada cirurgia eletiva a fim de corrigir essa hérnia. Como o paciente é diabético, você foi\nacionado para o parecer clínico, no qual foi solicitado posicionamento sobre a diferenciação desse\nseu caso em relação aos de pacientes não diabéticos. Seu parecer foi muito elogiado, com\nEXCEÇÃO de um dos pareceres a seguir, que se mostrava INADEQUADO. Assinale-o.","options":{"A":"O DM está associado a um aumento do risco de infecções em feridas operatórias.","B":"Infecções perioperatórias no DM tem seu risco alterado, possivelmente por um efeito deletério da\nhiperglicemia na quimiotaxia, fagocitose e aderência de granulócitos.","C":"Infecções aumentam o risco de hiperglicemia em pacientes com DM.","D":"A melhora do controle glicêmico no período perioperatório não consegue reduzir o risco de\ninfecções em pacientes submetidos à cirurgia."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-139772","number":"139772","sourceNumber":"139772","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Analise as afirmativas abaixo relacionadas ao processo de cicatrização da ferida\noperatória. I. Na primeira semana pós-lesão é\ninibida a neoformação vascular.; II. O colágeno só\ncomeça a ser produzido 4 a 14 dias após a lesão (fase proliferativa).; III. O aumento da resistência\nda ferida cirúrgica à ruptura está associado ao acúmulo de colágeno tipoI, na fase proliferativa da\ncicatrização. É CORRETO, APENAS, o que se afirma em:","options":{"A":"I.","B":"I e II.","C":"III.","D":"II e III."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134728","number":"134728","sourceNumber":"134728","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As catecolaminas adrenalina e noradrenalina são fundamentais na resposta\ninflamatória ao trauma. São as principais responsáveis por:","options":{"A":"Taquicardia, Taquipneia, Vasoconstrição periférica e aumento do débito cardíaco.","B":"Bradicardia, Taquipneia, Vasoconstrição periférica e diminuição do débito cardíaco.","C":"Taquicardia, Taquipneia, Vasoconstrição periférica e diminuição do débito cardíaco.","D":"Bradicardia, Taquipneia, Vasoconstrição periférica e aumento do débito cardíaco."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134761","number":"134761","sourceNumber":"134761","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quanto ao colágeno produzido na cicatrização, marque a FALSA.","options":{"A":"É produzido pelo Fibroblasto.","B":"Sua produção inicia-se no terceiro dia.","C":"É formado pela Hidroxilisina e Hidroxiprolina.","D":"Predomina-se Colágeno tipo I (20%) e II (80%)."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134727","number":"134727","sourceNumber":"134727","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Dos fatores citados abaixo, qual apresenta MENOR influência no processo de\ncicatrização das feridas?","options":{"A":"Desnutrição.","B":"Corticoides.","C":"Diabetes mellitus.","D":"Hemoglobina = 10 g/dl."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-134740","number":"134740","sourceNumber":"134740","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual é o papel dos macrófagos no processo de cicatrização?","options":{"A":"Ocasiona perda de plasma através da ativação da serotonina e histamina.","B":"Induz à apoptose dos polimorfonucleares.","C":"Estimula a liberação do fator de agregação plaquetária.","D":"Estimula a liberação de fatores quimiotáticos para neutrófilos."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-111919","number":"111919","sourceNumber":"111919","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa CORRETA quanto aos fatores que interferem na cicatrização da\nferida operatória.","options":{"A":"Desvitalização tecidual e necrose, presença de corpo estranho, infecção e radioterapia são\nfatores sistêmicos.","B":"Nutrição, proteínas, corticoides e anti-inflamatórios não esteroidais. Idade avançada e diabetes\nsão fatores locais.","C":"Desvitalização tecidual e necrose, presença de corpo estranho, infecção e radioterapia são\nfatores locais.","D":"Nutrição, proteínas, corticoides e anti-inflamatórios não esteroidais, idade avançada e diabetes\nsão fatores sistêmicos."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-111852","number":"111852","sourceNumber":"111852","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As catecolaminas, adrenalina e noradrenalina, são fundamentais na resposta\ninflamatória ao trauma. São as principais responsáveis por:","options":{"A":"taquicardia, taquipneia, vasoconstrição periférica e aumento do débito cardíaco.","B":"bradicardia, taquipneia, vasoconstrição periférica e diminuição do débito cardíaco.","C":"taquicardia, taquipneia, vasoconstrição periférica e diminuição do débito cardíaco.","D":"bradicardia, taquipneia, vasoconstrição periférica e aumento do débito cardíaco."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-350802","number":"350802","sourceNumber":"350802","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 64 anos está sendo preparado para realizar uma hepatectomia direita\npor neoplasia. Obedecendo as diretrizes de\nSegurança do Paciente Cirúrgico, qual o melhor\nmomento para a equipe confirmar a reserva sanguínea?","options":{"A":"Na consulta pré-operatória com o cirurgião.","B":"Após avaliar a ressecabilidade do tumor.","C":"Antes da indução anestésica.","D":"Antes da incisão cirúrgica."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-350872","number":"350872","sourceNumber":"350872","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quatro anos após a gastroplastia, um homem de 45 anos busca o cirurgião plástico\npara realizar uma abdominoplastia com\ndermolipectomia e correção de diástase de retos\nabdominais. Seu IMC atual é 24 kg/m² e não apresenta intercorrências clínicas importantes. A\nprevisão de duração da cirurgia é de 4 horas. Com relação à prevenção de infecção operatória qual\ndas seguintes medidas é a mais importante para esse caso?","options":{"A":"Realização de tricotomia abdominal.","B":"Irrigação do subcutâneo com antibiótico tópico.","C":"Uso de antibioticoprofilaxia na indução anestésica.","D":"Preparo da pele com antissépticos à base de álcool."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-350859","number":"350859","sourceNumber":"350859","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre as técnicas clássicas de reparo das hérnias inguinais, qual das seguintes, usa a\ntela como principal elemento para reconstrução do assoalho inguinal?","options":{"A":"Técnica de Bassini.","B":"Técnica de McVay.","C":"Técnica de Shouldice.","D":"Técnica de Lichtenstein."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-350855","number":"350855","sourceNumber":"350855","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Esse gás anestésico apresenta as seguintes características: baixo indutor de\ndepressão cardíaca e respiratória, possui rápido\nadormecer e despertar, não deve ser usado como\nsubstância única na manutenção de anestesia profunda, está associado a náuseas e vômitos\n\npós-anestésicos e é frequentemente utilizado para sedação consciente. A qual dos seguintes gases\nanestésicos essas características se refere?","options":{"A":"Éter.","B":"Halotano.","C":"Isoflurano.","D":"Óxido Nitroso."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321277","number":"321277","sourceNumber":"321277","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma menina de 8 anos é admitida para realização de uma cirurgia eletiva para remoção\nde amígdalas sob anestesia geral. Sua mãe\ninforma que sua última refeição foi cerca de 150ml de\nsuco de laranja e um sanduíche de presunto, às 6:00 da manhã. Com relação ao jejum\n\npré-operatório, a partir de que horas o anestesiologista poderá iniciar a indução anestésica da\ncriança?","options":{"A":"A partir das 8:00.","B":"A partir das 10:00.","C":"A partir das 12:00.","D":"A partir das 14:00."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321279","number":"321279","sourceNumber":"321279","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente previamente saudável, ASA I, será submetida a histerectomia eletiva por\nvia transvaginal devido a mioma uterino. Qual a recomendação de uso de antibiótico para essa\nsituação?","options":{"A":"Cefalexina 500 mg VO de 6/6 horas por 5 dias.","B":"Cefalexina 500 mg 6/6h se apresentar alguma infecção.","C":"Cefazolina 2 g EV 60min antes do início da cirurgia.","D":"Cefazolina 2 g EV antes do início da cirurgia e de 8/8h até a alta hospitalar."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321280","number":"321280","sourceNumber":"321280","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma mulher de 22 anos, após sua primeira gestação, a termo, há 4 meses, comparece\nao ambulatório de cirurgia geral com queixa de\nabaulamento abdominal. Ela refere que o parto foi\npor via vaginal. Durante a gestação houve aumento de 16 quilos, atualmente já está no seu peso\nhabitual, no entanto, apresenta projeção abdominal da linha média com abaulamento paradoxal\napós contratura dos retos abdominais, conforme figura a seguir. A ultrassonografia da parede\nabdominal demonstra linha média íntegra, delgada com afastamento dos músculos retos em 5\ncentímetros entre si. Conferir figura correspondente com melhor resolução no anexo (FIGURA 1)\nNesse momento, qual a melhor conduta para essa paciente?","options":{"A":"Indicar plicatura de retos com abdominoplastia.","B":"Orientar atividades físicas e observar sintomas.","C":"Corrigir a falha com aposição de tela de proliporpileno.","D":"Programar aproximação dos retos por via supraumbilical."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/321280.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321289","number":"321289","sourceNumber":"321289","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Menino de 11 meses de vida, nascido de parto prematuro, é acompanhado pela mãe\nem consulta com cirurgião, devido a hérnia\ninguinoscrotal. Ela refere que o aumento da bolsa\nescrotal é mais pronunciado à tarde e durante o choro, e menor, ao acordar. Ao exame: bolsa\nescrotal cheia parcialmente redutível. Qual a classificação provável dessa hérnia, segundo Nihus?","options":{"A":"Nihus I.","B":"Nihus II.","C":"Nihus III a.","D":"Nihus III b."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321290","number":"321290","sourceNumber":"321290","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher de 55 anos faz uso crônico de varfarina 5mg ao dia, devido trombose venosa\nprofunda há 4 meses. A paciente é diabética\ne apresenta uma infecção grave na perna. Devido a\npiora do quadro e odor, ela foi à emergência, onde foi indicada amputação suprapatelar, devido a\ngangrena úmida. INR do dia: 3. O que a equipe cirúrgica deve fazer para diminuir o risco de\nsangramento durante a amputação?","options":{"A":"Suspender o varfarina, transfundir plaquetas.","B":"Suspender o varfarina, aplicar sulfato de protamina.","C":"Suspender o varfarina, realizar a amputação em 5 dias.","D":"Suspender o varfarina, aplicar vitamina K e reservar plasma."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-292791","number":"292791","sourceNumber":"292791","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na Unidade de Pronto Atendimento (UPA), uma mulher de 65 anos é admitida com\nquadro de vômitos por obstrução neoplásica\npré-pilórica, desidratação e ingesta oral zero, aguarda\ntransferência para um hospital terciário. Vem recebendo hidratação e suporte calórico por meio de\nsoro glicosado a 5%. Após três dias de espera, queixando-se de cefaleia refratária a dipirona,\napresenta episódio de convulsão. Qual a causa provável da crise convulsiva dessa paciente?","options":{"A":"Hiponatremia.","B":"Hiperglicemia.","C":"Metátase em SNC.","D":"Alcalose metabólica."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-292793","number":"292793","sourceNumber":"292793","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A suplementação com líquidos sem resíduos, ricos em carboidratos (líquidos claros),\napresenta vantagem quando ingeridos no preparo de pacientes para cirurgias eletivas. Até quanto\ntempo antes da cirurgia é segura a ingesta desse tipo de substância para um paciente eutrófico\nASA I que será submetido a uma cirurgia ortopédica?","options":{"A":"2h antes da cirurgia.","B":"6h antes da cirurgia.","C":"8h antes da cirurgia.","D":"12h antes da cirurgia."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-292797","number":"292797","sourceNumber":"292797","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um jovem de 28 anos, atleta de natação, será submetido a abdominoplastia após\nperder 45 kg por cirurgia bariátrica, há 3\nanos, e mudança em hábitos de vida. Qual das seguintes\nmedidas apresenta maior impacto na prevenção de infecção do sítio cirúrgico para esse paciente?","options":{"A":"Uso de drenos de sucção e remoção de pelos abdominais.","B":"Tempo cirúrgico abreviado e uso criterioso do eletrocautério.","C":"Uso de antibiótico profilaxia 1h antes da realização da incisão.","D":"Suplementação pré-operatória hipocalórica e com alto teor de proteína."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-292798","number":"292798","sourceNumber":"292798","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um homem submetido a duodenopancreatectomia por neoplasia de pâncreas\nencontra-se no 6o pós-operatório e está com\ndieta oral líquida 50 ml a cada 3h, associada à\nnutrição enteral 1500ml/d. O paciente refere dor abdominal. Ao examinar o paciente, o médico\n\npercebe dor abdominal difusa e eliminação de secreção esverdeada em ferida operatória. Diante do\nquadro, qual deve ser a conduta médica?","options":{"A":"Solicitar tomografia para avaliar a necessidade de drenagem de coleções.","B":"Abrir protocolo sepse e indicar laparotomia exploradora de urgência.","C":"Alimentar o paciente por sonda nasoenteral com dieta oligomérica.","D":"Suspender a dieta, iniciar NPT e antibióticos e reavaliar após 24h."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-292803","number":"292803","sourceNumber":"292803","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 54 anos queixa-se de dor e assimetria abdominal do lado direito, logo\nabaixo da linha da cintura e lateral ao músculo reto abdominal. Ao exame, percebe-se a dor a\npalpação dessa região e leve abaulamento. Uma tomografia revela protrusão e conteúdo abdominal\nentre as camadas musculares da parede abdominal lateral, com aponeurose do músculo oblíquo\nexterno íntegra. A paciente refere cirurgia cesariana prévia há 25 anos. Nega outras cirurgias. Qual\na causa da dor dessa paciente?","options":{"A":"Hérnia incisional.","B":"Tumor desmoide.","C":"Hérnia de Spiegel.","D":"Implante endometrial."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-259691","number":"259691","sourceNumber":"259691","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo masculino, 47 anos, diabético e com ferida em perna esquerda há 6\nmeses, comparece ao posto de saúde para avaliação médica. O médico deverá descobrir a ferida\npara avaliar fatores que contribuem para cronificação do processo de cicatrização. Qual opção\nmelhor sugere a necessidade de debridamento cirúrgico?","options":{"A":"Presença de tecido fibrinoso e bordas difusas.","B":"Presença de corpo estranho e bordas aderidas.","C":"Presença de tecido necrótico e colonização bacteriana.","D":"Presença de tecido de granulação e bordas maceradas."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-259693","number":"259693","sourceNumber":"259693","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher, 45 anos de idade, portadora de púrpura trombocitopênica idiopática\n\nencontra-se internada por anemia refratária e sangramento vaginal excessivo e persistente. Após\ninício de terapia medicamentosa e realização\nde exames complementares foi decidido pela\nhisterectomia. Qual medida profilática para eventos tromboembólicos está indicada nessa situação?","options":{"A":"Deambulação precoce.","B":"Rivaroxabana 10 mg VO por 7 dias.","C":"Compressão pneumática intermitente.","D":"Enoxaparina 40 mg SC 1x dia por 7 dias."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-259694","number":"259694","sourceNumber":"259694","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Após 1 (uma) hora do início de uma gastrectomia total com linfadenectomia a D2 por\num adenocarcinoma moderadamente diferenciado em\nfundo gástrico, houve laceração da veia\nesplênica e volumoso sangramento. O paciente foi estabilizado com solução cristaloide e\nconcentrado de hemácias e a cirurgia flui normalmente com previsão de duração de 3 horas. Qual\nconduta em relação a antibioticoprofilaxia deve ser adotada pela equipe?","options":{"A":"Reaplicar Cefazolina agora.","B":"Manter Cefazolina de 8/8h por 24 horas.","C":"Reaplicar Cefazolina 4 horas após a indução.","D":"Repetir Cefazolina se a cirurgia durar 4 horas."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-259698","number":"259698","sourceNumber":"259698","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente foi submetida a uma gastrectomia parcial sob anestesia geral e relata aos\nfamiliares e médico que \"lembra\" de eventos ocorridos no transoperatório. A consciência operatória\npoderia ser minimizada através de qual das seguintes ações?","options":{"A":"Manutenção venosa com morfina.","B":"Manutenção do BIS em torno de 50-60.","C":"Reaplicação de pancurônio ao final da cirurgia.","D":"Manutenção da PAM em torno de 60-70 mmHg."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-259702","number":"259702","sourceNumber":"259702","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo feminino, 37 anos, primípara, deu entrada na emergência com quadro\nde dor em hemiabdome direito, de início\nsúbito e de forte intensidade. Ao exame, apresentava-se\nestável hemodinamicamente, com massa dolorosa palpável no quadrante superior direito,\ndescompressão brusca dolorosa e presença de equimose periumbilical. Os exames laboratoriais\nmostravam anemia discreta, leucócitos e plaquetas sem alterações. US compatível com hematoma\nde reto abdominal. Na história patológica pregressa, a paciente relatava três abortos prévios e um\nepisódio de TVP em perna esquerda há 6 meses. Está em uso de clexane dose profilática. Qual o\ntratamento recomendado para esta paciente?","options":{"A":"Repouso e analgésicos.","B":"Suspensão do anticoagulante.","C":"Embolização do vaso sangrante.","D":"Exploração e drenagem do hematoma."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-234004","number":"234004","sourceNumber":"234004","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 38 anos foi internada no plantão noturno para realizar cirurgia no dia\nseguinte. Na checagem de rotina dos exames pré-operatórios, a enfermeira do setor acionou o\nplantonista da cirurgia, pois a dosagem de hemoglobina da paciente era de 7,6 g/dl. Na avaliação\nmédica, constatou-se que a paciente estava assintomática, não tinha comorbidades, não fazia uso\nde medicações regulares, a frequência cardíaca era de 88 bpm/minuto, a pressão arterial era de\n110 x 70 mmHg e iria ser submetida a uma histerectomia em decorrência de miomatose uterina\nassociada à hipermenorreia. A prescrição deixada pela equipe assistente constava apenas de\njejum, aferição de dados vitais e medicações sintomáticas. Qual deve ser a conduta do plantonista?","options":{"A":"Prescrever ferro por via endovenosa.","B":"Transfundir concentrado de hemácias.","C":"Manter a prescrição da equipe assistente.","D":"Prescrever eritropoietina por via endovenosa."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-234008","number":"234008","sourceNumber":"234008","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, sexo feminino, 21 anos, foi admitida na UPA, com quadro de dor súbita em\nandar inferior do abdômen que depois se\ngeneralizou, febre e relatos de \"sensação de falta de ar\",\nsem conseguir se alimentar ou urinar nas últimas 8 horas. Relata que foi operada há 5 dias em\ndecorrência de ser portadora de endometriose profunda. No relatório de alta havia a informação\nque fora submetida à ressecção dos focos endometrióticos e retossigmoidectomia segmentar com\nanastomose colorretal terminoterminal mecânica, por via laparoscópica, sem intercorrências e\nrecebendo alta no 3° dia de pós-operatório. À admissão, tinha fácies de dor, palidez\n\ncutâneo-mucosa, taquicardia (FC = 144 bpm), taquipneia (FR = 37 irpm), no abdômen havia\naumento da tensão abdominal com dor à\npalpação superficial e profunda e descompressão brusca\npositiva em todo o abdômen. Qual a hipótese diagnóstica mais provável?","options":{"A":"Retenc?a?o urina?ria aguda.","B":"Endomiometrite po?s-ciru?rgica.","C":"Deisce?ncia de anastomose intestinal.","D":"Sangramento de foco endometrio?tico residual."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-234019","number":"234019","sourceNumber":"234019","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 54 anos foi internado a? noite para realizar procedimento ciru?rgico de\ngrande porte (gastrectomia total) na manha? seguinte. Tem relato de ser diabe?tico em uso de\nhipoglicemiante oral (sulfonilureia) e trouxe o resultado (ainda na?o checado pela equipe\nassistente) de hemoglobina A1c realizado ha? uma semana (7%), a func?a?o renal era normal. A\ncirurgia esta? prevista para ocorrer a?s 11 horas da manha? seguinte. Como deve ser a conduta do\nme?dico plantonista quanto a?s orientac?o?es pre?-operato?rias desse paciente?","options":{"A":"Suspender a sulfonilureia e prescrever insulina de curta durac?a?o sob demanda.","B":"Suspender a cirurgia com base no valor de HbA1c e risco de complicac?o?es.","C":"Prescrever o hipoglicemiante oral com pouca a?gua na manha? do procedimento.","D":"Prescrever insulina de longa durac?a?o na ve?spera da cirurgia e suspender a sulfonilureia."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-199657","number":"199657","sourceNumber":"199657","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 68 anos, assintomático, foi submetido à colonoscopia com biópsia há\ncerca de 2 semanas, que evidenciou\nadenocarcinoma de cólon direito. Na ocasião, ele apresentou\nepisódio de angina durante a recuperação e necessitou de observação clínica intra-hospitalar por\n24 horas. Ele é obeso, sedentário e dislipidêmico. Qual deve ser a conduta antes da cirurgia?","options":{"A":"Realizar minimamente um teste cardiológico não invasivo para isquemia.","B":"Contraindicar a cirurgia até completar três meses do episódio de angina.","C":"Considerá-lo apto à cirurgia caso não apresente isquemia no eletrocardiograma.","D":"Realizar obrigatoriamente um teste cardiológico invasivo (cineangiocoronariografia)."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-199652","number":"199652","sourceNumber":"199652","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem, 43 anos, em tratamento de artrite reumatoide com prednisona há 5 meses,\nencontra-se no 60° dia de Pós-Operatório (PO) de apendicectomia por apendicite complicada. No\n7° dia de pós-operatório, apresentou drenagem de secreção entérica fecaloide pela Ferida\nOperatória (FO), quando fez tratamento com ciprofloxacino e metronidazol por 14 dias. Desde\nentão evolui afebril, com abdome flácido, sem dor a descompressão brusca e com presença de\nextrusão mucosa em FO. O leucograma tem parâmetros de normalidade. Apesar das medidas\nclínicas adotadas, o débito da drenagem se mantém cerca de 550 ml/24h. Foi realizada TC de\nabdome, que mostra um pertuito entre o ceco e a aponeurose menor que 1 cm de comprimento.\nQual a conduta?","options":{"A":"Iniciar novo tratamento clínico com antibioticoterapia e ampliação de espectro.","B":"Indicar reabordagem, ressecção do pertuito e do segmento intestinal envolvido.","C":"Realizar um ?shaving? (raspagem) do pertuito e ressutura da parede.","D":"Manter o tratamento clínico expectante por mais 60 dias."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-172945","number":"172945","sourceNumber":"172945","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher de 58 anos, hipertensa, com quadro de colecistite crônica calculosa, com crises\nrecorrentes, comparece ao ambulatório de avaliação pré-anestésica, pois foi indicada\ncolecistectomia videolaparoscópica. Faz uso de losartana 100 mg/dia e atenolol 25 mg/dia.\n\nInterrogada acerca de sua capacidade funcional, relata que ao caminhar duas quadras precisa\nparar algumas vezes pois se sente \"cansada\". É\ndiabética insulino-dependente. Ao exame físico:\numa pressão arterial de 130 x 80 mmHg; pulso regular de 65 ppm; ausculta cardiopulmonar normal.\nNos exames, chama atenção uma creatinina de 2,5 mg/dl, no entanto, relata diurese satisfatória.\n\nApresenta eletrocardiograma normal e radiografia de tórax normal para a idade. Qual a conduta\nmais apropriada para essa paciente?","options":{"A":"Manter medicações, liberar para realização da cirurgia planejada.","B":"Manter medicações, realizar cateterismo cardíaco antes da cirurgia.","C":"Encaminhar ao cardiologista para liberação desta paciente para cirurgia.","D":"Manter medicações, solicitar cintilografia miocárdica ou ecocardiografia de estresse."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-172952","number":"172952","sourceNumber":"172952","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Pais levam seu filho de 10 meses de vida, 8.900 gramas, para consulta com um\ncirurgião pediátrico. Relatam abaulamento\nintermitente em região inguinal esquerda,\nparticularmente em situações de choro forte, e mudança importante de volume da região testicular\ndireita, durante o dia. Ambos ocorrem desde o nascimento, sem observação pelos pais de melhora\naté hoje. Por outro lado, negam qualquer evento agudo que os levasse a pensar em dor\nrelacionada aos achados descritos. Exame físico identifica testículos tópicos, com tamanho e\ntextura normais, presença de hérnia inguinal à esquerda e hidrocele moderada à direita. O bebê\nnão apresenta quaisquer outras comorbidades, a despeito de ter nascido prematuro (idade\ngestacional ao nascer de 33 semanas de gestação e peso ao nascer de 2.100 gramas).\n\nPermanecera em unidade de terapia intensiva neonatal durante seu primeiro mês pós-natal. Qual a\nmelhor conduta para esse bebê?","options":{"A":"Herniorrafia inguinal esquerda + punção da hidrocele direita.","B":"Herniorrafia inguinal bilateral em um mesmo tempo cirúrgico.","C":"Aguardar completar 1 ano de vida para indicar tratamento cirúrgico.","D":"Herniorrafia inguinal esquerda + hidrocelectomia direita por acesso escrotal."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-172942","number":"172942","sourceNumber":"172942","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Durante a hernioplastia inguinal aberta, foi questionado aos estudantes presentes quais\nseriam os limites anatômicos daquela herniação classificada como tipo IIIa, segundo Nyhus. Qual a\nmelhor resposta a esse questionamento?","options":{"A":"Borda lateral do músculo reto abdominal, trato iliopúbico e nervo ilio-hipogástrico.","B":"Músculo reto abdominal, forame obturador e ramo genital do nervo genitofemoral.","C":"Borda medial do músculo reto abdominal, ligamento de Cooper, nervo ilioinguinal.","D":"Bainha do músculo reto abdominal, ligamento inguinal e vasos epigástricos inferiores."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-172953","number":"172953","sourceNumber":"172953","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem, 68 anos, irá se submeter à cirurgia de prótese total de joelho. Durante o\nperíodo perioperatório na sala cirúrgica, em um\ndeterminado momento, toda a equipe confirmou\nque todos os membros foram apresentados por nome e função, confirmou o nome do paciente, o\nlocal da cirurgia e o procedimento, confirmou administração do antibiótico e que os exames de\nimagem essenciais estavam exibidos no ambiente da sala de cirurgia. Obedecendo aos critérios de\nsegurança do paciente, em que momento do período perioperatório foram realizadas essas\ncomunicações?","options":{"A":"No intraoperatório.","B":"Antes da incisão da pele.","C":"Ao final do procedimento.","D":"Antes da indução da anestesia."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-150838","number":"150838","sourceNumber":"150838","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem de 84 anos apresenta, há 6 anos, abaulamento em região inguinal direita,\nassociado a discreto desconforto aos\nmoderados esforços. Exame físico: PA = 160 x 105 mmHg;\nFC = 90 bpm; ritmo cardíaco regular, com bulhas hipofonéticas; murmúrio vesicular pulmonar\ndiminuído nas bases; abdome flácido com hepatomegalia discretamente dolorosa e hérnia redutível\nem quadrante inferior direito do abdome, com anel herniário de 4 cm; presença de edema em\nmembros inferiores (++/4+). HPP: DM, hipertenso e insuficiência cardíaca leve. Foi submetido à\nressecção prostática transuretral há 2 anos, sem queixas de prostatismo ou constipação. Qual a\nmelhor conduta para esse paciente?","options":{"A":"Indicar hernioplastia laparoscópica com abordagem transabdominal (TAAP).","B":"Indicar eletivamente hernioplastia pela técnica do reparo ao ligamento de Cooper (McVay).","C":"Realizar hernioplastia inguinal de urgência utilizando o reparo livre de tensão (Lichtenstein).","D":"Estabelecer uma estratégia de espera vigilante e de gerenciamento sintomático, não operatória."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-150833","number":"150833","sourceNumber":"150833","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher de 64 anos, diabética, em uso de metformina, 01 comprimido (850 mg) 2 vezes\nao dia, às refeições. Internou-se para\nrealização de colecistectomia videolaparoscópica, agendada\npara 14 h. Não apresenta outras comorbidades. Os exames pré-operatórios mostram glicemia em\njejum 118 mg/dL, hemoglobina glicada 6,8%, demais exames normais. Diante do exposto, em\nrelação ao diabetes, qual a conduta recomendada para essa paciente, no dia da cirurgia?","options":{"A":"Suspender o uso da metformina.","B":"Substituir a metformina por sulfonilureia.","C":"Administrar insulina regular pela manhã e soro glicosado.","D":"Administrar insulina de longa duração no período da manhã."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-150817","number":"150817","sourceNumber":"150817","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente masculino, 70 anos, hoje no 2º pós-operatório de correção cirúrgica de fratura\nde fêmur, evolui com quadro de agitação\npsicomotora, confusão mental e agressividade, tentando\nbater nos enfermeiros. Foram realizadas adequações no ambiente e outras medidas de manejo\nnão-farmacológico, sem melhora do quadro. É portador de hipertensão arterial sistêmica e\nosteoporose e, segundo familiares, era independente para atividades de vida diária até a\ninternação. Quanto ao quadro descrito, qual a medicação adequada para uso?","options":{"A":"Prometazina.","B":"Haloperidol.","C":"Donepezila.","D":"Lorazepam."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-126987","number":"126987","sourceNumber":"126987","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"José, 43 anos, portador de neoplasia de fígado, irá submeter-se a uma hepatectomia\ndireita. Seguindo a lista de verificação de\nsegurança em cirurgia da Organização Mundial da Saúde\n(time out), o risco de perda sanguínea deve ser avaliado em que momento?","options":{"A":"Antes da incisão cirúrgica.","B":"Antes da indução anestésica.","C":"Antes da admissão na enfermaria.","D":"Antes do paciente sair da sala de operação."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-102086","number":"102086","sourceNumber":"102086","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 48 anos, sexo feminino, é vítima de acidente automobilístico tendo sido\nsubmetido a várias operações que a deixaram acamada por mais de 30 dias. Nesse período,\ndesenvolve enorme escara sacral infectada, grau IV. Diante desse quadro, o melhor tratamento é\nrealizar:","options":{"A":"retalho músculo-cutâneo de vizinhança.","B":"enxertia de pele após granulação.","C":"retalho cutâneo da vizinhança.","D":"enxertia de pele total."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-81234","number":"81234","sourceNumber":"81234","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 70 kg, com queimadura por fogo em 70% da superfície corpórea, após\n4 horas do evento apresenta diurese\nconcentrada, com 25 ml/kg/min. O tratamento imediato deve\nincluir hidratação com:","options":{"A":"Soluções de cristaloide e de albumina humana nas primeiras 24 horas.","B":"Solução de cristaloide ? 9.800 ml em 4 horas e 9.800 ml nas 16 horas seguintes e plasma.","C":"Solução de Ringer lactato ? 2 a 4 ml/kg/% superfície corpórea queimada em 24 horas.","D":"Soluções de cristaloide, 19.600 ml, sendo metade nas primeiras 8 horas e a outra metade nas\n16 horas, seguidas de diurético."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-81305","number":"81305","sourceNumber":"81305","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente masculino, 69 anos, diabético e com mal perfurante plantar no pé direito, há 3\ndias vem evoluindo com febre, calafrios e drenagem de secreção purulenta pela lesão cutânea.\n\nDuas hemoculturas colhidas em locais de punção distintos detectaram a presença de uma bactéria\nGram-negativa. Do ponto de vista fisiopatológico, qual das condições abaixo se associa à MENOR\nchance de progressão para o choque?","options":{"A":"Aumento da concentração sérica de Interleucina 10.","B":"Redução da concentração sérica de proteína C-reativa.","C":"Aumento da concentração sérica de Óxido nítrico.","D":"Redução da concentração sérica de Cortisol."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-65745","number":"65745","sourceNumber":"65745","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem de 22 anos sofreu queimaduras após cair dentro de uma caldeira de água\nquente. Foi imediatamente levado à unidade de\npronto atendimento próxima de sua casa,\napresentando-se acordado, orientado, extensamente queimado, com lesões no rosto, braços e\ntronco. Apresenta ainda rouquidão e inspiração ruidosa. Está hemodinamicamente estável. Qual\ndeve ser a conduta prioritária para minimizar as complicações e o risco de morte no caso descrito?","options":{"A":"Acesso venoso, hidratação e antibioticoterapia.","B":"Transferência imediata para centro de queimados.","C":"Manutenção de via aérea com entubação orotraqueal.","D":"Transfusão de plasma e concentrado de hemácias e albumina.","E":"Cobertura da pele com lençóis úmidos, analgésicos e transferência."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-65778","number":"65778","sourceNumber":"65778","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma mulher de 59 anos, vítima de acidente automobilístico, chega ao pronto-socorro\ncom sinais de choque hemorrágico. Ela refere\ndor no quadril e percebe-se crepitação à palpação da\nbacia. A sondagem vesical evidenciou hematúria macroscópica. Não há fonte externa de\nsangramento nem fraturas nos membros. Foi realizado o exame ultrassonográfico abdominal\n(FAST) que não mostrou líquido livre intraperitoneal. A radiografia do tórax em AP e coluna cervical\nem perfil foram normais. Qual é a melhor forma de abordagem diagnóstica e terapêutica para este\ncaso?","options":{"A":"TC abdominal, urografia excretora, cistografia e fixação interna da bacia.","B":"Radiografia da bacia, uretrocistografia retrógrada e fixação externa da bacia.","C":"Radiografia da bacia, TC de abdome, fixação externa da bacia e embolização.","D":"Radiografia da bacia, urografia excretora, angiografia e fixação interna da bacia.","E":"Radiografia da bacia, TC de abdome, uretrocistografia retrógrada e fixação externa da bacia."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-51220","number":"51220","sourceNumber":"51220","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual alternativa corresponde aos achados do exame físico compatíveis com uma hérnia\ninguinal direta?","options":{"A":"O examinador observa abaulamento da região inguinal e presença de parestesia com irradiação\npara região escrotal.","B":"O examinador observa, ao orientar o paciente a fazer a manobra de Valsalva, abaulamento\nabaixo do ligamento inguinal.","C":"O examinador posiciona seu dedo indicador sobre o canal inguinal, orienta o paciente a fazer a\nmanobra de Valsalva e observa que o abaulamento progride do fundo para superfície.","D":"O examinador posiciona seu dedo indicador sobre o canal inguinal, orienta o paciente a fazer a\nmanobra de Valsalva e observa o abaulamento que se move da região lateral para medial."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-51255","number":"51255","sourceNumber":"51255","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Estado geral de paciente, sexo masculino, 42 anos, admitido na UTI séptico, no\npós-operatório de esofagectomia, evoluia satisfatoriamente até que, há dois dias, o paciente\npassou a apresentar alteração do estado geral, febre e leucocitose. Qual a substância cuja\n\ndosagem sérica, ainda que de forma indireta, pode avaliar o envolvimento da interleucina 6 nesse\nquadro?","options":{"A":"Fosfatase alcalina (FA).","B":"Proteina C reativa (PCR).","C":"Desidrogenase lática (LDH).","D":"Superóxido desmutase (SOD)."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-141599","number":"141599","sourceNumber":"141599","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No paciente grande queimado, é fundamental a antibioticoterapia, visando a cobertura\npara os seguintes microorganismos:","options":{"A":"S. aureus e Pseudomonas.","B":"Fungos e S. aureus.","C":"E. coli e S. aureus.","D":"E. coli e Proteus."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-141615","number":"141615","sourceNumber":"141615","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os procedimentos cirúrgicos são fontes comuns de eventos adversos relacionados ao\ncuidado em saúde. Uma importante iniciativa global para se diminuir os erros no centro cirúrgico é a\ncampanha da OMS, chamada ?cirurgias seguras salvam vidas?, que implica no preenchimento de\num checklist pela equipe cirúrgica em três momentos: 1 ? antes da indução da anestesia; 2 ? antes\nda incisão; 3 ? antes do paciente deixar a sala de operações. Qual das seguintes situações abaixo\nrepresenta uma falha na checagem do momento 3?","options":{"A":"Drenagem de hematoma extradural no lado errado.","B":"Paciente agendado para adenoidectomia foi submetido à turbinectomia.","C":"Gaze na pelve de uma paciente submetida à histerectomia videolaparoscópica.","D":"Anemia aguda grave por falta de reserva de sangue em cirurgia de exenteração pélvica."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-365626","number":"365626","sourceNumber":"365626","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias estão entre as mais antigas patologias registradas na humanidade. Uma\nhérnia é definida como uma protrusão, protuberância ou projeção de um órgão, ou uma parte de\num órgão, através da parede do corpo que normalmente o contém. Coletivamente, hérnias\ninguinais e hérnia femoral são conhecidas como hérnias na virilha. A hérnia inguinal direta é\nresponsável por 30% a 40% das hérnias na virilha nos homens e a aproximadamente 14% a 21%\ndas hérnias inguinais nas mulheres. Elas se projetam mediante aos vasos epigástricos inferiores\ndentro do triângulo de Hesselbach. O triângulo de Hesselbach é delimitado por","options":{"A":"inferior: ligamento inguinal / medial: vasos epigástricos / lateral: músculo reto abdominal.","B":"inferior: vasos epigástricos / medial: músculo reto abdominal / lateral: ligamento inguinal.","C":"inferior: ligamento inguinal / medial: músculo reto abdominal / lateral: vasos epigástricos.","D":"inferior: músculo reto abdominal / medial: ligamento inguinal / lateral: vasos epigástricos."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-365625","number":"365625","sourceNumber":"365625","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que se refere à anatomia da região inguinal, deve-se atentar para não lesar os\nnervos localizados nessa topografia durante um procedimento cirúrgico de herniorrafia\nconvencional. Dois deles passam interiormente ao canal inguinal. Esses nervos são","options":{"A":"ílio-hipogástrico e ilioinguinal.","B":"ílio-hipogástrico e ramo genital do genitofemoral.","C":"ílio-hipogástrico e pudendo.","D":"ramo genital do genitofemoral e ilioinguinal."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-365620","number":"365620","sourceNumber":"365620","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 58 anos de idade, com antecedentes de hipertensão arterial sistêmica\nbem controlada com enalapril, foi admitido para\ncirurgia eletiva de colecistectomia laparoscópica\npor causa de episódios recorrentes de cólica biliar. Ao exame físico, apresentou PA = 130 mmHg x\n80 mmHg, FC = 78 bpm, FR = 16 irpm, temperatura = 36,8 ºC e SatO2 = 98% em a.a. Realizou\nexames laboratoriais com resultados dentro da faixa de normalidade, glicose = 110 mg/dL, ureia e\ncreatinina normais, coagulograma normal, eletrocardiograma com ritmo sinusal, sem alterações\nagudas. Quanto à história cirúrgica, o paciente não possui histórico de cirurgias prévias. Ele\nrelatou\nnão ter alergias conhecidas a medicamentos. Considerando o caso apresentado, qual a abordagem\nmais apropriada para o preparo pré-operatório desse paciente?","options":{"A":"Prescrição de antibióticos de amplo espectro uma hora antes do procedimento.","B":"Administração de hidrocortisona para a prevenção de resposta inflamatória exagerada.","C":"Jejum absoluto de seis horas antes da cirurgia.","D":"Monitoramento da glicemia perioperatória, mantendo-a abaixo de 180 mg/dL."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-349766","number":"349766","sourceNumber":"349766","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em um paciente com doença coronariana, qual dos seguintes agentes NÃO seria\nindicado para indução anestésica, por ter como efeito colateral a hipertensão?","options":{"A":"Tiopental.","B":"Propofol.","C":"Cetamina.","D":"Etomidato.","E":"Midazolam."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-349775","number":"349775","sourceNumber":"349775","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo a classificação de Caprini para pacientes cirúrgicos, assinale a alternativa\ncorreta quanto à classificação de risco para\nTEV (Tromboembolismo Venoso) de um paciente de 54\nanos que foi submetido a uma cirurgia de câncer de cólon, aberta, que durou aproximadamente 2h.","options":{"A":"Risco muito baixo.","B":"Risco baixo.","C":"Risco moderado.","D":"Risco alto.","E":"Risco muito alto."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-349713","number":"349713","sourceNumber":"349713","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma criança de 4 anos é levada pelos pais à UBS após queda da própria altura\nenquanto brincava com os primos. Ao examiná-la,\no médico observa um pequeno corte no queixo\ne, após limpeza da lesão e exame clínico, determina a necessidade de sutura. Sabendo que a\ncriança pesa cerca de 15 kg, assinale a conduta adequada para a preparação desse procedimento.","options":{"A":"Deve-se utilizar fio de náilon 5-0 e preparar lidocaína com vasoconstritor a 1% para anestesia.\n\nDeve-se, ainda, solicitar uma ou duas pessoas para auxiliar na segurança da sutura.","B":"Deve-se utilizar fio de náilon 3-0 e preparar lidocaína com vasoconstritor a 1% para anestesia.\n\nDeve-se, ainda, solicitar uma ou duas pessoas para auxiliar na segurança da sutura.","C":"Deve-se utilizar fio de náilon 3-0 e orientar os pais sobre o risco da anestesia,\ncontraindicando o\nuso de anestésicos injetáveis. Deve-se,\nainda, solicitar uma ou duas pessoas para auxiliar na\nsegurança da sutura.","D":"Deve-se utilizar fio de náilon 3-0 e preparar lidocaína sem vasoconstritor a 1% para anestesia.\n\nDeve-se, ainda, solicitar uma ou duas pessoas para auxiliar na segurança da sutura.","E":"Deve-se utilizar fio de náilon 5-0 e preparar lidocaína sem vasoconstritor a 1% para anestesia.\n\nDeve-se, ainda, solicitar uma ou duas pessoas para auxiliar na segurança da sutura."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337493","number":"337493","sourceNumber":"337493","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 72 anos será submetida a uma cirurgia eletiva de histerectomia aberta\ne, para isso, passa por uma consulta\npré-anestésica. Diante do caso, o anestesista opta em\nassociar um bloqueio anestésico para a paciente. Com base no caso clínico e nos bloqueios\nanestésicos, julgue o item a seguir. Caso o anestesista aumente a dose de anestésico durante um\nbloqueio subaracnoide, geralmente irá causar aumento da extensão da dispersão cefálica e a\nduração do bloqueio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337494","number":"337494","sourceNumber":"337494","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 72 anos será submetida a uma cirurgia eletiva de histerectomia aberta\ne, para isso, passa por uma consulta\npré-anestésica. Diante do caso, o anestesista opta em\nassociar um bloqueio anestésico para a paciente. Com base no caso clínico e nos bloqueios\nanestésicos, julgue o item a seguir. A raquianestesia consiste em uma alternativa a pacientes como\na citada nesse caso, a depender do procedimento cirúrgico em questão, pois evita a manipulação\nda via aérea e as complicações da intubação traqueal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337495","number":"337495","sourceNumber":"337495","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 72 anos será submetida a uma cirurgia eletiva de histerectomia aberta\ne, para isso, passa por uma consulta\npré-anestésica. Diante do caso, o anestesista opta em\nassociar um bloqueio anestésico para a paciente. Com base no caso clínico e nos bloqueios\nanestésicos, julgue o item a seguir. Caso o anestesista opte por colocar um cateter epidural, em\ngeral, ele não deve ser colocado após 24 horas da última dose de heparina de baixo peso\nmolecular (HBPM) e não deve ser removido antes de 12 horas após a última dose de HBPM.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-322137","number":"322137","sourceNumber":"322137","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em um reparo cirúrgico aberto de hérnia inguinal, é importante que o cirurgião tenha\nconhecimento de anatomia e habilidade para preservar estruturas importantes encontradas na\nregião do canal inguinal. No caso de pacientes homens, quais são os nervos (com suas respectivas\nfunções) que devem ser cuidadosamente dissecados e preservados nesse procedimento?","options":{"A":"Ramo genital do nervo genitofemoral (sensibilidade lateral do escroto); nervo ilio-hipogástrico\n(sensibilidade da região inguinal e púbis / base\ndo pênis); nervo ilioinguinal (sensibilidade de região\nmedial superior da coxa).","B":"Ramo femoral do nervo genitofemoral (sensibilidade lateral da perna); nervo ilioinguinal\n(sensibilidade de região medial superior da\ncoxa); nervo obturador (motricidade - adução da perna).","C":"Nervo obturador (motricidade - adução da perna); e nervo cutâneo femoral lateral (sensibilidade\nde região lateral superior da coxa).","D":"Nervo femoral (motricidade e sensibilidade da perna); nervo ílio-hipogástrico (sensibilidade de\nregião medial superior da coxa); nervo ilioinguinal (sensibilidade da região inguinal e púbis / base\ndo pênis).","E":"Ramo genital do nervo genitofemoral (sensibilidade lateral do escroto); nervo obturador\n(motricidade - adução da perna); nervo\nilioinguinal (sensibilidade da região inguinal e púbis / base\ndo pênis)."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-322143","number":"322143","sourceNumber":"322143","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente foi submetido a uma cirurgia abdominal, e o anestesista introduziu um\ncateter peridural para analgesia. O paciente se\nencontra na UTI utilizando heparina de baixo peso\nmolecular como anticoagulação profilática, e a enfermeira questiona o médico plantonista se pode\nretirar o cateter. Nesse caso, qual é a conduta mais adequada e a respectiva justificativa?","options":{"A":"Retirar o cateter, já que a anticoagulação profilática não interfere no risco para hematoma\nepidural.","B":"Manter o cateter e solicitar orientação ao anestesista quanto ao momento da retirada, devido ao\nrisco de hematoma epidural.","C":"O cateter poderá ser removido se a última dose de heparina tiver sido realizada há mais de 3h.","D":"Manter o cateter e aguardar, pelo menos, 48h, após a última dose da heparina para remover o\ncateter.","E":"Manter o cateter por, pelo menos, 24 horas, após a última dose de heparina devido ao risco de\nhematoma subdural."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-322144","number":"322144","sourceNumber":"322144","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação ao risco de contaminação, podemos classificar uma cirurgia eletiva de\ncâncer de estômago com abordagem controlada da cavidade gástrica como","options":{"A":"limpa.","B":"contaminada.","C":"potencialmente contaminada.","D":"suja.","E":"infectada."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337511","number":"337511","sourceNumber":"337511","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Trata-se de provável hérnia inguinal, mais comum no sexo masculino.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-322146","number":"322146","sourceNumber":"322146","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente será submetido a uma cirurgia cardíaca eletiva. Qual antibiótico deve ser\npreferencialmente utilizado para a profilaxia antimicrobiana cirúrgica?","options":{"A":"Cefazolina.","B":"Metronidazol.","C":"Ceftriaxona.","D":"Cefepima.","E":"Ciprofloxacino."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337512","number":"337512","sourceNumber":"337512","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. As hérnias diretas ocorrem no triângulo de Hesselbach, enquanto as hérnias inguinais\nindiretas originam-se lateralmente ao triângulo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337513","number":"337513","sourceNumber":"337513","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. As hérnias inguinais indiretas com anel inguinal normal são classificadas como tipo II de\nNyhus.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337514","number":"337514","sourceNumber":"337514","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. É recomendada a intervenção cirúrgica quando ocorre a descoberta de uma hérnia inguinal\nsintomática, porque a história natural pode resultar em potencial encarceramento e\nestrangulamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337515","number":"337515","sourceNumber":"337515","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. O reparo de McVay é particularmente utilizado para hérnias femorais estranguladas, porque\nele proporciona obliteração do espaço femoral sem o uso de malha.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337516","number":"337516","sourceNumber":"337516","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino de 32 anos percebeu um abaulamento em região\ninguinal à direita, mais evidente ao esforço\nfísico, com desconforto local eventual, sem sinais\nflogísticos. Com base no caso descrito e nos conhecimentos médicos correlatos, julgue o item a\nseguir. No reparo de Shouldice, uma tela inabsorvível protética é confeccionada para proteger ou\nreforçar o canal inguinal, a qual é suturada com fio inabsorvível começando no tubérculo púbico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-305270","number":"305270","sourceNumber":"305270","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em uma cirurgia colorretal, durante o procedimento, o cirurgião deve estar atento e\nfazer qual das seguintes recomendações ao colega anestesista?","options":{"A":"Administrar uma dose de vancomicina profilática logo após a incisão da pele.","B":"Administrar cefazolina + ampicilina-sulbactam na indução anestésica e repetir a dose após 6\nhoras.","C":"Administrar vancomicina na indução anestésica e manter por 24 horas.","D":"Administrar cefazolina + metronidazol na indução anestésica e repetir após aproximadamente\n3?4 horas.","E":"Administrar ampicilina-sulbactam na indução anestésica e manter por 48 horas."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-305272","number":"305272","sourceNumber":"305272","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente que será submetido a uma cirurgia teve indicação de anestesia raquidiana\npela equipe de anestesia. Assinale a alternativa\nque apresenta somente informações CORRETAS\nsobre esse bloqueio anestésico e que podem ser fornecidas ao paciente.","options":{"A":"A raquianestesia representa uma alternativa à manipulação da via aérea e evita as complicações\nda intubação orotraqueal.","B":"Na raquianestesia, pode haver despertar prolongado ou sonolência pós-operatória com alguma\nfrequência.","C":"A raquianestesia apresenta vantagens por evitar efeitos colaterais como bradicardia e cefaleia.","D":"A raquianestesia apresenta a vantagem de poder ser realizada também em pacientes com\ncardiopatias e coagulopatias.","E":"O risco de cefaleia pós-punção é baixo e ocorre com maior frequência em idosos do sexo\nmasculino."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-298847","number":"298847","sourceNumber":"298847","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em caso de febre no 2º PO desse\npaciente, deve-se pensar, como causa mais comum, a infecção da ferida operatória, que deve ser\ntratada com drenagem da FO e (ou) antibioticoterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-305279","number":"305279","sourceNumber":"305279","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Durante uma consulta médica, um paciente do sexo masculino relata ao médico que\npossui um abaulamento da região inguinal direita, intermitente, muitas vezes doloroso. Qual é a\nmelhor maneira de realizar o exame físico desse paciente e qual é o provável diagnóstico?","options":{"A":"Introduzir o dedo no canal inguinal por invaginação da bolsa escrotal e solicitar que o paciente\nrealize Valsalva, com detecção de abaulamento local ? hérnia inguinal.","B":"Posicionar as mãos sobre a fossa ilíaca direita, comprimir e descomprimir bruscamente a região,\ngerando dor local ? hérnia epigástrica.","C":"Posicionar o dedo sobre o canal inguinal e solicitar ao paciente que inspire profundamente, com\ndetecção de depressão local ? hérnia inguinal.","D":"Posicionar o dedo sobre o trato iliopúbico e solicitar inspiração profunda, com detecção de\nabaulamento acima desse local ? hérnia femoral.","E":"Posicionar a mão sobre o testículo direito e palpá-lo, detectando enduramento local ? hérnia\ninguinal."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-261204","number":"261204","sourceNumber":"261204","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Trata-se de patologia\nbenigna cujo tratamento exige uso de antibióticos, sendo vancomicina uma opção segura.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-261205","number":"261205","sourceNumber":"261205","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A origem do defeito,\nnesse caso, está lateral aos vasos epigástricos inferiores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-261206","number":"261206","sourceNumber":"261206","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico\nnecessita da realização de exame de imagem, sendo a TC contrastada uma boa opção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-261207","number":"261207","sourceNumber":"261207","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Esse paciente,\nsegundo Nyhus, apresenta classificação 3C da sua patologia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274342","number":"274342","sourceNumber":"274342","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente jovem com câncer de colo uterino será submetida a uma histerectomia\nradical videolaparoscópica. Qual seria a profilaxia\nantimicrobiana mais recomendada?","options":{"A":"Ceftriaxona 1 g e metronidazol 500 mg endovenosos após a incisão cirúrgica.","B":"Cefazolina 1-2 g endovenosa na indução anestésica.","C":"Ciprofloxacino 500 mg endovenoso na indução anestésica.","D":"Metronidazol 500 mg e cefazolina 1-2 g endovenosos na indução anestésica.","E":"Cefoxetina 1-2 g e metronidazol 500 mg endovenosos na indução anestésica."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274343","number":"274343","sourceNumber":"274343","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considerando os fios cirúrgicos utilizados para sutura, assinale a alternativa correta.","options":{"A":"O fio de PDS é monofilamentar e inabsorvível.","B":"O fio de categute é um dos que causam menor reação tecidual.","C":"O fio de Vicryl permanece com sua força tênsil em mais de 50% em 5 semanas.","D":"O fio de Monocryl é monofilamentar e produz reação tecidual mínima.","E":"O fio de Prolene é multifilamentar e absorvível."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-261209","number":"261209","sourceNumber":"261209","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um menino de 6 anos de idade, foi encaminhado ao consultório com relato de aumento\ndo volume testicular progressivo há cerca de\num ano. Ao exame físico, constataram-se FC = 85\nbpm; FR = 18 ipm; e SatO2 = 98%, com abaulamento inguinal à esquerda, que piora às manobras\nde esforço, com identificação de tumefação que desce através do canal inguinal. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. No caso de pacientes\ndo sexo feminino, a maior parte dos casos de defeitos ocorre através do anel femoral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274344","number":"274344","sourceNumber":"274344","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente com indicação de cirurgia apresentou, logo após a anestesia, taquicardia,\ntemperatura elevada, arritmia e espasmo do\nmúsculo masseter. Sobre o provável diagnóstico desse\nquadro, suas características e manejo, assinale a alternativa CORRETA.","options":{"A":"Trata-se de choque séptico que deve ser tratado com infusão imediata de antibiótico.","B":"Trata-se de hipotermia maligna e deve ser administrado dantrolene.","C":"Trata-se de hipertermia maligna, condição autossômica dominante.","D":"Trata-se de choque séptico refratário e deve ser administrado sevoflurano.","E":"Trata-se de hipertermia maligna e deve ser administrada succinilcolina."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274349","number":"274349","sourceNumber":"274349","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O canal inguinal é uma referência anatômica importante na identificação e reparo das\nhérnias inguinais. Assinale a alternativa que apresenta somente estruturas que podem estar\ncontidas no canal inguinal.","options":{"A":"Ligamento redondo do útero, artéria uterina e ramo genital do nervo genitofemoral.","B":"Fibras do músculo cremastérico, ramo femoral no nervo genitofemoral e vasos testiculares.","C":"Ligamento redondo, ramo femoral do nervo genitofemoral e vasos ovarianos.","D":"Fibras do músculo cremastérico, ramo genital no nervo genitofemoral e ducto deferente.","E":"Fibras do músculo cremastérico, ramo femoral no nervo genitofemoral e vasos testiculares."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284319","number":"284319","sourceNumber":"284319","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. A obesidade, a técnica cirúrgica inadequada e o procedimento prévio\nrealizado com anestesia local são fatores relacionados com a recidiva da hérnia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284320","number":"284320","sourceNumber":"284320","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. A ultrassonografia da região inguinal é um exame desnecessário para se\nconfirmar o diagnóstico de hérnia inguinal recidivada, pois o diagnóstico é clínico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284321","number":"284321","sourceNumber":"284321","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. O risco de complicações, como, por exemplo, o encarceramento e o\nestrangulamento, é baixo em pacientes assintomáticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284322","number":"284322","sourceNumber":"284322","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. A cirurgia laparoscópica apresenta taxa de recidiva significativamente menor\nque a da cirurgia aberta com utilização de tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284323","number":"284323","sourceNumber":"284323","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. A escolha técnica para o tratamento da hérnia inguinal deve considerar a\nexpertise do cirurgião, os recursos disponíveis e as características de cada paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-284324","number":"284324","sourceNumber":"284324","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 53 anos de idade foi submetido à herniorrafia inguinal direita há oito\nanos. Retornou ao consultório médico, referindo\nabaulamento em região inguinal direita, que surgiu\nhá seis meses, mas que vem aumentando progressivamente. Com base nessa situação hipotética,\njulgue o item a seguir. A via de acesso recomendável para um paciente que teve uma recidiva após\numa via de acesso aberta é a mesma incisão aberta, para abordar diretamente a recidiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-239263","number":"239263","sourceNumber":"239263","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A\ninfecção de ferida operatória é complicação comum após o tratamento cirúrgico adequado da\ndoença apresentada por esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-250131","number":"250131","sourceNumber":"250131","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 44 anos de idade queixa-se de dor abdominal, principalmente em\nhipocôndrio direito, que se iniciou há dois dias. Relata febre de 38 ºC, associada ao quadro, além\nde náuseas. Ao exame, encontrava-se em bom estado geral, desidratada +/4+, anictérica, com\nabdome plano, flácido, doloroso à palpação em hipocôndrio direito e com defesa em hipocôndrio\ndireito. Realizou hemograma, que mostrou 14.500 leucócitos (normal até 10.000), bilirrubinas totais\nde 0,7 (normal até 1) e amilase de 137 (normal até 110). Fez ultrassom, que mostrou vesícula\naumentada de volume, com múltiplos cálculos de até 1,2 cm em seu interior e com paredes\ndelaminadas e com espessura de 6 mm. Com base nesse caso hipotético e nos conceitos médicos\na ele associados, julgue o item a seguir. Durante a colecistectomia, pode haver a necessidade de\ndrenagem da cavidade e esse dreno, em geral, pode ser retirado no primeiro dia pós-operatório,\ndesde que sua drenagem seja baixa e seu conteúdo não seja bilioso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-211981","number":"211981","sourceNumber":"211981","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 41 anos de idade, obesa, após 20 dias de pós-operatório de uma\ncolectomia direita por isquemia mesentérica, apresenta febre e presença de conteúdo enteral\nsecretado através do dreno deixado próximo à anastomose primária realizada no transoperatório.\nDiagnosticada a presença de fístula, a paciente foi levada à laparotomia de emergência. No\ninventário da cavidade, foi identificado espessamento importante da parede das alças próximo à\nanastomose e presença de orifício entre a sutura da anastomose das alças, com secreção de\nconteúdo enteral no local. Com base no caso clínico apresentado, quanto ao uso de antibióticos na\ncirurgia, assinale a alternativa correta.","options":{"A":"A obesidade não é considerada um fator de risco para infecção.","B":"A colectomia direita realizada no primeiro momento cirúrgico é considerada uma cirurgia\ninfectada.","C":"As infecções de sítio cirúrgico raramente são causadas por cocos Gram-positivos.","D":"As infecções por bacilos Gram-negativos são mais comuns em cirurgias nas quais não há\nmanipulação de vísceras ocas.","E":"Durante o procedimento cirúrgico, a manutenção da temperatura corporal normal é importante\npara a redução da incidência de infecções de\nsítio cirúrgico."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-179172","number":"179172","sourceNumber":"179172","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 34 anos de idade, previamente hígido, buscou assistência médica com\nqueixa de dor na virilha, associada a \"inchaço\" da região, após realização de atividade física. Ao\nexame, apresentava abaulamento em região inguinal direita, abaixo do ligamento inguinal, com\naproximadamente 4 cm de diâmetro, com moderada dor à palpação, mas sem sinais flogísticos.\n\nCom base nesse caso hipotético, assinale a alternativa que apresenta o diagnóstico mais provável\npara o paciente.","options":{"A":"Hérnia inguinal direta.","B":"Hérnia inguinal indireta.","C":"Hérnia de Ritcher.","D":"Hérnia de Spigel.","E":"Hérnia femoral."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-152062","number":"152062","sourceNumber":"152062","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. As ISC são as mais\ncomuns entre todas as infecções em áreas cirúrgicas, tendo melhor prognóstico em comparação às\ninfecções em áreas cirúrgicas relacionadas ao órgão/espaço.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-152097","number":"152097","sourceNumber":"152097","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considere hipoteticamente a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista, apresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir. Se\ngrandes volumes de solução salina normal forem utilizados para a reanimação do paciente em\nquestão, ocorrerá acidemia hiperclorêmica como resultado da substituição do bicarbonato no\nsangue perdido por cloreto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-154330","number":"154330","sourceNumber":"154330","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente, 42 anos de idade, sexo masculino, foi internado para tratamento cirúrgico\neletivo de hérnia inguinal à direita, com\ndois anos de evolução. Durante o ato operatório, após\nabertura do saco herniário em hérnia tipo Nyhus IIIB, identificou-se segmento ileal no respectivo\ninterior, com divertículo de Meckel de base larga, sem evidentes sinais de inflamação, o qual foi\ntratado conservadoramente, por meio de redução para a cavidade peritoneal. Com base nas\ninformações apresentadas e no caso clínico, o epônimo de hérnia especial descrita é hérnia:","options":{"A":"De Richeter.","B":"De Littré.","C":"De Amyand.","D":"De Garengeot.","E":"Ventrolateral de Spiegel."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-135061","number":"135061","sourceNumber":"135061","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUm paciente de cinquenta e quatro anos de\nidade, tabagista, portador de neoplasia de cabeça de\npâncreas, foi submetido à duodenopancreatectomia com preservação pilórica. O procedimento\ntranscorreu sem intercorrências. O paciente foi transferido para UTI no pós-operatório imediato\nextubado, respirando ar ambiente, com saturação de oxigênio de 98%. No segundo dia após a\noperação, o paciente apresentou desconforto respiratório importante, baixa de saturação, com\nnecessidade de entubação orotraqueal para assistência ventilatória adequada. A radiografia de\ntórax mostrou desvio da traqueia para esquerda, pequeno nível de líquido obliterando o seio\ncostofrênico esquerdo, desvio do coração para o lado esquerdo e colapso do pulmão esquerdo.\n\nNesse caso, a conduta clínica adequada seria manter a assistência ventilatória, realizar\nfisioterapia\nrespiratória, tromboprofilaxia e drenagem torácica fechada do hemitórax esquerdo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-108132","number":"108132","sourceNumber":"108132","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os pacientes que apresentam situações de emergências clínicas ou cirúrgicas, como\ntrauma, choque, queimaduras graves, parada cardiorrespiratória ou coma, necessitam de\natendimento rápido e eficaz para que sua vida seja preservada. A respeito desse assunto, julgue o\nitem que se segue. O tratmento mais indicado para a dor intensa de paciente com área extensa de\nqueimadura é realizado com os opioides, por via endovenosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-64619","number":"64619","sourceNumber":"64619","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação à profilaxia sistêmica antimicrobiana para prevenção de Infecção do Sítio\nCirúrgico (ISC), assinale a alternativa CORRETA:","options":{"A":"A classificação da ferida cirúrgica (Limpa, Potencialmente Contaminada, Contaminada,\nInfectada) é o único critério a ser\nconsiderado para determinar o emprego de antibiótico profilático.","B":"Antibióticos profiláticos não deverão ser administrados, sob quaisquer circunstâncias, em\ncirurgias limpas.","C":"Nas feridas potencialmente contaminadas e contaminadas, o uso de antibiótico profilático não\ntrará benefícios clínicos.","D":"Em pacientes traqueostomizados ou intubados, os antibióticos profiláticos representam uma\nmedida eficaz na prevenção de infecções de sítio pulmonar.","E":"Os antibióticos profiláticos devem ser administrados pré-operatoriamente no momento da\nindução anestésica ou 30 (trinta) minutos antes do início do procedimento."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-52625","number":"52625","sourceNumber":"52625","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Julgue o item seguinte, a respeito do processo de cicatrização de feridas. A deficiência\nde vitamina A não interfere na cicatrização de\nferidas.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-52626","number":"52626","sourceNumber":"52626","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Julgue o item seguinte, a respeito do processo de cicatrização de feridas. Os\nfibroblastos são as células predominantes durante a fase proliferativa da cicatrização.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-52628","number":"52628","sourceNumber":"52628","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Julgue o item seguinte, a respeito do processo de cicatrização de feridas. O colágeno\nmais comumente encontrado na pele de adultos é o\ndo tipo I.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352307","number":"352307","sourceNumber":"352307","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nAvaliação clínica perioperatória compreende, entre outros elementos de sua avaliação, orientar\nmanejo pré, intra e pós-operatórios, elemento denominado estratégia protetora.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352377","number":"352377","sourceNumber":"352377","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nPacientes tabagistas, doença pulmonar obstrutiva crônica, diabetes mellitus e hipertensão arterial\nsistêmica são categorizados como ASA II pela American Society of Anesthesiologists (ASA).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352376","number":"352376","sourceNumber":"352376","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nPara pacientes com idade inferior a 40 anos, recomenda-se a realização apenas de um hemograma\ncompleto e coagulograma como exames pré-operatórios.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352375","number":"352375","sourceNumber":"352375","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nPacientes com classificação ASA III e histórico de cardiopatia isquêmica requerem uma avaliação\nabrangente, que envolve a análise de biomarcadores como o NT-ProBNP e a troponina, juntamente\ncom a estratificação do risco cardiovascular através de cineangiocoronariografia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352374","number":"352374","sourceNumber":"352374","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir. Um\npaciente com morte encefálica confirmada, envolvido em um processo de doação de órgãos, não\napresenta uma classificação ASA definida de acordo com seu estado clínico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352373","number":"352373","sourceNumber":"352373","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir. A\navaliação do risco perioperatório é influenciada pela análise não apenas do risco cardíaco, mas\ntambém de outras áreas, incluindo o risco anestésico para a liberação da cirurgia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352372","number":"352372","sourceNumber":"352372","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nEntre as complicações cardíacas pós-operatórias potenciais, destacam-se arritmias graves com\ninstabilidade hemodinâmica. No entanto, é importante observar que a lesão miocárdica após\ncirurgia não cardíaca (MINS) não está associada a um aumento na mortalidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352371","number":"352371","sourceNumber":"352371","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nEntre os algoritmos elaborados para a avaliação do risco de complicações cardíacas\nperioperatórias, destaca-se o Índice de Risco\nRevisado de Lee, que utiliza critérios como o tipo de\ncirurgia, o estado funcional do paciente e fatores de risco cardiológicos, como a presença de ondas\nQ no ECG, o uso de nitratos e o diabetes tratado com insulinoterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352370","number":"352370","sourceNumber":"352370","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nCirurgias oftalmológicas de emergência são classificadas de baixo risco intrínseco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-366255","number":"366255","sourceNumber":"366255","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A avaliação clínica perioperatória é descrita como análise clinica e objetiva\nquantificar o\nrisco de complicações clinicas perioperatórias. Essa avaliação deve ser baseada em variáveis\nclinicas e em resultados de exames subsidiários (quando indicados) e deve considerar os riscos de\ncomplicações cardíacas e não cardíacas. \"\"Manual do residente de clínica médica. Maria Helena\nSampaio Favarato et ai. 3ªed. - Santana de Parnaíba/SP; Manole, 2023. Considerando o texto\nacima apenas de caráter informativo sobre avaliação clínica perioperatória bem como sua\nimportancia e seus assuntos correlatos, julgue o item subsequente. Paciente com stent\nfarmacológico há 9 meses em dupla anti-agregação plaquetária, que necessita de cirurgia de\nurgência, deverá ter os medicamentos suspensos 7 dias antes do procedimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343425","number":"343425","sourceNumber":"343425","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A anestesia em que a interrupção dos impulsos nervosos acontece por meio de um\nbloqueio à condução, feito por interferência no processo de origem do potencial de ação, em que a\ninfiltração do anestésico nos tecidos é o método mais usado e os tecidos a serem manipulados ou\noperados estarão bloqueados para o procedimento é a anestesia:","options":{"A":"Regional.","B":"Caudal.","C":"Local.","D":"Peridural."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343426","number":"343426","sourceNumber":"343426","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os objetivos básicos da anestesia geral são obtidos com o uso de medicamentos com\nfinalidades bem específicas, cuja ação conjunta resulte em sinergismos e interações. Os\nmedicamentos são classificados em: hipnóticos, opioides e bloqueadores neuromusculares. Os\nopioides mais utilizados normalmente são:","options":{"A":"Tiopental, cetamina, alfentanila, succinilcolina e dopamina.","B":"Tiopental, propofol, midazolam, diazepam e etomidato.","C":"Atracúrio, cisatracúrio, pancurônio, rocurônio e vecurônio.","D":"Morfina, meperidina, fentenila, sufentalina e remifentanila."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343431","number":"343431","sourceNumber":"343431","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A técnica considerada ideal para feridas com tensão, capaz de conter as camadas\nprofundas e as superficiais, que na primeira\npassagem da agulha, mais distante das bordas e\nabrangendo a profundidade, tem a saída também distante da borda, e na volta da agulha, a\npassagem estará mais próxima da borda da ferida e em menor profundidade, formando assim a\neversão das bordas, é chamada de:","options":{"A":"Sutura intradérmica.","B":"Sutura contínua.","C":"Sutura com pontos separados em laço.","D":"Sutura em laceração triangular."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343434","number":"343434","sourceNumber":"343434","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre as hérnias de parede abdominal, é CORRETO afirmar:","options":{"A":"A hérnia femoral e umbilical são mais frequentes em mulheres.","B":"A técnica de Lichtenstein é considerada, hoje, padrão-ouro na correção de hérnia epigástrica por\napresentar taxas de recidiva menores do que 1%.","C":"Aproximadamente 50% das hérnias ocorrem na região inguinal, sendo dois terços indiretas.","D":"Nas hérnias lombares, as mais frequentes são as localizadas no triângulo lombar inferior\n(triângulo de Petit)."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-343442","number":"343442","sourceNumber":"343442","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem, 35 anos, com quadro de abaulamento em região de virilha esquerda, iniciado\nhá 72 horas, com dor e hiperemia local. Hoje,\nrelata febre e que a dor está aumentando.\n\nConsiderando o enunciado, é CORRETO afirmar:","options":{"A":"Deve-se tentar reduzir a hérnia e realizar analgesia, pois trata-se de hérnia femoral esquerda\nencarcerada.","B":"Trata-se de hérnia inguinal esquerda. Deve ser realizada redução da hérnia e programação de\ncirurgia eletiva.","C":"Deve-se tentar reduzir a hérnia e realizar analgesia, pois trata-se de hérnia inguinal esquerda\nencarcerada.","D":"Deve-se programar cirurgia de urgência, pois trata-se de hérnia inguinal esquerda encarcerada,\nevoluindo para hérnia inguinal estrangulada."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-307087","number":"307087","sourceNumber":"307087","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 46 anos de idade apresenta hérnia de região inguinal. No que se refere\nà anatomia da região inguinal, assinale a\nalternativa correta.","options":{"A":"A última camada anatômica da região inguinal é formada pelo músculo oblíquo externo do\nabdome, cuja aponeurose predomina na região inguinal e compõe a bainha do reto abdominal.","B":"Quando o defeito na parede abdominal se localiza no triângulo de Hasselbach, caracteriza uma\nhérnia femoral, resultado da fraqueza da fáscia transversal. O conteúdo do saco herniário, nesse\ncaso, é geralmente composto por gordura intraperitoneal.","C":"O triângulo de Hessert é formado pela borda inferior do músculo oblíquo interno, a borda externa\ndo músculo reto e o ligamento inguinal.","D":"O orifício miopectíneo localiza-se entre a margem inferior do púbis (no ligamento pectíneo), a\nmargem lateral do ligamento inguinal, as artérias e veias epigástricas e o músculo transverso\nabdominal.","E":"A estrutura mais superficial da região inguinal, no momento da dissecção anatômica para\ncorreção cirúrgica, é a fáscia transversalis."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-268886","number":"268886","sourceNumber":"268886","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente de 43 anos de idade está com dor em região inguinal esquerda,\nassociada a abaulamento há cerca de três\ndias. Além disso, apresenta náuseas e vômitos e parada\nde eliminação de gases. Ao exame físico, percebe-se em bom estado geral, normocorada,\nanictérica e com sinais vitais estáveis: PA = 130 mmHg x 80 mmHg; FC = 89 bpm; FR = 17 irpm; e\nSatO2 = 99%. Verifica-se abdome com dor à palpação superficial, globoso e com ruídos\nadventícios diminuídos. Com base nesse caso clínico, no que se refere às patologias da região\ninguinal, assinale a alternativa correta.","options":{"A":"A classificação para essa hérnia é Nyhus tipo III B.","B":"A incidência de estrangulamento de hérnias femorais é baixa.","C":"Algumas hérnias femorais podem se apresentar acima do ligamento inguinal. Nesses casos, o\nsaco herniário protui abaixo do ligamento inguinal e ascende em direção cefálica.","D":"As hérnias femorais são as hérnias mais comuns nas mulheres.","E":"Somente hérnias femorais que cursam com estrangulamento devem ser operadas."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-268888","number":"268888","sourceNumber":"268888","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Tendo em vista a anatomia da região inguinal e os conhecimentos médicos correlatos,\nassinale a alternativa correta.","options":{"A":"O músculo oblíquo externo é o mais profundo dos músculos da parede abdominal lateral.","B":"O ligamento inguinal encontra-se às margens inferiores da aponeurose do oblíquo externo, que\nse estende da crista ilíaca ao tubérculo\npúblico.","C":"A fáscia transversal é componente cefálico do canal inguinal.","D":"O canal inguinal tem 4 cm de altura e está localizado abaixo do ligamento inguinal.","E":"O músculo cremaster origina-se das fibras do reto abdominal."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274606","number":"274606","sourceNumber":"274606","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na avaliação pré-operatória de pacientes com problemas cardiovasculares, alguns\nexames cardiológicos costumam ser requisitados, como é o caso da eletrocardiografia, da\nradiografia de tórax, do teste ergométrico, da ecodopplercardiografia, dentre outros mais que\npossam vir a ser úteis. No que concerne à ecodopplercardiografia, é INCORRETO afirmar:","options":{"A":"É um exame não invasivo, baseado no uso do ultrassom.","B":"Propicia informações complementares quanto à função ventricular sistólica.","C":"O seu uso é recomendado no perioperatório apenas quando há alguma certeza clínica.","D":"Não é um exame essencial."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274630","number":"274630","sourceNumber":"274630","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A dose-limite do anestésico local lidocaína sem vasoconstritor para um homem de 70\nkg é:","options":{"A":"350 mg.","B":"700 mg.","C":"500 mg.","D":"150 mg."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274632","number":"274632","sourceNumber":"274632","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considerando os tipos de fios e técnicas de suturas, o material utilizado para\nfechamento ósseo após esternotomia é:","options":{"A":"Grampos metálicos.","B":"Fio de seda.","C":"Categute.","D":"Fio de aço."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274633","number":"274633","sourceNumber":"274633","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As comorbidades do paciente podem influenciar o resultado do processo de anestesia\ne/ou cirurgia. Dadas as alternativas abaixo, a\nque apresenta a maior taxa de mortalidade pela\nanestesia é:","options":{"A":"Paciente com hipertensão controlada com medicação de uso diário e atividade física.","B":"Paciente com diabetes mellitus descompensado com lesão secundária em órgão-alvo.","C":"Paciente com doença pulmonar obstrutiva crônica oxigênio-dependente.","D":"Paciente com doença sistêmica limitante, mas não incapacitante."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274636","number":"274636","sourceNumber":"274636","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A febre pós-operatória é produzida em resposta tanto a processos infecciosos quanto a\nnão infecciosos. Considerando as principais\ncausas de febre no pós-operatório, a alternativa que se\nrefere à coleção intracavitária, fístula é:","options":{"A":"24 horas.","B":"72 horas.","C":"48 horas.","D":"Após 7 dias."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274639","number":"274639","sourceNumber":"274639","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A inabilidade de micção espontânea é comum no pós-operatório, especialmente após\ncirurgias pélvicas e perineais ou em procedimentos em que foi empregada raquianestesia ou\nperidural. São todos fatores relacionados e que interferem na retenção urinária, EXCETO:","options":{"A":"Alterações neurais responsáveis pelo normal esvaziamento da bexiga.","B":"Infecção do órgão.","C":"Trauma operatório ao plexo.","D":"Distensão excessiva do órgão."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274644","number":"274644","sourceNumber":"274644","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias da parede abdominal e inguinocrural representam afecções frequentes nos\nserviços de cirurgia geral e constituem as operações eletivas mais realizadas. Considerando a\nregião anatômica, exemplos de hérnias da região inguinofemoral são:","options":{"A":"Hérnias lombares.","B":"Hérnias ventrolaterais de Spiegel.","C":"Hérnias periestomais.","D":"Hérnias obturatórias."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-274651","number":"274651","sourceNumber":"274651","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O suporte respiratório é, em diversas ocasiões, solicitado a pacientes que se encontram\nem estado crítico devido às complicações\nrespiratórias pulmonares decorrentes, em muitos casos,\nde cirurgias ginecológicas ou obstétricas. Quanto ao tipo de insuficiência e às suas\ncaracterísticas,\né CORRETO afirmar:","options":{"A":"Insuficiência respiratória hipercápnica, a qual associa-se à elevação da ventilação para a\nrealização da troca de gases no pulmão.","B":"Insuficiência respiratória hipercápnica, a qual se consubstancia por pressão parcial arterial\naumentada de dióxido de carbono (PaCO2) > 25 mmHg e pH < 7,35.","C":"Insuficiência respiratória hipóxica, a qual associa-se à hipoventilação.","D":"Insuficiência respiratória hipóxica, a qual se consubstancia por pressão parcial arterial de\noxigênio diminuída (PaQ2) < 60 mmHg e/ou saturação de oxigênio arterial (SaO2)."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-263408","number":"263408","sourceNumber":"263408","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente com 25 anos de idade foi submetida à ressecção eletiva de segmento de\ncólon sigmoide de cerca de 10 cm devido à estenose intestinal ocasionada por endometriose\npélvica. No pré-operatório, foi realizado apenas preparo de cólon distal com clister glicerinado.\n\nDurante a cirurgia, com duração de 4 horas, não houve extravasamento de fezes no momento da\nabertura colônica e foi realizada anastomose primária com fio inabsorvível monofilamentar. Para\nesse caso, a antibioticoprofilaxia adequada deve ser feita","options":{"A":"no momento da incisão com dose única.","B":"no momento da incisão, com repetição da dose a cada 2 a 4 horas e manter por 24 horas após a\ncirurgia.","C":"até uma hora antes da incisão cirúrgica com repetição da dose a cada 2 a 4 horas e manter por\n48 horas após a cirurgia.","D":"até uma hora antes da incisão cirúrgica com repetição da dose a cada 2 ou 4 horas apenas\ndurante o ato operatório."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-291546","number":"291546","sourceNumber":"291546","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um homem com 20 anos de idade foi atendido em ambulatório de hospital secundário 7\ndias após a sutura de ferimento corto-contuso no antebraço direito para retirada dos pontos.\n\nRelatava que, há 3 dias, sentia dor e a ferida encontrava-se abaulada e arroxeada. Não relatou\nfebre no período. A incisão com\naproximadamente 10 cm estava suturada com pontos simples de\nfio de náilon, apresentava abaulamento doloroso em toda a extensão, pouco depressível e havia\nequimose das bordas da ferida. Com base nos dados apresentados, assinale a alternativa que\napresenta a conduta adequada.","options":{"A":"Retirar todos os pontos e manter as bordas aproximadas com esparadrapo microporoso.","B":"Prescrever antibiótico via oral e agendar retirada dos pontos após mais uma semana.","C":"Encaminhar ao pronto-socorro para revisão da hemostasia com anestesia.","D":"Retirar alguns pontos para drenagem da ferida e agendar retorno para avaliação."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-227370","number":"227370","sourceNumber":"227370","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de vinte e cinco anos de idade, vítima de acidente automobilístico com\ncapotamento ocorrido havia 8 horas, foi levado\nao pronto-socorro, onde deu entrada consciente,\norientado, imobilizado em prancha rígida, com colar cervical. O paciente apresentava sinais vitais\nnormais, quadro de dor em região cervical, abdominal e lacerações em membros superiores e\ninferiores. Com relação a esse caso clínico e aos múltiplos aspectos a ele relacionados, julgue o\nitem a seguir. Devido ao tempo decorrido entre o acidente e o atendimento, não se deve suturar as\nlacerações de pele, pois isso aumentaria o risco de infecção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-244465","number":"244465","sourceNumber":"244465","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Nos últimos anos, o manejo perioperatório tem sido questionado com uma série de\nevidências científicas, gerando protocolos como o Enhanced Recovery after Surgery (ERAS) ou a\nAceleração da Recuperação Total pós-operatória (ACERTO). Assinale a alternativa que indica um\ndos pilares desses protocolos.","options":{"A":"Padronizar o tempo de jejum pré-operatório de no mínimo 12 horas, a fim de garantir a\nsegurança do paciente durante o procedimento.","B":"Efetuar tratamento intensivo das náuseas e dos vômitos.","C":"Solicitar coleta de exames de rotina no pré-cirúrgico e no pós-cirúrgico, bem como no pré e\npós-parto.","D":"Realizar mobilização cautelosa no pós-cirúrgico, ou seja, não incentivar a mobilização precoce, a\nfim de evitar eventos adversos ao paciente e complicações no pós-cirúrgico.","E":"Evitar administração excessiva de fluídos no perioperatório."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-227379","number":"227379","sourceNumber":"227379","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias em geral são doenças prevalentes na população adulta e motivo frequente\nde atendimento em ambulatórios de cirurgia geral. A\nrespeito desse assunto, julgue o item que se\nsegue. A cirurgia para tratamento de hérnia inguinal é classificada como limpa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-227380","number":"227380","sourceNumber":"227380","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias em geral são doenças prevalentes na população adulta e motivo frequente\nde atendimento em ambulatórios de cirurgia geral. A\nrespeito desse assunto, julgue o item que se\nsegue. Hérnia femoral é mais prevalente em mulheres do que em homens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-227381","number":"227381","sourceNumber":"227381","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias em geral são doenças prevalentes na população adulta e motivo frequente\nde atendimento em ambulatórios de cirurgia geral. A\nrespeito desse assunto, julgue o item que se\nsegue. Prótese é comumente utilizada tanto na técnica de Lichtenstein quanto no tratamento de\nhérnia inguinal por videolaparoscopia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-230575","number":"230575","sourceNumber":"230575","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Das alternativas abaixo assinale aquela que representa uma criança com sedação\nadequada:","options":{"A":"Criança desperta com o estímulo.","B":"Criança sorri.","C":"Criança apresenta taquicardia.","D":"Criança encontra-se inconsciente."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-230581","number":"230581","sourceNumber":"230581","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre os anestésico inalatórios, assinale a CORRETA:","options":{"A":"o óxido nitroso é o agente mais escolhido para indução anestésica de pacientes com\nhipertensão intra-abdominal.","B":"o halotano é o agente que apresenta alta biotransformação, por isso deve ser evitado em\npacientes que apresentem lesão hepatocelular.","C":"o isoflurano é o agente que apresenta maior Concentração Alveolar Mínima (CAM), por isso é\nmais potente e sua ação é mais rápida quando comparado ao halotano.","D":"o halotano é o agente que apresenta maior Concentração Alveolar Mínima (CAM), por isso é\nconsiderado o agente inalatório mais potente."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-230594","number":"230594","sourceNumber":"230594","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"De acordo com a classificação de infecções do sítio cirúrgico segundo o CDC (Center\nfor Disease Control) e ANVISA, assinale a CORRETA:","options":{"A":"elas podem ser classificadas em 4 tipos: superficial externa, superficial interna, profunda e\nórgão/cavitária.","B":"a infecção do tipo profunda ocorre nos primeiros 30 dias após a cirurgia ou até um ano, se\nhouver colocação de prótese, e envolve tecidos moles profundos à incisão (ex: fáscia e/ou\nmúsculos).","C":"a infecção do tipo superficial externa ocorre até os o trigésimo dia pós operatório e acomete\napenas a epiderme e derme.","D":"a infecção do tipo órgão/cavidade ocorre sempre após 30 dias após a cirurgia ou até um ano, se\nhouver colocação de prótese, e envolve qualquer órgão ou cavidade que tenha sido aberta ou\nmanipulada durante a cirurgia."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-203118","number":"203118","sourceNumber":"203118","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 14 anos de idade foi submetido à laparotomia exploradora com achado\nde apendicite aguda perfurada, com peritonite\nlocalizada. Evoluiu, no segundo dia de\n\npós-operatório, com febre aferida de 38°C. Acerca desse caso clínico, qual é a principal hipótese\ndiagnóstica?","options":{"A":"Atelectasia","B":"Abscesso intra-abdominal","C":"Pneumonia.","D":"Infeccção de sitio cirúrgico","E":"Infecção de trato urinário."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-206154","number":"206154","sourceNumber":"206154","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa que representa uma situação em que a sequência rápida de\nintubação esteja indicada:","options":{"A":"Paciente em parada cardiorrespiratória.","B":"Pacientes em coma profundo.","C":"Pacientes em broncoespasmo.","D":"Recém-nascidos com síndrome do desconforto respiratório."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-206134","number":"206134","sourceNumber":"206134","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A atelectasia é definida como o colapso de porção variável do parênquima pulmonar.\nAssinale a alternativa INCORRETA sobre a atelectasia no pós-operatório.","options":{"A":"Os fumantes são encorajados a parar de fumar pelo menos 1 semana antes da cirurgia.","B":"A manobra no qual se pede para o paciente tossir com a aplicação de um travesseiro sobre o\nlocal da incisão abdominal deve ser desencorajada devido ao maior risco de hérnia incisional.","C":"O tratamento de pacientes com DPOC, asma e ICC deve ser otimizado previamente ao\nprocedimento cirúrgico.","D":"Controle da dor adequado e boa higiene pulmonar são importantes no período pós-operatório."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-206139","number":"206139","sourceNumber":"206139","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação ao isoflurano:","options":{"A":"Em concentrações iguais ou menores que de 1,0 CAM, o isoflurano causa pequena redução do\nfluxo sanguíneo cerebral e da pressão intracraniana (PIC).","B":"O isoflurano continua popular, pelo menos em parte, devido aos baixos custos de produção.","C":"Seu odor irritante praticamente impede seu uso para indução inalatória.","D":"Uma eventual taquicardia induzida pelo isoflurano pode aumentar o consumo miocárdico de\noxigênio."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-177245","number":"177245","sourceNumber":"177245","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente do sexo masculino, de 65 anos de idade, realiza uma consulta em razão de\ndor em região inguinal esquerda, ao\nrealizar esforço. Relata já ter realizado cirurgia para tratamento\nde hérnia na mesma região há cerca de 20 anos, mas não sabe informar se foi utilizada tela de\nmárlex na cirurgia. Refere ocasionalmente dor similar na região inguinal direita. Ao exame físico, o\npaciente apresentou abaulamento parcialmente redutível em região inguinal esquerda à manobra\nde Valsalva, além de abaulamento redutível em região inguinal direita à manobra Valsalva, o que\nsugere hérnia inguinal bilateral. Considerando-se o caso clínico relatado e os conhecimentos\nmédicos referentes ao tratamento cirúrgico das hérnias inguinais, é correto afirmar que","options":{"A":"a técnica de Lichtenstein corresponde ao fechamento da parede posterior pela aproximação da\nfáscia transversal e da aponeurose do oblíquo externo e transverso ao ligamento inguinal com\npontos separados.","B":"o tratamento laparoscópico tem base na técnica de Stoppa, na qual é colocada uma tela\npré-peritoneal, cobrindo toda a região inguinal.","C":"na técnica de Bassini, realiza-se reparo do anel femoral por aproximação da fáscia transversal\nao ligamento de Cooper.","D":"a técnica de McVay corresponde à fixação de tela sem tensão ao ligamento inguinal, ao\ntubérculo púbico, à bainha do músculo reto e à aponeurose do oblíquo interno e transverso.","E":"O tratamento laparoscópico é indicado apenas para hérnias bilaterais ou recidivantes."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-177229","number":"177229","sourceNumber":"177229","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Considere um paciente do sexo masculino, de 35 anos de idade, que apresenta hérnia\ninguinal tipo II na classificação de Nyhus. O paciente não apresenta outras alterações no exame\nfísico e nega outras doenças e cirurgias prévias. Com base no referido caso clinico e considerando\nos conhecimentos médicos relacionados à correção de hérnia inguinal, assinale a alternativa\ncorreta.","options":{"A":"No reparo de hérnia inguinal com tensão, a técnica de McVay utiliza a fásola transversalis e o\nligamento de Cooper.","B":"O mencionado paciente se beneficiaria de uma hernioplastia Lichtenstein, que é um reparo livre\nde tensão e tem uso de tela.","C":"Mesmo em pacientes altamente selecionados, o reparo de Shouldice é associado a altas taxas\nde recidiva.","D":"O reparo videolaparoscópico extraperitoneal e pré-peritoneal transabdominal de hérnias\ninguinais é uma técnica que promove mais tensão nos tecidos pela fixação da tela.","E":"Caso se optasse pela técnica de Bassini, que é uma técnica sem tensão, o reparo seria com\ntendão conjunto e o ligamento inguinal, sem tela"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-177242","number":"177242","sourceNumber":"177242","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à infecção do sítio cirúrgico, assinale a alternativa correta.","options":{"A":"Alguns fatores de risco relacionados ao paciente são: obesidade, imunossupressão, transfusões\nsanguíneas transoperatórias, tabagismo, idade,\nneoplasia e esteróides.","B":"Feridas cirúrgicas em que o trato digestivo é violado de forma controlada são classificadas como\ncontaminadas.","C":"Os cuidados e a preparação do sítio cirúrgico não modificam a incidência de infecção local.","D":"O uso de avental estéril é um modo de manter a equipe cirúrgica segura, não interferindo na\ntaxa de infecção do sítio cirúrgico.","E":"Pacientes desnutridos e com níveis elevados de albumina estão associados ao aumento da\ninfecção no sítio cirúrgico."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183871","number":"183871","sourceNumber":"183871","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que diz respeito ao controle clínico do paciente cirúrgico, julgue o item que se\nsegue. Pacientes com Insuficiência Renal Crônica\n(IRC) têm especial propensão a desenvolver\nsangramentos transoperatórios em decorrência de disfunção plaquetária, mesmo quando a\ncontagem de plaquetas no sangue periférico é normal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183885","number":"183885","sourceNumber":"183885","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que diz respeito ao controle clínico do paciente cirúrgico, julgue o item que se\nsegue. No pré-operatório, devem ser suspensas\nas medicações anti-hipertensivas de pacientes\nportadores de hipotensão arterial sistêmica (HAS), para evitar a ocorrência de hipertensão\ndecorrente de eventuais perdas volêmicas durante procedimentos cirúrgicos de grande porte.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183894","number":"183894","sourceNumber":"183894","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que diz respeito ao controle clínico do paciente cirúrgico, julgue o item que se\nsegue. A doença arterial coronariana é a afecção cardíaca mais comum e a principal causa de\nmorbidade e mortalidade de origem cardiáca em pacientes cirúrgicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183847","number":"183847","sourceNumber":"183847","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que se refere à avaliação da função pulmonar - espirometria - no paciente cirúrgico,\njulgue o item subsequente. A restrição ao\nfluxo aéreo é um dos achados característicos da fibrose\npulmonar causada pela silicose (pneumopatia ocupacional).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-183853","number":"183853","sourceNumber":"183853","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que se refere à avaliação da função pulmonar - espirometria - no paciente cirúrgico,\njulgue o item subsequente. A redução da\ncapacidade residual funcional (CRF) é um dos achados\ncaracterísticos da doença pulmonal obstrutiva crônica (DPOC).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-175126","number":"175126","sourceNumber":"175126","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Para diminuir o risco de aspiração pulmonar, o jejum recomendado para fórmula infantil\né de:","options":{"A":"2 horas.","B":"4 horas.","C":"6 horas.","D":"8 horas."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-175127","number":"175127","sourceNumber":"175127","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São contraindicações à Raquianestesia, EXCETO:","options":{"A":"Sepse.","B":"Infecção no local da punção.","C":"CIVD.","D":"Diminuição da pressão intracraniana."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-175134","number":"175134","sourceNumber":"175134","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São efeitos colaterais relacionados ao uso de Opioides, EXCETO:","options":{"A":"Depressão respiratória.","B":"Vômito.","C":"Midríase.","D":"Rigidez dos músculos esqueléticos."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-175136","number":"175136","sourceNumber":"175136","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual fármaco abaixo tem efeito analgésico e hipnótico?","options":{"A":"Etomidato.","B":"Cetamina.","C":"Alfentanil.","D":"Dexmedetomedina."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-175137","number":"175137","sourceNumber":"175137","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Podemos afirmar que o paciente que possui apenas palato duro visível, possui\nMallampati:","options":{"A":"I","B":"II","C":"III","D":"IV"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-154497","number":"154497","sourceNumber":"154497","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente em pós-operatório imediato de hepatectomia parcial com duração de 4h,\nqueixando-se de dispneia. Ao exame físico, está taquipneico (32 irpm), com limitação das incursões\nrespiratórias por conta de dor em ferida operatória, taquicárdico (108 bpm), febril (37,9ºC), com\nsaturação periférica de oxigênio de 88% em ar ambiente, murmúrio vesicular abolido em base\npulmonar direita. Qual é o provável diagnóstico?","options":{"A":"Hérnia diafragmática.","B":"Derrame pleural.","C":"Atelectasia pulmonar.","D":"Pneumonia hospitalar.","E":"Tromboembolismo pulmonar."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-168431","number":"168431","sourceNumber":"168431","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um homem com 48 anos de idade, tabagista crônico e hipertenso, é admitido em um\nhospital para correção de aneurisma aortoilíaco esquerdo, com a utilização de prótese vascular.\nDurante a checagem de informações do protocolo de cirurgia segura, a conduta adequada do\ncirurgião assistente é","options":{"A":"indicar antibioticoterapia e não profilaxia para minimizar o risco de infecção.","B":"indicar antibioticoprofilaxia em cirurgia vascular porque há o uso de prótese.","C":"indicar antibioticoprofilaxia em paciente porque há comorbidades.","D":"não indicar antibioticoprofilaxia por tratar-se de cururgia limpa."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-168459","number":"168459","sourceNumber":"168459","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente com 71 anos de idade e diagnóstico de catarata bilateral definido em\navaliação anterior há 6 meses, é atendida no ambulatório para programação de cirurgia de\ncatarata, categoria de procedimento de pequeno porte e de curta permanência, sob anestesia local.\nRegistradas no prontuário da paciente, constam as seguintes informações: sobrepeso (índice de\nmassa corporal = 26 kg/m²) e hipertensão arterial sistêmica e hipercolesterolemia em\nacompanhamento com cardiologista periodicamente (última consulta há 2 meses) e uso de\nmedicação de rotina (propanolol e sinvastatina). Ao exame físico, conclui-se que, da consulta\nanterior para a atual, não há mudanças a situação clínica da paciente. Entre os cuidados\n\npré-operatórios à paciente, qual a conduta médica adequada?","options":{"A":"Solicitar os seguintes exames laboratoriais: hemograma, glicemia, eletrólitos, bem como a\nrealização de radiografia de tórax e eletrocardiograma, para identificar doenças não detectadas\npelo exame clínico; recomendar, ainda, paciente que interrompa as medicações de uso contínuo\numa semana antes da cirurgia.","B":"Solicitar exames laboratoriais para verificar taxa de creatinina e ureia, bem como a realização\nde\neletrocardiograma e ecocardiograma transtorácido devido ao dignóstico de hipertensão arterial\nsistêmica; recomendar à paciente que mantenha as medicações de uso contínuo.","C":"Solicitar os seguintes exames laboratoriais: hemograma, glicemia, eletrólitos, porque a paciente\ntem hipertensão arterial sistêmica e mais de 50\nanos de idade; recomendar à paciente que\ninterrompa as medicações de uso contínuo na véspera da cirurgia.","D":"Dispensar a solicitação de exames, pois a paciente é portadora de hipertensão arterial sistêmica\ncompensada e está sob acompanhamento médico; recomendar à paciente que mantenha as\nmedicações de uso contínuo."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-158064","number":"158064","sourceNumber":"158064","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente tabagista e diabético, no 10º dia de pós-operatório de correção de hérnia\ninguinal, comparece à emergência apresentando drenagem de secreção amarelada pela ferida\noperatória. Durante o exame físico, percebe-se hiperemia em ferida operatória associada a\ndrenagem de secreção purulenta. O restante do exame físico é normal. Considerando esse caso\nclínico, quanto à principal hipótese diagnóstica, assinale a alternativa CORRETA.","options":{"A":"Infecção de sítio-cirúrgico.","B":"Seroma.","C":"Hematoma.","D":"Recidiva da hérnia.","E":"Deiscência de sutura."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-129046","number":"129046","sourceNumber":"129046","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No que diz respeito à cicatrização de feridas, assinale a alternativa correta.","options":{"A":"A resistência das feridas à ruptura é maior na fase inflamatória.","B":"A fase de maturação é caracterizada por maior síntese de colágeno tipo I.","C":"Na pele do adulto, o colágeno tipo III é o mais comum.","D":"A função primária dos fibroblastos é a síntese de fibrina.","E":"Os linfócitos T são os primeiros leucócitos a aparecer na ferida, com maior concentração no\nprimeiro e no segundo dias."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-104762","number":"104762","sourceNumber":"104762","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um importante fenômeno que acontece nos procedimentos operatórios é a cicatrização\nde feridas. No que se refere a esse tema,\nassinale a alternativa correta.","options":{"A":"No início do processo cicatricial, há maior concentração de colágeno tipo I que depois será\nsubstituído por colágeno tipo II e em seguida\npor colágeno tipo lll nas fases de maturação da ferida.","B":"As plaquetas liberam radicais livres que recrutarão os linfócitos T e B.","C":"Os neutrófilos produzem fibronectina.","D":"O fator de necrose tumoral (TNF) alfa é produzido pelos macrófagos e induz à marginação e à\ncitotoxicidade de polimorfonucleares.","E":"Todas as interleucinas são produzidas pelos fibroblastos."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-97775","number":"97775","sourceNumber":"97775","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Uma paciente com 23 anos de idade, submetida à cirurgia cesariana há cerca de 90\ndias, com incisão mediana, é atendida em Unidade Básica de Saúde com relato de abaulamento\nem região suprapúbica e dor local aos esforços, de início associado ao retomo de atividades\ndomésticas (lavar roupas manualmente). Com base no quadro clínico exposto, qual a hipótese\ndiagnóstica correta?","options":{"A":"Hematoma de bainha do reto abdominal.","B":"Corpo estranho pós-cirúrgico.","C":"Seroma volumoso.","D":"Hérnia incisional."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-97803","number":"97803","sourceNumber":"97803","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um adolescente com 17 anos de idade estava praticando moutain bike quando sofreu\numa queda em um trecho cheio de lama e feriu\no dorso, há cerca de quatro horas. Ao exame físico,\nna Unidade de Pronto-Socorro, observou-se ferimento com cerca de seis centímetros de extensão\nem região escapular, acometendo a pele e o tecido subcutâneo, sem sangramento ativo, bordos\nregulares, sujo de terra. A mãe dele informou que todas as vacinas regulares foram feitas nas datas\nprevistas e que a vacina antitetânica foi feita há cinco anos. Depois da limpeza da ferida, qual é a\nconduta indicada?","options":{"A":"Desbridamento das bordas, curativo e cicatrização por segunda intenção, imunoglobulina\nantitetânica.","B":"Sutura primária, sem necessidade de imunuglobulina ou toxoide tetânico.","C":"Sutura primária, toxoide tetânico e imunoglobulina antitetânica.","D":"Desbridamento das bordas, sutura primária e toxoide tetânico."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-75456","number":"75456","sourceNumber":"75456","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem de 22 anos de idade procura a Unidade Básica de Saúde de seu bairro com\nnáuseas, vômitos e ?caroço doloroso na virilha?. Informa que há três anos essa massa aparece\nquando faz esforço e desaparece ao deitar-se, mas desta vez vem se mantendo há dois dias. Ao\nexame físico: paciente em bom estado geral e aumento de volume na região inguinal e do escroto\ndireito, com dor à palpação. A conduta a ser adotada pelo médico da Unidade é:","options":{"A":"administração de relaxante muscular, colocando o paciente em posição de Trendelenburg, com\ntentativa de redução do volume.","B":"encaminhamento do paciente ao Serviço de Urgência do Hospital com o pedido de avaliação\nimediata do cirurgião.","C":"tentativa de redução manual do aumento de volume da região inguinoescrotal para a cavidade\nabdominal.","D":"transiluminação do escroto para tentar diferenciar hérnia inguinal de hidrocele comunicante.","E":"prescrição de antiemético e solicitação de ecografia da região inguinoescrotal."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-75565","number":"75565","sourceNumber":"75565","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher com 45 anos de idade, em preparo para colecistectomia por doença calculosa,\nprocura o médico da Unidade Básica de\nSaúde de seu bairro, apresentando os resultados dos\nexames laboratoriais solicitados. O hemograma apresenta hemoglobina = 11 g/dL. Ela quer saber\nsobre o risco da necessidade de transfusão de sangue durante a operação. Salienta que não\nperguntou ao cirurgião a respeito da necessidade de transfusão. Tendo como base o Guia para o\nUso de Hemocomponentes do Ministério da Saúde, o médico formulará a resposta à paciente com\nbase no fato de que:","options":{"A":"a transfusão de hemocomponentes traz riscos\nimediatos ou tardios e por isso deve ser evitada na\ncirurgia proposta, se possível.","B":"a transfusão de concentrado de hemácias está\n\nrecomendada após perda volêmica superior a 8% da volemia total.","C":"as cirurgias de abdome exigem reserva de sangue\n\npara transfusão porque pode ser necessário ampliar a ressecção.","D":"as mulheres, após os 40 anos de idade, podem ter\n\nanemia leve, por isso é correto reservar sangue para a cirurgia.","E":"a transfusão poderá ser indicada com a finalidade de proporcionar a mais rápida recuperação da\npaciente."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-137627","number":"137627","sourceNumber":"137627","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um homem de 47 anos de idade, portador de diabetes do tipo 1, foi submetido a\nvasectomia há 5 dias. Hoje comparece à Unidade de Emergência queixando-se de febre alta,\ngrande aumento de volume escrotal, edema, dor acentuada e coloração avermelhada no escroto.\nAo exame de palpação do escroto, verifica-se a presença de enfisema subcutâneo. Qual o\ndiagnóstico mais provável e a conduta adequada para o caso?","options":{"A":"Fasceíte necrotizante; debridamento cirúrgico e antibioticoterapia de amplo espectro.","B":"Abscesso escrotal; drenagem e antibioticoterapia de amplo espectro.","C":"Abscesso escrotal; drenagem, antiinflamatório inibidor da ciclo-oxigenase 2","D":"Coleção serosa; drenagem por punção, antiinflamatório inibidor da ciclo-oxigenase 2.","E":"Torção testicular iatrogênica; intervenção cirúrgica de liberação do testículo."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-137687","number":"137687","sourceNumber":"137687","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um homem de 35 anos de idade, tabagista (60 maços/ano) encontra-se hospitalizado,\nno sétimo dia pós-operatório de rafia de\núlcera gástrica. Há dois dias apresenta febre vespertina e\ndor em hipocôndrio D, referida na região subescapular. Ao exame, apresenta-se com estado geral\nregular, temperatura axilar = 38,6°C, pulso = 116 bpm, frequência respiratória = 28 irpm, PA = 112 x\n67 mmHg. O abdome é discretamente distendido, doloroso à palpação, notadamente no\nhipocôndrio D, onde observa-se defesa voluntária e percussão também dolorosa; ruídos\nhidroaéreos presentes. A punho a percussão lombar é dolorosa à direita. A expansibilidade\npulmonar está diminuída no hemitórax direito e o murmúrio vesicular um pouco diminuído na base\ndo pulmão D. O leucograma mostra 16.200 leucócitos/mm3 (valor de referência: 3800 a 10600/mm\n\n) com 17% de bastões. A Proteína C Reativa é de 4,5 mg /dL (valor de referência = 0,3 a 0,5 mg\n\n/dL). A principal hipótese diagnóstica é","options":{"A":"pielonefrite aguda.","B":"abscesso subfrênico.","C":"pneumotórax espontâneo.","D":"pneumonia de base pulmonar D.","E":"deiscência de rafia gástrica com pneumoperitôneo."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-352192","number":"352192","sourceNumber":"352192","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente feminina, 21 anos, sem comorbidades ou alergias medicamentosas, com\nhérnia umbilical redutível e sintomática. Qual a conduta correta no pré-operatório de herniorrafia\numbilical para esta paciente?","options":{"A":"Solicitar hemograma, glicemia de jejum, exame de urina de elementos anormais e sedimento\n(EAS), tempo de atividade de protrombina (TAP) e\ntempo de tromboplastina parcial ativado (PTTa).","B":"Devido alto risco de eventos tromboembólicos, indicar profilaxia farmacológica com heparina de\nbaixo peso molecular.","C":"Orientar jejum de 2 horas para líquidos claros.","D":"Classificar a paciente como risco cirúrgico ASA III."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-368192","number":"368192","sourceNumber":"368192","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Para a indicação da profilaxia antibiótica em cirurgia, a correta associação entre o\nsítio\ncirúrgico abordado e a flora bacteriana usualmente mais infectante é:","options":{"A":"Trato urinário ? Bacilos Gram-negativos e Gram-positivos.","B":"Gastrointestinais ? Bacilos Gram-positivos.","C":"Uso de próteses / implantes ? Bacilos Gram-negativos.","D":"Trato ginecológico ? Bacilos Gram-negativos, Gram-positivos e anaeróbios."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-351590","number":"351590","sourceNumber":"351590","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação ao acesso cirúrgico para tratar as hérnias femorais, é CORRETO afirmar\nque:","options":{"A":"A vantagem do acesso pré-peritoneal é sua facilidade na execução.","B":"O acesso femoral tem como vantagem reparo sem tensão e pequena taxa de recidiva.","C":"O acesso pré-peritoneal não permite uma boa exposição nem a correção de outras hérnias\nassociadas.","D":"O acesso inguinal é o que permite maior exposição local, com redução do conteúdo do saco\nherniário."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-354092","number":"354092","sourceNumber":"354092","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No Hospital Maternidade São José, foi indicada cirurgia para correção de uma hérnia na\nregião inguinal (acima da prega inguinal) em uma mulher de 70 anos, multípara de 5 filhos (partos\nnormais), portadora de obesidade e doença pulmonar obstrutiva crônica, devido ao tabagismo\n(35anos/maço). Com esses dados, pode-se concluir que o tipo mais provável de hérnia da paciente\né:","options":{"A":"Inguinal indireta.","B":"Inguinal direta.","C":"Obturatória.","D":"Crural.","E":"Spigel."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-354098","number":"354098","sourceNumber":"354098","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Fístulas enterocutâneas são comunicações anormais entre o trato gastrointestinal e a\npele. Estão geralmente associadas a uma tríade de sepse, desequilíbrio líquido eletrolítico e\ndesnutrição. A gravidade dessas manifestações depende da anatomia e fisiologia cirúrgica da\nfístula. Considerando as manifestações relacionadas às fístulas enterocutâneas, assinale a\nalternativa correta:","options":{"A":"Nos pacientes com fístulas de indicação cirúrgica, deve-se evitar grandes dissecções\nintracavitárias, pois se trata normalmente de\ndoentes graves, anêmicos e desnutridos. O ideal,\nnestes casos, é a menor abordagem possível com exteriorização apenas do segmento doente e\nposterior ressecção e anastomose.","B":"Existe indicação cirúrgica sempre que a fístula apresentar secreção fecalóide.","C":"As fístulas de anastomoses gástricas em geral têm bom prognóstico.","D":"Para prevenção das fístulas o octreotide deve ser sempre utilizado durante a indução\nanestésica.","E":"Processos suboclusivos distal à fístula, alto débito, fístulas labiadas, desnutrição e doenças\nintestinais como Chron e tuberculose são situações de mau prognóstico para fechamento\nespontâneo."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-336255","number":"336255","sourceNumber":"336255","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre correção de hérnias inguino crurais:","options":{"A":"As técnicas de Lichtenstein e Stoppa utilizam tela de polipropileno polifilamentado não\nabsorvível.","B":"A técnica de Mcvay consiste em aproximar a margem da aponeurose do transverso do abdome\nao ligamento de Cooper e trato iliopúbico","C":"A técnica de Bassini consiste na aproximação com sutura em dupla camada do músculo oblíquo\nexterno, do arco aponeurótico do músculo transversoao trato ilio-púbico (lig. de Thomson) e\nligamento inguinal (lig. de Poupart).","D":"A técnica de Shouldice consiste na imbricação da parede anterior do canal inguinal com suturas\ncontínuas em 3 ou 4 planos, do plano mais superficial para o mais profundo"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-336259","number":"336259","sourceNumber":"336259","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher, 57 anos, queixa de edema em panturrilha direita e dor contínua com início há 2\ndias. Relata cirurgia prévia há 12 dias de adbominoplastia e que permaneceu em \"repouso\nabsoluto\" devido dor na cirurgia e receio de rompimento dos pontos. Ao exame: panturrilha direita\nedemaciada com menor mobilidade em comparação à esquerda, dor após dorsiflexão passiva do\npé direito. Solicitado ultrassonografia com doppler de membros inferiores que só poderá ser\nrealizado no dia seguinte. Qual é a conduta adequada neste momento ?","options":{"A":"Admnistrar heparina não fracionada, subcutânea, 1mg/Kg a cada 12 h.","B":"Tranquilizar a paciente e aguardar a realização da US para decidir a conduta.","C":"Administrar heparina de baixo peso molecular, subcutânea, 1mg/Kg a cada 12h.","D":"Explicar à paciente que o quadro é esperado e orientá-la a deambular."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-337620","number":"337620","sourceNumber":"337620","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"No bloco cirúrgico um paciente foi submetido a correção cirúrgica aberta denominada\nde técnica de McVay. Nesse caso é CORRETO afirmar\nque se trata de uma hérnia:","options":{"A":"Tipo IV de Nyhus.","B":"Tipo III A de Nyhus.","C":"Tipo III C de Nyhus.","D":"Obturadora, não classificada em Nyhus."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-336264","number":"336264","sourceNumber":"336264","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente 58 anos, hipertenso, em primeiro dia de pós-operatório de hérnia discal após\n10 horas do procedimento, evolui com dor\nabdominal importante a palpação e agitação. Feito FAST\na beira leito com a imagem abaixo. Após análise da imagem sua conduta é:","options":{"A":"Sondagem vesical de alívio.","B":"Passagem de sonda nasogástrica.","C":"Tomografia de abdome.","D":"Avaliação do cirurgião com urgência."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/336264.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-335078","number":"335078","sourceNumber":"335078","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Nos cuidados pós-operatórios ao retorno da alimentação oral do paciente idoso, o\ncirurgião deve proceder da seguinte maneira:","options":{"A":"Antecipar a capacidade do idoso para uma alimentação oral, caso não haja problemas no\nintraoperatório.","B":"Adiar por pelo menos duas semanas o retorno à alimentação oral, mesmo sem problemas no\nintraoperatório.","C":"Manter a alimentação enteral, em detrimento da oral, em todos os casos pelo maior tempo\npossível.","D":"Optar pela colocação de sonda nasoduodenal, nasojejunal ou jejunostomia e mantê-la no\npós-operatório em vez de voltar à alimentação oral."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-335081","number":"335081","sourceNumber":"335081","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente do sexo masculino, 54 anos de idade, é submetido a anestesia geral com\nentubação. Depois de dois minutos, o oxímetro de pulso apresenta uma leitura de 93%, sua\npressão arterial sistólica cai para 40 mmHg e sua frequência cardíaca diminui para 35 bpm. Nesse\nmomento, a melhor conduta a ser feita é","options":{"A":"realizar cardioversão sincronizada.","B":"colocar o paciente na posição de Trendelenburg, com o lado esquerdo para baixo.","C":"avaliar a colocação do tubo orotraqueal.","D":"realizar administração intravenosa rápida de um ?-agonista."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345712","number":"345712","sourceNumber":"345712","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das alternativas a seguir apresenta o principal fator de risco para TVP em crianças\nmenores?","options":{"A":"Administração de insulina","B":"Terapia enteral prolongada","C":"Fármacos para úlcera por estresse","D":"Cateter venoso central"},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345722","number":"345722","sourceNumber":"345722","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente em primeiro dia de pós-operatório de gastrectomia total por adenocarcinoma\ngástrico apresenta taquicardia, febre e taquipneia.\nAssinale a principal hipótese diagnóstica.","options":{"A":"Infecção de sítio cirúrgico.","B":"Deiscência anastomótica.","C":"Infecção urinária.","D":"Atelectasia."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-336282","number":"336282","sourceNumber":"336282","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Menino, 5 anos, internado com pneumonia e derrame pleural esquerda é encaminhado\nao centro cirurgico para drenagem de tórax.\nRealizado procedimento sob sedação inalatória,\ncontudo evoluiu ao final com TAX: 39,4°C, FC: 192 bpm, FR: 48 irpm e rigidez muscular, sem\noutras alterações. Diante do quadro clinico, o tratamento adequado é:","options":{"A":"Dantrolene","B":"Neostigmina","C":"Atropina","D":"Biperideno"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345725","number":"345725","sourceNumber":"345725","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São fatores que impedem o fechamento das fístulas de intestino delgado, exceto:","options":{"A":"Livre fluxo distal.","B":"Trajeto fistuloso < 2.5 cm.","C":"Alto débito (>500ml/24h).","D":"Epitelização do trajeto."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-346865","number":"346865","sourceNumber":"346865","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Os estados de hipoperfusão pós-operatório podem ocorrer nos pacientes graves. No\ndiagnóstico clínico desta condição, é CORRETO afirmar que:","options":{"A":"A hipotensão, oligúria, cianose e alterações da consciência podem ocorrer.","B":"Os critérios hemodinâmicos do choque cardiogênico são PA<80mmHg sustentada por mais de\numa hora.","C":"A função diastólica não está comprometida pela redução da complacência ventricular induzida\npela isquemia.","D":"A disfunção sistólica com aumento do débito cardíaco é responsável por uma situação de\nhiperperfusão tecidual e hipóxia celular."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-346866","number":"346866","sourceNumber":"346866","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na administração de antibioticoterapia no tratamento das infecções em cirurgia temos\nde tomar cuidado com efeitos colaterais dos\nantibióticos para evitar eventos adversos para os\npacientes. Nesse sentido, analise as afirmativas a seguir: I- A oxacilina pode causar nefrite\nintersticial. II- As quinolonas podem causar colite pseudomembranosa. III- Os aminoglicosídeos\npodem causar nefro e ototoxicidade. IV- A vancomicina pode causar reação histamínica e\nnefrotoxicidade. Estão CORRETAS as afirmativas:","options":{"A":"I e II apenas.","B":"II e III apenas.","C":"II, III e IV apenas.","D":"I, II, III e IV."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-321185","number":"321185","sourceNumber":"321185","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Analise as assertivas a seguir: I- Hérnia inguinal direta ocorre pela persistência do\nconduto peritônio-vaginal. PORQUE II- Nessa hérnia o\nsaco herniário encontra-se medial aos vasos\nepigástricos inferiores. Após análise das assertivas, assinale a alternativa CORRETA:","options":{"A":"I e II são verdadeiras e II justifica a I.","B":"I e II são verdadeiras, mas II não justifica a I.","C":"I é falsa e II é verdadeira.","D":"I é verdadeira e II é falsa."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345728","number":"345728","sourceNumber":"345728","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na avaliação pré-anestésica em que se visualize apenas o palato duro, e o palato mole\né totalmente não visível é classificada por Mallampati em:","options":{"A":"I","B":"II","C":"IV","D":"III"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-345729","number":"345729","sourceNumber":"345729","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Assinale a correta:","options":{"A":"A hérnia inguinal dos pacientes pediátricos tem como fisiopatologia a persistência do conduto\nperitônio-vaginal, diferente da hérnia dos pacientes adultos em que a grande maioria pode se\nencontrar uma fraqueza da parede abdominal.","B":"A hérnia inguinal dos pacientes pediátricos tem como fisiopatologia a fraqueza da parede\nabdominal, diferente da hérnia dos pacientes\nadultos em que a grande maioria pode se encontrar a\npersistência do conduto peritônio-vaginal.","C":"Das hérnias da região inguinal, a hérnia femoral é a mais frequente, muito mais comum na\npopulação masculina.","D":"As hérnias inguinais dos pacientes pediátricos, em que há manutenção da anatomia dos anéis\ninguinais interno e externo são classificadas por Nyhus em IIIA."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-320454","number":"320454","sourceNumber":"320454","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Durante o tratamento cirúrgico de uma hérnia em topografia inguinal encarcerada à\ndireita em uma mulher, após a inguinotomia, o cirurgião observa que o conteúdo herniário passa\npor baixo do ligamento inguinal. Levando-se em consideração o tipo de hérnia encontrada, onde\ndeve ser realizado o principal ponto de fixação durante o reparo, considerando a técnica cirúrgica\nmais amplamente aceita, para que seja o mais efetivo e reduza o risco de recorrência?","options":{"A":"Músculo obliquo externo.","B":"Músculo oblíquo interno.","C":"Ligamento inguinal.","D":"Ligamento pectíneo.","E":"Ligamento obturador."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-314016","number":"314016","sourceNumber":"314016","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias são um problema de saúde comum; entretanto, sua verdadeira incidência\nnão é conhecida. Calcula-se que 5% da\npopulação venha a desenvolver uma hérnia da parede\nabdominal, mas a prevalência pode ser mesmo mais alta. Com relação aos quadros de hérnia\nabdominal e sua anatomia, assinalar a alternativa CORRETA:","options":{"A":"O saco herniário inguinal direto passa do anel inguinal interno obliquamente em direção ao anel\ninguinal externo e, por fim, para o escroto.","B":"O saco de uma hérnia inguinal indireta faz protrusão para fora e para adiante e é medial ao anel\ninguinal interno e aos vasos epigástricos inferiores.","C":"Uma hérnia inguinal indireta é a hérnia mais comum, independentemente do sexo.","D":"Os limites do canal de Guyon são o trato iliopúbico, anteriormente; o ligamento de Cooper,\nposteriormente; e a veia femoral, lateralmente.","E":"Tanto as hérnias inguinais indiretas como as hérnias femorais ocorrem mais comumente no lado\nesquerdo."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-314018","number":"314018","sourceNumber":"314018","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A cirurgia ambulatorial pode ser realizada em salas de operação vinculadas a um\ngrande hospital, em um centro de cirurgia\nambulatorial independente, ou mesmo no consultório do\nmédico. A avaliação pré-operatória do paciente, em geral, é realizada em base ambulatorial, sendo\nexigida maior coordenação pelo cirurgião para assegurar que essa avaliação seja completada e\nfuncione de maneira conveniente. Com relação a condição(ões) para a(s) qual(is) a avaliação\n\npré-operatória pode ser recomendada antes do dia da operação, assinalar a alternativa CORRETA:","options":{"A":"Hipertensão controlada.","B":"Pacientes que terminaram quimioterapia há mais de 6 meses.","C":"Diabetes melito insulino-dependente.","D":"Cifose ou escoliose, causando ou não comprometimento funcional.","E":"Arritmias assintomáticas."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-314019","number":"314019","sourceNumber":"314019","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação às complicações da ferida cirúrgica, analisar os itens abaixo: I. O seroma\né a coleção de gordura liquefeita, soro e\nliquido linfático que se forma sob a incisão. O líquido, em\ngeral, é claro, amarelado e um tanto quadro viscoso, e encontra-se na camada subcutânea (SC),\nlogo abaixo da derme. II. O hematoma é uma coleção anormal de sangue, geralmente na camada\nsubcutânea de uma incisão recente ou em um espaço potencial na cavidade abdominal após\nexérese de um órgão. Os seromas são mais preocupantes do que os hematomas, em virtude do\nseu potencial para infecções secundárias. III. Deiscência da ferida é a separação das camadas\nmusculoaponeuróticas no início do curso pós-operatório. Está entre as mais temidas complicações\nenfrentadas pelos cirurgiões, por causa da possibilidade de deiscência repetida, infecção da ferida\ncirúrgica e formação de hérnia incisional. Está(ão) CORRETO(S)?","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente o item III.","D":"Somente os itens I e III.","E":"Somente os itens II e III."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-313286","number":"313286","sourceNumber":"313286","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação aos fios de sutura, é correto afirmar que o fio de aço é:","options":{"A":"Mineral, monofilamento.","B":"Sintético, monofilamento.","C":"Vegetal, monofilamento.","D":"Mineral, multifilamento torcido.","E":"Sintético, multifilamento trançado."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-305002","number":"305002","sourceNumber":"305002","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Quando se prescrevem 80mL/h de solução glicosada a 5%, um paciente deverá\nreceber, em 24 horas, aproximadamente,","options":{"A":"100 kcal.","B":"350 kcal.","C":"1.000 kcal.","D":"1.500 kcal."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-313287","number":"313287","sourceNumber":"313287","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Leia a descrição, abaixo: ?A sutura intradérmica é realizada por passagem do fio de\nforma horizontal, em plano mais superficial\npossível. A passagem do fio contra lateral deve ser\nrealizada no mesmo nível do término da passagem imediatamente anterior. O fio deve ser cruzado.\nO fio pode ser exteriorizado, com ou sem nó externo, nas duas extremidades. ?O excerto acima\ndiscorre sobre a/o: .? (Fonte: https://www.ucs.br/site/midia/arquivos/ebook-tecnica-\ncirurgica_2.pdf)","options":{"A":"Sutura em bolsa.","B":"Barra grega.","C":"Sutura de colchoeiro.","D":"Ponto contínuo ancorado.","E":"Ponto em U horizontal interno."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-314027","number":"314027","sourceNumber":"314027","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"De acordo com GUSSO e LOPES, em relação aos cuidados pré-operatórios, analisar\nos itens abaixo: I. Todas as comorbidades\ndevem ser verificadas quanto ao controle e\nacompanhamento clínico. II. As informações clínicas provenientes da anamnese são fundamentais\ne guiam o médico sobre a necessidade de exames complementares adicionais para a avaliação do\nrisco do paciente e a adoção de cuidados diferenciados. III. Pacientes com estenose aórtica grave,\nestase jugular, edema pulmonar e/ou terceira bulha cardíaca apresentam risco cirúrgico elevado.\n\nEstá(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-313288","number":"313288","sourceNumber":"313288","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A gordura subcutânea da região abdominal é composta por duas camadas,\nentremeadas por uma fáscia, denominada fáscia de:","options":{"A":"Buck.","B":"Scarpa.","C":"Camper.","D":"Toldt.","E":"Denonvilliers."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-305004","number":"305004","sourceNumber":"305004","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação ao diagnóstico da hérnia incisional, assinale a alternativa correta.","options":{"A":"Para se avaliar de maneira adequada a deformidade externa, o tamanho do anel herniário e do\nsaco herniário, o paciente deve ser avaliado,\ninicialmente, em decúbito dorsal.","B":"O exame complementar de escolha que deverá ser solicitado pelo médico é a radiografia\nsimples de abdome em ortostatismo e na posição\nde decúbito dorsal.","C":"Para avaliar a dinâmica do saco herniário em relação à parede abdominal, utilizam-se manobras\nde aumento da pressão abdominal, como a indução\ndo reflexo da tosse ou a manobra semiológica\nde Valsalva.","D":"Na avaliação da hérnia incisional por meio de TC de abdome, delimitam-se os segmentos da\nparede abdominal descontinuados, mas não é possível uma avaliação dos componentes dessa\nparede com precisão suficiente para definir a melhor estratégia cirúrgica."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-314030","number":"314030","sourceNumber":"314030","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à associação de vasoconstritores com os anestésicos, analisar os itens\nabaixo: I. As soluções contendo\nvasoconstritor não devem ser injetadas em áreas com circulação\nterminal, como dedos e pênis, pelo risco de ocorrer gangrena destas estruturas. II. Reações\nsistêmicas causadas pelos vasoconstritores são bastante comuns e facilmente confundidas com\nmanifestações psiquicas. Caracterizam-se por palidez e taquicardia, acompanhadas de ansiedade.\n\nIII. Em casos de doença cardiovascular grave, o uso dos vasoconstritores deve ser restringido\nsempre que possível. Esta(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-313295","number":"313295","sourceNumber":"313295","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Com relação à antibioticoprofilaxia cirúrgica, o Colégio Brasileiro de Cirurgiões ? CBC\naponta que a principal condição que favorece à resistência bacteriana é:","options":{"A":"A farmacocinética.","B":"O espectro do antibiótico.","C":"A toxicidade do fármaco.","D":"O risco de alterar a flora bacteriana.","E":"A duração da antibioticoprofilaxia."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-306720","number":"306720","sourceNumber":"306720","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"P.A.R., 58 anos, dá entrada no pronto socorro queixando-se de intensa dor abdominal,\ncom história de ter iniciado há cerca de 6\nhoras abaulamento doloroso na região inguinal direita,\ncom vermelhidão local. Relata ter apresentado episódios de vômitos escurecidos e não apresentar\na eliminação de flatos e fezes. De acordo com o quadro clínico apresentado, assinale a alternativa\ncorreta:","options":{"A":"Neste caso não deveremos pensar em obstrução intestinal, pois esta complicação somente\nocorreria no caso de a hérnia acontecer do lado esquerdo","B":"O paciente deverá ser encaminhado para tratamento cirúrgico de urgência de hérnia\ninguinocrural estrangulada.","C":"Deverá ser tentada a redução manual de hérnia em sala de procedimentos, e caso não seja\npossível, o paciente deverá ser encaminhado ao centro cirúrgico","D":"Caso o paciente permaneça estável durante observação por 6 horas, deverá ser realizada a\nredução manual da hérnia e seguimento no ambulatório"},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-291945","number":"291945","sourceNumber":"291945","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre a prevenção de infecção em cirurgias e a antibióticoprofilaxia, analise as\nafirmativas a seguir: I- O preparo do\npaciente evolve banho com água e sabão na noite anterior ou\nna manhã do procedimento, associado a degermação próxima a incisão cirúrgica. II- O controle\nmetabólico do paciente com manutenção de hipotermia no perioperatório (tax < 35,5Cº) e glicemia\nabaixo de 180mgr/dl e otimização da oxigenação tecidual. III- Antibióticoprofilaxia quando indicada\ndeve ser administrado 1 a 2 horas antes do procedimento e descontinuado em 24 horas. Está(ão)\nCORRETA(S) a(s) afirmativa(s):","options":{"A":"III apenas.","B":"II e III apenas.","C":"I e III apenas.","D":"I, II e III."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-291952","number":"291952","sourceNumber":"291952","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Analise a proposição e a razão a seguir: PROPOSIÇÃO: A analgesia peridural reduz o\ninfarto agudo do miocárdio intra e pós-operatório. RAZÃO: Porque a analgesia reduz efeitos da dor\nno pós-operatório diminuindo hipertensão, arritmias, reduzindo aumento do trabalho cardíaco e\nconsequentemente o consumo de oxigênio.","options":{"A":"A proposição é uma afirmativa verdadeira e a razão uma afirmativa falsa.","B":"A proposição é uma afirmativa falsa e a razão uma afirmativa verdadeira.","C":"A proposição e a razão são ambas afirmativas falsas.","D":"A proposição é uma afirmativa correta e a razão uma afirmativa verdadeira e realmente a causa\ndesse efeito."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-291648","number":"291648","sourceNumber":"291648","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 75 anos de idade, encontra-se no vigésimo dia pós-operatório de\nlaparotomia exploradora devido abdome agudo inflamatório por diverticulite. Evoluiu com\nbroncopneumonia aspirativa na indução anestésica, necessitando de ventilação mecânica e\ncuidados de terapia intensiva. Há 7 dias, foi extubado e, no momento, está sem drogas vasoativas\ncom pressão em níveis de normalidade, afebril, recebendo dieta enteral e com hemocultura\nnegativa, mas swab positivo para cândida. O leucograma está normalizado. Está completando\ncatorze dias de meropenem e vancomicina. Considerando o caso clínico, assinale a alternativa\ncorreta:","options":{"A":"O swab positivo para cândida da paciente indica tratamento com antifúngico EV, pois, mesmo\nclinicamente melhor, trata-se de infecção grave.","B":"O swab positivo com hemocultura negativa não indica tratamento com antifúngico EV.","C":"Em estando a hemocultura negativa, o swab positivo só indicará tratamento com antifúngico EV\ncaso seja repetido em 72h e se mantenha\npositivo em pelo menos duas amostras.","D":"Por se tratar de paciente idoso já em uso de meropenem e vancomicina, não estaria indicado o\ntratamento com antifúngico EV, mesmo se a hemocultura viesse positiva, devido à alta toxicidade\ndo esquema terapêutico.","E":"Devido swab positivo para cândida, está indicado tratamento antifúngico EV profilático por se\ntratar de infecção muito grave."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-291649","number":"291649","sourceNumber":"291649","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 60 anos submetido a hernioplastia a Lichtenstein. No décimo dia de\npós-operatório ele procura pronto socorro devido febre 38,7°C, ferida operatória com sinais\nflogísticos e saída de secreção purulenta. Ele está com frequência cardíaca de 106 bpm, frequência\nrespiratória de 32 irpm e pressão arterial de 80/60 mmHg. Ao retirar um ponto da ferida operatória\nnotou-se saída de pus com gás de permeio. Após a ressucitação volêmica a conduta adotada deve\nser:","options":{"A":"Cirurgia com retirada de tela, irrigação de loja infectada e colocação de nova tela no mesmo\ntempo cirúrgico para evitar recidiva de hérnia.","B":"Abertura de todos os pontos da incisão com drenagem, antibioticoterapia e ressutura.","C":"Cirurgia com retirada da tela e desbridamento de todo tecido desvitalizado e antibioticoterapia.","D":"Antibioticoterapia endovenosa e observação clínica.","E":"Drenagem guiada por ultrassom e antibioticoterapia."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283882","number":"283882","sourceNumber":"283882","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher de 35 anos será submetida à colecistectomia videolaparoscópica eletiva devido\nà colecistite crônica calculosa. Na avaliação\npré-operatória desta paciente, que não apresenta\noutros sintomas, exceto dor abdominal após ingesta alimentar, qual das alternativas abaixo está\ncorreta?","options":{"A":"Rotina laboratorial pré-operatória não reduz risco de complicações perioperatórias.","B":"História clínica direcionada a sangramentos não prediz sangramento cirúrgico.","C":"Realização de eletrocardiograma pré-operatório está sempre indicado.","D":"Introdução pré-operatória de um betabloqueador reduz o risco de complicações cardíacas\nperioperatórias.","E":"Introdução pré-operatória de um inibidor da enzima de conversão da angiotensina (I-ECA) reduz\no risco de complicações cardíacas\nperioperatórias."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-287324","number":"287324","sourceNumber":"287324","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em um processo de cicatrização de uma ferida cirúrgica da parede abdominal, o que é\numa Deiscência?","options":{"A":"Corresponde ao afastamento parcial ou total de um ou todos planos de sutura, devido à abertura\nespontânea de pontos cirúrgicos ao longo da linha de incisão cirúrgica.","B":"Corresponde ao afastamento dos planos profundos da parede abdominal permanecendo a pele\níntegra.","C":"Corresponde à visualização do conteúdo abdominal através de uma abertura da linha de incisão\ncirúrgica.","D":"Corresponde à dificuldade de aproximação dos planos de uma ferida, não sendo possível\nrealizar a sutura."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-287840","number":"287840","sourceNumber":"287840","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação às hérnias abdominais, assinalar a alternativa que apresenta o tipo mais\ncomum tanto em homens adultos quanto em mulheres adultas:","options":{"A":"Hérnia inguinal indireta.","B":"Hérnia inguinal direta.","C":"Hérnia umbilical.","D":"Hérnia epigástrica.","E":"Hérnia de Spiegel."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-257342","number":"257342","sourceNumber":"257342","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Homem de 65 anos apresenta queda da própria altura e é levado ao pronto\natendimento. É portador de hipertensão\narterial sistêmica e fibrilação atrial. Faz uso irregular de\nhidroclorotiazida, enalapril, anlodipino, clonidina e rivaroxabana. Ao exame físico, PA: 226 X 122\nmmHg, FC: 102 bpm, FR: 22 ipm. Apresenta-se sonolento, abre os olhos, verbaliza ao chamado e\nobedece aos comandos. Apresenta redução da força no dimidio esquerdo. Sem outras\nanormalidades. Após 4 dias de permanência no CTI, o paciente apresentou rebaixamento do nível\nda consciência, e foi indicada a intubação orotraqueal por sequência rápida. Assinale a alternativa\nque apresenta a prescrição MAIS ADEQUADA para a sequência rápida nesse paciente:","options":{"A":"Fentanil, etomidato e rocurônio.","B":"Fentanil, midazolam e succinilcolina.","C":"Lidocaína, propofol e rocurônio.","D":"Quetamina e succinilcolina."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-3/257342.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-287328","number":"287328","sourceNumber":"287328","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente diabético, obeso, 63 anos, foi submetido a uma cirurgia abdominal por\nneoplasia de cólon, com duração de 06 horas.\nDas alternativas abaixo, qual NÃO é fator de risco de\ninfecção de um sítio cirúrgico?","options":{"A":"Tempo de cirurgia.","B":"Ser cirurgia de cólon.","C":"Ser diabético e obeso.","D":"Ser idoso."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-287843","number":"287843","sourceNumber":"287843","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Conforme GUSSO e LOPES, em relação aos cuidados pré-operatórios, analisar a\nsentença abaixo: A anamnese no perioperatório\ndeve ser ampla e ativa, uma vez que dados\nrelevantes, muitas vezes, não estão associados à doença cirúrgica do paciente (1ª parte). O exame\nclínico compõe uma parte importante da avaliação pré-operatória, possibilitando verificar a\npresença de comorbidades, os sinais de risco e excluir as condições graves (2ª parte). Todas as\ncomorbidades devem ser verificadas quanto ao controle e acompanhamento clínico. Deve-se dar\nenfoque especial à presença de condições potencialmente graves, como diabetes, doença vascular\nperiférica, acidente vascular cerebral, insuficiência renal e doença pulmonar (3ª parte). A sentença\nestá:","options":{"A":"Totalmente correta.","B":"Correta somente em sua 3ª parte.","C":"Correta somente em suas 1ª e 2ª partes.","D":"Correta somente em suas 2ª e 3ª partes.","E":"Totalmente incorreta."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283897","number":"283897","sourceNumber":"283897","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação à profilaxia sistêmica antimicrobiana para prevenção de Infecção do Sítio\nCirúrgico (ISC), assinale a alternativa correta.","options":{"A":"A classificação da ferida cirúrgica (limpa, potencialmente contaminada, contaminada, infectada)\né o único critério a ser considerado para\ndeterminar o emprego do antibiótico profilático.","B":"Antibióticos profiláticos só deverão ser administrados em cirurgias contaminadas.","C":"Os antibióticos devem ser administrados pré-operatoriamente 1 dia antes da cirurgia.","D":"Antibiótico profilático pode ser utilizado em cirurgias limpas, caso o paciente possua uma\nprótese.","E":"Nenhuma das anteriores."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283898","number":"283898","sourceNumber":"283898","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Dos fios abaixo, qual é considerado um fio absorvível?","options":{"A":"Vicryl.","B":"Mersilene.","C":"Prolene.","D":"Gore-tex.","E":"Nylon."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283899","number":"283899","sourceNumber":"283899","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 32 anos apresenta quadro clínico de apendicite aguda e é submetido à\napendicectomia videolaparoscópica. Durante o ato anestésico, apresenta taquicardia, labilidade\npressórica, sudorese, rigidez de membros inferiores e hipertemia progressiva. O diagnóstico deste\npaciente foi de hipertemia maligna. Qual medicação deve ser administrada?","options":{"A":"Atropina.","B":"Dantrolene.","C":"Flumazenil.","D":"Naloxona.","E":"Midazolan."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283900","number":"283900","sourceNumber":"283900","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"De acordo com a classificação da Sociedade Americana de Anestesiologia (ASA\nClassification), que categorizou as comorbidades pré-operatórias dos pacientes, paciente com\ndoença sistêmica grave, que resulta em comprometimento funcional, cujos exemplos são diabetes\nmellitus com complicações vasculares, infarto do miocárdio prévio e hipertensão não controlada, é\nclassificado como:","options":{"A":"ASA II.","B":"ASA III.","C":"ASA IV.","D":"ASA V.","E":"ASA VI."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283904","number":"283904","sourceNumber":"283904","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hérnia que se apresenta entre a linha semilunar (que marca a transição do músculo\npara a aponeurose no músculo transverso\nabdominal) e a borda lateral do músculo reto, logo\nabaixo da linha arqueada de Douglas, é chamada de:","options":{"A":"Hérnia de Spiegel.","B":"Hérnia Lombar.","C":"Hérnia Obturador.","D":"Hérnia Perineal.","E":"Hérnia Umbilical."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-283921","number":"283921","sourceNumber":"283921","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Na alta hospitalar de um paciente pediátrico em pós-operatório de\nadenoamigdalectomia, o medicamento\nCONTRAINDICADO para analgesia em ambiente domiciliar\né:","options":{"A":"Dipirona.","B":"Ibuprofeno.","C":"Cetoprofeno.","D":"Codeína.","E":"Quetamina."},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-266398","number":"266398","sourceNumber":"266398","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente masculino, 40 anos, com dor abdominal de forte intensidade há 24 horas,\nmais intensa em fossa ilíaca esquerda,\nacompanhada de distensão abdominal e vômitos fecaloides.\nAo exame físico, o paciente se encontrava taquicárdico, com distensão abdominal importante, sem\nirritação peritoneal e observou-se presença de hérnia inguinal esquerda, irredutível às manobras,\ncom dor importante à manipulação. O raio X de abdome evidenciou distensão de alças de intestino\ndelgado, com a presença de níveis hidroaéreos. O exame laboratorial evidenciou leucocitose com\ndesvio à esquerda. Durante a fase de hidratação e início de antibioticoterapia, o médico foi\ninformado pelo enfermeiro que a hérnia havia reduzido de forma espontânea. Ao examinar o\npaciente, o médico confirma a redução espontânea do material herniado. Qual a melhor conduta\ndiante dessa nova situação clínica?","options":{"A":"Manter o paciente em observação na unidade de pronto atendimento e após 6 horas, se\nmantiver o atual exame físico, dar alta para o domicílio com antibiótico oral.","B":"Dar alta para o domicílio com orientações dietéticas.","C":"Encaminhar o paciente para cirurgia de urgência, apesar da redução espontânea da hérnia.","D":"Dar alta para o domicílio e orientar procurar o serviço de cirurgia geral ambulatorialmente."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-255627","number":"255627","sourceNumber":"255627","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Há alguns meses João, de 44 anos, vem notando um abaulamento em sua região\ninguinal direita, especialmente após esforço físico. Sobre as hérnias de parede abdominal,\npodemos afirmar que. MARQUE A CORRETA:","options":{"A":"A distinção entre hérnia inguinal direta ou indireta é de pouca importância, pois o reparo\ncirúrgico\ndesses tipos de hérnias é semelhante.","B":"O estrangulamento das hérnias femorais é raro, podendo ser reparada em caráter eletivo.","C":"A ultrassonografia não costuma ajudar no diagnóstico de hérnia inguinal devido ao seu baixo\ngrau de sensibilidade e especificidade.","D":"A estratégia de espera vigilante em detrimento ao reparo profilático da hérnia inguinal não é\nsegura para pacientes mais idosos com hérnia assintomática."},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-255631","number":"255631","sourceNumber":"255631","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"O objetivo da avaliação pré-operatória não é procurar extensivamente por doenças não\ndiagnosticadas, mas identificar e quantificar qualquer comorbidade que possa afetar o resultado\ncirúrgico. Marque a alternativa que classifica CORRETAMENTE o paciente como estágio III na\nAvaliação do estado físico da American Society of Anesthesiologists ? ASA:","options":{"A":"Leve a moderado distúrbio fisiológico, controlado. Sem comprometimento da atividade normal. A\ncondição pode afetar a cirurgia ou anestesia.","B":"Desordem sistêmica severa, potencialmente letal, com grande impacto sobre a anestesia e\ncirurgia.","C":"Distúrbio sistêmico importante, de difícil controle, com comprometimento da atividade normal e\ncom impacto sobre a anestesia e cirurgia.","D":"Moribundo. A cirurgia é a única esperança para salvar a vida."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-255632","number":"255632","sourceNumber":"255632","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As complicações cirúrgicas ainda são um aspecto frustrante e difícil do tratamento\noperatório dos pacientes e, a despeito da\nhabilidade técnica do cirurgião, constituem uma\npossibilidade real no dia a dia do profissional. Dentre às complicações de feridas cirúrgicas que\npodem ser abordadas APENAS em centros cirúrgicos, MARQUE A CORRETA:","options":{"A":"Seroma localizado.","B":"Deiscência de feridas de incisões abdominais recentes.","C":"Infecções superficiais do sítio cirúrgico.","D":"Pequeno hematoma associado ao uso de antiplaquetários."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-255636","number":"255636","sourceNumber":"255636","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mariana, residente médica de Medicina de Família e Comunidade, está acompanhando\no cirurgião geral do Hospital Estadual\nreferência de sua cidade. Sobre as etapas da técnica de\ntratamento de ferimentos cutâneos, MARQUE A CORRETA:","options":{"A":"O anestésico deve ser aplicado de preferência pelo bordo do ferimento, sendo que a utilização\ndo vasoconstritor independe do tecido a ser\ninfiltrado.","B":"A antissepsia deve incluir a limpeza cuidadosa da pele ao redor da lesão, de preferência com\ngluconato de clorexidina mais álcool etílico, ou com sabão neutro.","C":"O primeiro ponto da camada mais profunda deve ser dado marginalmente para garantir a\nadequada aposição das margens do ferimento.","D":"As colas e fitas adesivas estão indicadas para o fechamento de ferimentos menores que 7 cm."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-234437","number":"234437","sourceNumber":"234437","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre a anatomia e cirurgia da hérnia inguinal, assinale a alternativa CORRETA:","options":{"A":"O nervo íleo hipogástrico é um dos componentes do funículo espermático.","B":"As hérnias diretas são laterais aos vasos epigástricos.","C":"O canal inguinal tem como assoalho a fáscia transversal e o teto a aponeurose do oblíquo\nexterno.","D":"O triângulo de Hasselbach tem como limites os vasos epigástricos, o ligamento de Cooper e a\nborda medial do reto."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-232144","number":"232144","sourceNumber":"232144","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As fístulas são complicações relacionadas à cirurgia do trato gastrointestinal, sendo\nresponsáveis por um aumento significativo na morbidade e mortalidade desses pacientes. São\nfatores que influenciam de maneira favorável o fechamento das mesmas:","options":{"A":"Localização em intestino delgado distal, apresentação crônica e associação com doença\ninflamatória intestinal.","B":"Localização em intestino delgado distal, trajeto curto e débito menor que 500 ml por dia.","C":"Localização em intestino delgado distal, sinais de sub-oclusão e débito maior que 500 ml por\ndia.","D":"Localização em esôfago cervical, trajeto longo e débito menor que 500 ml por dia.","E":"Localização no esôfago cervical, história de radioterapia prévia e ausência de desnutrição."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-232153","number":"232153","sourceNumber":"232153","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Avalie os quadros abaixo descritos e sua respectiva classificação, conforme Nyhus. I.\nPaciente de 22 anos, submetido à hernioplastia inguinal direita com evidência de anel inguinal\ninterno dilatado, mas com parede posterior intacta. Classifiação de Nyhus: Tipo II. II. Paciente de\n73\nanos, submetido à hernioplastia inguinal esquerda com evidência de anel inguinal interno dilatado,\ncom importante deformidade da parede posterior. Classificação de Nyhus: Tipo III A. III. Paciente de\n4 anos, submetido à hernioplastia inguinal direita com evidência de anel inguinal interno normal.\n\nClassificação de Nyhus: Tipo I C. IV. Paciente de 36 anos, submetida à correção em urgência de\nhérnia femoral encarcerada. Classificação de Nyhus: Tipo III C. Assinale a alternativa correta que\ndemonstra se a associação é verdadeira (V) ou falsa (F):","options":{"A":"V, V, V, V","B":"F, F, V, V","C":"F, V, F, V","D":"V, F, V, F","E":"V, F, F, V"},"answer":"E","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-246772","number":"246772","sourceNumber":"246772","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Paciente de 65 anos, ex-tabagista (parou há 6 meses), foi submetido a hernioplastia\ninguinal direita. Durante a cirurgia foi\nidentificado anel herniário medial aos vasos epigástricos\ninferiores. Quais afirmativas abaixo são verdadeiras em relação ao caso do enunciado: I - Essa é\numa hérnia inguinal direta; II - Essa é uma hérnia inguinal indireta; III - A hérnia ocorreu no\ntriângulo\nde Hesselbach; IV - A classificação dessa hérnia é Nyhus IIIc; V - É recomendado que o reparo da\nhérnia seja realizado com a utilização de Tela","options":{"A":"II, IV, V","B":"I, III, IV","C":"I, III, V","D":"II, III, V","E":"II, IV, V"},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-246773","number":"246773","sourceNumber":"246773","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Dentre as afirmações abaixo, quais são falsas (F) e quais são verdadeiras (V): ( ) I - A\nhérnia de Amyand é caracterizada pela presença do apêndice cecal no interior do saco herniário\ninguinal. ( ) II - A hérnia de Spiegel localiza - se ao nível da linha arqueada. ( ) III - A hérnia\nde Littre\né caracterizada pela presença do divertículo de Meckel no interior do saco herniário. ( ) IV - A\nhérnia de Richter é caracterizada pela presença de alça intestinal no saco herniário causando\nobstrução intestinal.","options":{"A":"V, F, V, F","B":"V, V, F, V","C":"F, F, V, F","D":"F, V, F, V","E":"V, V, V, F"},"answer":"A","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-243042","number":"243042","sourceNumber":"243042","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"São diretrizes do pré-operatório imediato em pacientes que serão submetidos a cirurgia\nplástica reparadora pós cirurgia bariátrica as seguintes alternativas, EXCETO:","options":{"A":"iniciar massageamento pneumático de membros inferiores, confirmar plano anestésico e checar\nmedicamentos/ equipamentos e iniciar profilaxia antibiótica antes da incisão.","B":"iniciar profilaxia antibiótica antes da incisão, checar instrumental de sala e funcionamento dos\nequipamentos indicados e iniciar profilaxia antibiótica antes da incisão.","C":"sondagem vesical de demora com sistema coletor fechado, iniciar a quimioprofilaxia da TVP em\ncasos indicados e iniciar profilaxia\nantibiótica antes da incisão.","D":"iniciar profilaxia antibiótica antes da incisão, verificar medicações em uso e identificar\nalergias e\npreparar material para mudança de decúbito e coxins acolchoados.","E":"iniciar a prevenção de hipotermia, sondagem vesical de demora com sistema coletor fechado e\niniciar profilaxia antibiótica antes da incisão."},"answer":"C","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-196729","number":"196729","sourceNumber":"196729","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Em relação ao preparo do cólon no pré-operatório de ressecções colorretais eletivas,\nestá correto.","options":{"A":"As soluções de polietilenoglicol podem induzir hiperfosfatemia, hipernatremia, hipopotassemia e\nhipocalcemia.","B":"As soluções de fosfato de sódio são indicadas em pacientes com insuficiência renal, cirrose,\nascite ou insuficiência cardíaca.","C":"Solução de manitol a 10% é a mais indicada para pacientes com obstrução do cólon.","D":"A incidência de deiscência das anastomoses pode ser menor quando não se faz o preparo\nmecânico do cólon."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-196747","number":"196747","sourceNumber":"196747","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Um paciente de 50 anos, bom estado geral, interna-se para a terceira laparotomia, para\ntratamento de obstrução intestinal; a cirurgia inicial foi uma apendicectomia. A operação foi\ntecnicamente difícil devido extensas aderências; havia obstrução no íleo, a cerca de 30 cm do ceco,\nsendo necessário ressecção de segmento de 10 cm. No sexto dia de pós-operatório surge\ndrenagem de secreção digestiva na cicatriz cirúrgica; são retirados alguns pontos da pele e\nidentifica-se deiscência da parede e visualização da alça ileal e deiscência parcial da anastomose,\ncom cerca de 0,5 cm de diâmetro; a alça está completamente bloqueada e a secreção digestiva é\ntotalmente eliminada através da parede abdominal. Neste momento e 24 horas após não existem\nmanifestações sistêmicas de infecção nem sinais de irritação peritoneal. O débito pela fístula foi\nde\n\n1.200 ml em 24 horas. Em relação ao tratamento deste paciente está correto.","options":{"A":"Indica-se sutura imediata da deiscência da anastomose na própria enfermaria.","B":"Reposição de fluidos é prioridade neste momento.","C":"Indica-se nutrição enteral com dieta oligomérica.","D":"Nutrição parenteral e octreotide proporcionarão fechamento espontâneo."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-196754","number":"196754","sourceNumber":"196754","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Qual das condutas abaixo não tem sido considerada eficiente para reduzir a incidência\nde infecção do sítio cirúrgico nas cirurgias\neletivas?","options":{"A":"Suspensão do cigarro por pelo menos um mês antes da cirurgia.","B":"Redução de peso dos obesos, quando há tempo disponível.","C":"Preparo da pele com agentes antissépticos no momento da operação.","D":"Descolonizar os portadores de S. aureus com antibióticos ativos contra MRSA."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-196801","number":"196801","sourceNumber":"196801","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"As hérnias da parede Abdominal que ocorrem na linha arqueada ou abaixo dela são\ndenominadas:","options":{"A":"Laterais.","B":"Spiegel.","C":"Mayo.","D":"Ventro-lateral."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-196739","number":"196739","sourceNumber":"196739","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"A hérnia com anel inguinal interno dilatado invadindo os limites medialmente ou\ndestruindo a fáscia transversalis do\ntrígono de Hesselbach (Inguinal), segundo a classificação de\nLoyd Nyhus, é do tipo:","options":{"A":"I.","B":"II.","C":"III A.","D":"III B."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-212966","number":"212966","sourceNumber":"212966","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Mulher, 29 anos, com queixa de abaulamento em região inguinal esquerda que aparece\ne dói durante atividade física, é submetida\na cirurgia para correção de hérnia. Durante a cirurgia é\nidentificado anel herniário medial aos vasos epigástricos. Qual o tipo de hérnia? Qual a\nclassificação dessa de Nyhus?","options":{"A":"Hérnia indireta. Nyhus tipo II.","B":"Hérnia direta. Nyhus tipo III A.","C":"Hérnia indireta. Nyhus tipo III B.","D":"Hérnia direta. Nyhus tipo I.","E":"Hérnia indireta. Nyhus IV."},"answer":"B","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-3-220321","number":"220321","sourceNumber":"220321","collectionBlock":"medcurso:medcurso-cirurgia-cir-3","collectionLabel":"Medcurso · CIR 3","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 3","subtopic":"","stem":"Sobre o uso de antibioticoprofilaxia em cirurgia, assinale a alternativa CORRETA:","options":{"A":"Nas cirurgias limpas, não é indicado o uso de antibióticos para esses fins.","B":"Nas cirurgias de esôfago e de histerectomias, não é necessária a prescrição de\nantibioticoprofilaxia.","C":"Nas cirurgias, como as de peritonites, está indicado o uso de antibioticoprofilaxia.","D":"Nas cirurgias plásticas, está indicada a antibioticoprofilaxia em descolamentos grandes de\n\ntecidos e uso de próteses."},"answer":"D","source":"Cirurgia/CIR 3/CIR 3.txt","sourceLabel":"Medcurso · CIR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
